        /// <summary>
        /// Internal buffer used to marshal results efficiently from the native engine.
        /// </summary>
        [StructLayout(LayoutKind.Sequential)]
        internal struct PhysicsBuffer2D : IDisposable
        {
            /// <undoc/>
            public readonly IntPtr buffer => m_Buffer;

            /// <undoc/>
            public readonly int size => m_Size;

            /// <undoc/>
            public readonly Allocator allocator => m_Allocator;

            /// <undoc/>
            public PhysicsBuffer2D()
            {
                m_Buffer = IntPtr.Zero;
                m_Size = 0;
                m_Allocator = Allocator.None;
            }

            /// <undoc/>
            public PhysicsBuffer2D(IntPtr buffer, int size, Allocator allocator)
            {
                m_Buffer = buffer;
                m_Size = size;
                m_Allocator = allocator;
            }

            /// <undoc/>
            public static unsafe PhysicsBuffer2D FromNativeArray<T>(NativeArray<T> nativeArray) where T : struct
            {
                return new PhysicsBuffer2D((IntPtr)nativeArray.GetUnsafePtr(), nativeArray.Length, Allocator.None);
            }

            /// <undoc/>
            public static unsafe PhysicsBuffer2D FromSpan<T>(ReadOnlySpan<T> span) where T : unmanaged
            {
                fixed (T* addr = span)
                {
                    return new PhysicsBuffer2D((IntPtr)addr, span.Length, Allocator.None);
                }
            }

            /// <undoc/>
            public readonly unsafe NativeArray<T> ToNativeArray<T>() where T : struct
            {
                if (m_Size == 0)
                    return new NativeArray<T>();

                var nativeArray = NativeArrayUnsafeUtility.ConvertExistingDataToNativeArray<T>(dataPointer: m_Buffer.ToPointer(), length: m_Size, allocator: m_Allocator);
                var safetyHandle = (m_Allocator == Allocator.Temp) ? AtomicSafetyHandle.GetTempMemoryHandle() : AtomicSafetyHandle.Create();
                NativeArrayUnsafeUtility.SetAtomicSafetyHandle(ref nativeArray, safetyHandle);
                return nativeArray;
            }

            /// <undoc/>
            public readonly unsafe Span<T> ToSpan<T>() where T : struct
            {
                return new Span<T>(m_Buffer.ToPointer(), m_Size);
            }

            /// <undoc/>
            public readonly unsafe ReadOnlySpan<T> ToReadOnlySpan<T>() where T : struct => new ReadOnlySpan<T>(m_Buffer.ToPointer(), m_Size);

            /// <undoc/>
            public unsafe readonly T AsEngineObject<T>(int index) where T : class
            {
                if (index < 0 || index >= size)
                    throw new ArgumentOutOfRangeException("Index argument is invalid.", nameof(index));

                var entityId = UnsafeUtility.ArrayElementAsRef<EntityId>(m_Buffer.ToPointer(), index);
                return Resources.EntityIdIsValid(entityId) ? Resources.EntityIdToObject(entityId) as T : null;
            }

            /// <undoc/>
            public unsafe readonly T As<T>(int index) where T : struct
            {
                if (index < 0 || index >= size)
                    throw new ArgumentOutOfRangeException("Index argument is invalid.", nameof(index));

                return UnsafeUtility.ArrayElementAsRef<T>(m_Buffer.ToPointer(), index);
            }

            /// <summary>
            /// This should NOT be called if a NativeArray or Span are currently active and being accessed otherwise bad things will happen.
            /// Typically, the NativeArray should be disposed of but in other cases, this can be used.
            /// </summary>
            public unsafe void Dispose()
            {
                if (m_Buffer == null || m_Size == 0)
                    return;

                // Free the allocation.
                UnsafeUtility.FreeTracked(m_Buffer.ToPointer(), m_Allocator);
                m_Buffer = IntPtr.Zero;
                m_Size = 0;
                m_Allocator = Allocator.None;
            }

            /// <undoc/>
            public readonly bool IsEmpty => m_Size == 0;

            /// <undoc/>
            public readonly bool IsValid => !IsEmpty;

            /// <undoc/>
            public readonly override string ToString() { return $"size={m_Size}, allocator={m_Allocator}"; }

            #region Internal

            IntPtr m_Buffer;
            int m_Size;
            Allocator m_Allocator;

            #endregion
        }

        /// <summary>
        /// Internal buffer pair used to marshal results efficiently from the native engine.
        /// </summary>
        [StructLayout(LayoutKind.Sequential)]
        internal readonly struct PhysicsBufferPair2D
        {
            #region Internal

            /// <undoc/>
            public readonly PhysicsBuffer2D buffer1;

            /// <undoc/>
            public readonly PhysicsBuffer2D buffer2;

            #endregion
        }
    }

    #region Object Arrays

    ///<summary>A collection of Collider2D.</summary>
    ///<remarks>The collection of <see cref="Collider2D" /> can be enumerated using "foreach" or its contents accessed via an indexer. The collection does not allocate any managed memory but must be disposed of.
    ///
    ///This collection can only be created by Unity and is typically returned as results from physics queries.</remarks>
    [StructLayout(LayoutKind.Sequential)]
    public struct ColliderArray2D : IEnumerable<Collider2D>, IDisposable
    {
        internal ColliderArray2D(PhysicsBuffer2D physicsBuffer)
        {
            m_PhysicsBuffer = physicsBuffer;
        }

        ///<summary>The number of <see cref="Collider2D" /> elements in the collection.</summary>
        public readonly int Length => m_PhysicsBuffer.size;
        ///<summary>An indexer allowing access to any <see cref="Collider2D" /> in the collection.</summary>
        ///<remarks>This must be in the range of 0 to <see cref="Length" />-1.</remarks>
        public readonly Collider2D this[int index] => m_PhysicsBuffer.AsEngineObject<Collider2D>(index);
        ///<summary>Disposes of the native memory allocated by the collection.</summary>
        ///<remarks>If the <see cref="Length" /> is zero, calling Dispose is optional as no memory would have been allocated in that case.</remarks>
        public void Dispose() => m_PhysicsBuffer.Dispose();

        #region Enumeration

        ///<summary>Gets an enumerator which allows iteration of the collection. This is typically used implicitly by "foreach".</summary>
        ///<returns>An ernumerator used to iterate the collection.</returns>
        public readonly IEnumerator<Collider2D> GetEnumerator() => new ColliderArrayIterator2D(this);
        readonly IEnumerator IEnumerable.GetEnumerator() => new ColliderArrayIterator2D(this);

        struct ColliderArrayIterator2D : IEnumerator<Collider2D>
        {
            public ColliderArrayIterator2D(ColliderArray2D colliderArray2D)
            {
                m_ColliderArray = colliderArray2D;
                m_Index = -1;
            }

            readonly object IEnumerator.Current => m_ColliderArray[m_Index];
            readonly Collider2D IEnumerator<Collider2D>.Current => m_ColliderArray[m_Index];

            bool IEnumerator.MoveNext()
            {
                if (m_ColliderArray.Length == 0)
                    return false;

                return ++m_Index < m_ColliderArray.Length;
            }

            void IEnumerator.Reset() => m_Index = -1;

            // Iterator does not own the buffer, nothing to dispose.
            public readonly void Dispose() { }

            #region Internal

            ColliderArray2D m_ColliderArray;
            int m_Index;

            #endregion
        }

        #endregion

        #region Internal

        PhysicsBuffer2D m_PhysicsBuffer;

        #endregion
    }

    #endregion

    #region Scene

    ///<summary>Represents a single instance of a 2D physics Scene.</summary>
    ///<remarks>A 2D physics Scene owns all 2D physics component objects added to it and can perform a simulation of them as well as execute queries against them.  All of this functionality is isolated from any other physics Scene.  Using this, multiple independent physics Scenes can coexist.</remarks>
    [NativeHeader("Modules/Physics2D/Public/PhysicsSceneHandle2D.h")]
    [StructLayout(LayoutKind.Sequential)]
    public partial struct PhysicsScene2D : IEquatable<PhysicsScene2D>
    {
        private int m_Handle;

        ///<exclude />
        public override string ToString() { return string.Format("({0})", m_Handle); }
        ///<exclude />
        public static bool operator==(PhysicsScene2D lhs, PhysicsScene2D rhs) { return lhs.m_Handle == rhs.m_Handle; }
        ///<exclude />
        public static bool operator!=(PhysicsScene2D lhs, PhysicsScene2D rhs) { return lhs.m_Handle != rhs.m_Handle; }
        ///<exclude />
        public override int GetHashCode() { return m_Handle; }
        ///<exclude />
        public override bool Equals(object other)
        {
            if (!(other is PhysicsScene2D))
                return false;

            PhysicsScene2D rhs = (PhysicsScene2D)other;
            return m_Handle == rhs.m_Handle;
        }

        public bool Equals(PhysicsScene2D other)
        {
            return m_Handle == other.m_Handle;
        }

        ///<summary>Determines whether the physics Scene is valid or not.</summary>
        ///<remarks>If the physics Scene is associated with a specific <see cref="Scene" /> which has been destroyed then the physics Scene is no longer valid.  Note that the <see cref="Physics2D.defaultPhysicsScene" /> is always valid.</remarks>
        ///<returns>True when the physics Scene valid.</returns>
        public bool IsValid() { return IsValid_Internal(this); }
        [StaticAccessor("GetPhysicsManager2D()", StaticAccessorType.Arrow)]
        [NativeMethod("IsPhysicsSceneValid")]
        extern private static bool IsValid_Internal(PhysicsScene2D physicsScene);

        ///<summary>Determines whether the physics Scene is empty or not.</summary>
        ///<returns>True when the physics Scene is empty.</returns>
        public bool IsEmpty()
        {
            if (IsValid())
                return IsEmpty_Internal(this);

            throw new InvalidOperationException("Cannot check if physics scene is empty as it is invalid.");
        }

        [StaticAccessor("GetPhysicsManager2D()", StaticAccessorType.Arrow)]
        [NativeMethod("IsPhysicsWorldEmpty")]
        extern private static bool IsEmpty_Internal(PhysicsScene2D physicsScene);

        ///<summary>The number of simulation sub-steps that occurred  during the last simulation step.</summary>
        ///<remarks>When simulation sub-stepping occurs, the number of sub-steps that run are monitored with the actual count available for analysis here. The cost of sub-stepping should be monitored with the Unity Profiler using the Physics 2D Module.</remarks>
        ///<seealso cref="Physics2D.useSubStepping" />
        ///<seealso cref="Physics2D.maxSubStepCount" />
        ///<seealso cref="Physics2D.minSubStepFPS" />
        ///<seealso cref="PhysicsScene2D.subStepLostTime" />
        public int subStepCount { get { return SubStepCount_Internal(this); } }

        [StaticAccessor("GetPhysicsManager2D()", StaticAccessorType.Arrow)]
        [NativeMethod("GetSubStepCount")]
        extern private static int SubStepCount_Internal(PhysicsScene2D physicsScene);

        ///<summary>The amount of simulation time that has been "lost" due to simulation sub-stepping hitting the maximum number of allowed sub-steps.</summary>
        ///<remarks>When simulation sub-stepping occurs, the number of sub-steps that run are limited to <see cref="Physics2D.maxSubStepCount" />. This can result is "lost" simulation time which is monitored and is available for analysis here. The cost of sub-stepping should be monitored with the Unity Profiler using the Physics 2D Module.</remarks>
        ///<seealso cref="Physics2D.useSubStepping" />
        ///<seealso cref="Physics2D.maxSubStepCount" />
        ///<seealso cref="Physics2D.minSubStepFPS" />
        ///<seealso cref="PhysicsScene2D.subStepCount" />
        public float subStepLostTime { get { return SubStepLostTime_Internal(this); } }

        [StaticAccessor("GetPhysicsManager2D()", StaticAccessorType.Arrow)]
        [NativeMethod("GetSubStepLostTime")]
        extern private static float SubStepLostTime_Internal(PhysicsScene2D physicsScene);

        // Perform a manual simulation step.
        [ExcludeFromDocs]
        public bool Simulate(float deltaTime)
        {
            return Simulate(deltaTime, Physics2D.AllLayers);
        }

        ///<summary>Simulate physics associated with this <see cref="PhysicsScene2D" />.</summary>
        ///<remarks>Calling <see cref="PhysicsScene2D.Simulate" /> will perform a single simulation step, simulating physics over the specified <c>step</c> time.
        ///
        ///By default, <see cref="Physics2D.AllLayers">All Layers</see> are simulated, however if you specify layers then only the <see cref="Rigidbody2D" /> will be simulated. Along with this, only contacts for <see cref="Collider2D" /> on the specified layer(s) will be handled. Finally, only <see cref="Joint2D">joints</see> or <see cref="Effector2D">effectors</see> on the specified layer(s) will be handled.
        ///
        ///You can call <see cref="PhysicsScene2D.Simulate" /> in the Editor outside of play mode, however caution is advised as this will cause the simulation to move GameObjects that have an attached <see cref="Rigidbody2D" /> component. When simulating in the Editor outside of play mode, a full simulation occurs for all physics components including <see cref="Rigidbody2D" />, <see cref="Collider2D" />, <see cref="Joint2D" /> and <see cref="Effector2D" />, and contacts are generated. However, contacts are not reported via the standard script callbacks. This is a safety measure to prevent callbacks from deleting objects in the Scene, which is not an undoable operation.
        ///
        ///**NOTE:** Calling <see cref="Physics2D.Simulate" /> does not cause Unity to call FixedUpdate. Unity still calls <c>FixedUpdate</c> at the rate defined by <see cref="Time.fixedDeltaTime" /> whether automatic simulation is on or off, and regardless of when you call Physics2D.Simulate. Also, if you pass framerate-dependent step values (such as <see cref="Time.deltaTime" />) to the physics engine, your simulation will be less deterministic because of the unpredictable fluctuations in framerate that can arise. To achieve more deterministic physics results, you should pass a fixed step value to Physics2D.Simulate every time you call it.
        ///
        ///
        ///
        ///Here is an example of a basic simulation that implements what's being done in the automatic simulation mode.</remarks>
        ///<param name="deltaTime">The time to advance physics by.</param>
        ///<param name="simulationLayers">The <see cref="Rigidbody2D" /> and <see cref="Collider2D" /> layers to simulate.</param>
        ///<returns>Whether the simulation was run or not.  Running the simulation during physics callbacks will always fail.</returns>
        ///<example>
        ///  <code><![CDATA[using UnityEngine;
        ///
        ///public class BasicSimulation : MonoBehaviour
        ///{
        ///    public PhysicsScene physicsScene;
        ///    private float timer;
        ///
        ///    void Update()
        ///    {
        ///        if (!physicsScene.IsValid())
        ///            return; // do nothing if the physics Scene is not valid.
        ///
        ///        timer += Time.deltaTime;
        ///
        ///        // Catch up with the game time.
        ///        // Advance the physics simulation in portions of Time.fixedDeltaTime
        ///        // Note that generally, we don't want to pass variable delta to Simulate as that leads to unstable results.
        ///        while (timer >= Time.fixedDeltaTime)
        ///        {
        ///            timer -= Time.fixedDeltaTime;
        ///            physicsScene.Simulate(Time.fixedDeltaTime);
        ///        }
        ///
        ///        // Here you can access the transforms state right after the simulation, if needed...
        ///    }
        ///}
        ///]]></code>
        ///</example>
        ///<seealso cref="Physics2D.simulationMode" />
        ///<seealso cref="Physics2D.Simulate" />
        public bool Simulate(float deltaTime, [DefaultValue("Physics2D.AllLayers")] int simulationLayers = Physics2D.AllLayers)
        {
            if (IsValid())
                return Physics2D.Simulate_Internal(this, deltaTime, simulationLayers);

            throw new InvalidOperationException("Cannot simulate the physics scene as it is invalid.");
        }

        #region Linecast

        ///<summary>Casts a line segment against colliders in the PhysicsScene2D, returning the first intersection only.</summary>
        ///<remarks>A linecast is an imaginary line between two points in world space. Any <see cref="Collider2D" /> making contact with this line can be detected and reported. This differs from the similar raycast in that raycasting specifies the line using an origin, direction and distance. Linecasts are useful for determining lines of sight, targets hit by gunfire and for many other purposes in gameplay.
        ///
        ///This function returns a RaycastHit2D object when the line contacts a <see cref="Collider2D" /> in the Scene. The direction of the line is assumed to extend from the start point to the end point. Only the first collider encountered in that direction will be reported.
        ///
        ///The layerMask can be used to detect objects selectively only on certain layers (this allows you to apply the detection only to enemy characters, for example). Overloads of this method that use <c>contactFilter</c> can filter the results by the options available in <see cref="ContactFilter2D" />.
        ///
        ///Additionally, this will also detect collider(s) at the start of the ray. In this case, the ray starts inside the collider and doesn't intersect the collider surface. This means that the collision normal cannot be calculated, in which case the returned collision normal is set to the inverse of the ray vector being tested. This can easily be detected because such results are always at a RaycastHit2D fraction of zero.
        ///
        ///**NOTE:** All results are sorted into ascending distance order i.e. the first result is the closest.</remarks>
        ///<param name="start">The start point of the line in world space.</param>
        ///<param name="end">The end point of the line in world space.</param>
        ///<param name="layerMask">The filter used to detect Colliders only on certain layers.</param>
        ///<returns>The cast results returned.</returns>
        ///<seealso cref="PhysicsScene2D" />
        ///<seealso cref="RaycastHit2D" />
        ///<seealso cref="LayerMask" />
        ///<seealso cref="Physics2D.DefaultRaycastLayers" />
        ///<seealso cref="Physics2D.IgnoreRaycastLayer" />
        ///<seealso cref="Physics2D.queriesHitTriggers" />
        public RaycastHit2D Linecast(Vector2 start, Vector2 end, [DefaultValue("Physics2D.DefaultRaycastLayers")] int layerMask = Physics2D.DefaultRaycastLayers)
        {
            var contactFilter = ContactFilter2D.CreateLegacyFilter(layerMask, -Mathf.Infinity, Mathf.Infinity);
            return Linecast_Internal(this, start, end, contactFilter);
        }

        ///<summary>Casts a line segment against colliders in the PhysicsScene2D, returning the first intersection only.</summary>
        ///<remarks>A linecast is an imaginary line between two points in world space. Any <see cref="Collider2D" /> making contact with this line can be detected and reported. This differs from the similar raycast in that raycasting specifies the line using an origin, direction and distance. Linecasts are useful for determining lines of sight, targets hit by gunfire and for many other purposes in gameplay.
