        ///This function returns a collection of <see cref="Collider2D" />  in a <see cref="ColliderArray2D" />. The collection does not allocate any managed memory but must be disposed of.
        ///
        ///The results can also be filtered by the <c>contactFilter</c>.</remarks>
        ///<param name="pointA">One corner of the rectangle.</param>
        ///<param name="pointB">The corner of the rectangle diagonally opposite the pointA corner.</param>
        ///<param name="contactFilter">The contact filter used to filter the results differently, such as by layer mask and Z depth. Note that the normal angle is not used for overlap testing.</param>
        ///<param name="allocator">The memory allocator to use for the results. This can only be Allocator.Temp, Allocator.TempJob or Allocator.Persistent.</param>
        ///<returns>A collection of Collider2D containing the results. The collection does not allocate any managed memory but must be disposed of.</returns>
        public readonly ColliderArray2D OverlapArea(Vector2 pointA, Vector2 pointB, ContactFilter2D contactFilter, Allocator allocator = Allocator.Temp)
        {
            Vector2 point = (pointA + pointB) * 0.5f;
            Vector2 size = new Vector2(Mathf.Abs(pointA.x - pointB.x), Math.Abs(pointA.y - pointB.y));
            return OverlapBox(point, size, 0.0f, contactFilter, allocator);
        }

        private int OverlapAreaToBoxList_Internal(Vector2 pointA, Vector2 pointB, ContactFilter2D contactFilter, List<Collider2D> results)
        {
            Vector2 point = (pointA + pointB) * 0.5f;
            Vector2 size = new Vector2(Mathf.Abs(pointA.x - pointB.x), Math.Abs(pointA.y - pointB.y));
            return OverlapBox(point, size, 0.0f, contactFilter, results);
        }

