                throw new ArgumentNullException("Collider cannot be NULL.");

            return ClosestPoint_Collider(position, collider);
        }

        // Get the closest point to position on the specified rigidbody.
        ///<summary>Returns a point on the perimeter of all enabled Colliders attached to the <c>rigidbody</c> that is closest to the specified <c>position</c>.</summary>
        ///<remarks>This function provides the ability to calculate the closest point of a specified <c>position</c> to the perimeter of any enabled <see cref="Collider2D" /> type attached to the specified <see cref="Rigidbody2D" />.
        ///
        ///    In the case where the <c>position</c> is inside any of the enabled <see cref="Collider2D" /> attached to the <c>rigidbody</c>, the input <c>position</c> is returned instead.</remarks>
        ///<param name="position">The position from which to find the closest point on the specified <c>rigidbody</c>.</param>
        ///<param name="rigidbody">The Rigidbody on which to find the closest specified <c>position</c>.</param>
        ///<returns>A point on the perimeter of a Collider attached to the <c>rigidbody</c> that is closest to the specified <c>position</c>.</returns>
        public static Vector2 ClosestPoint(Vector2 position, Rigidbody2D rigidbody)
        {
            if (rigidbody == null)
                throw new ArgumentNullException("Rigidbody cannot be NULL.");

            return ClosestPoint_Rigidbody(position, rigidbody);
        }

        [StaticAccessor("PhysicsQuery2D", StaticAccessorType.DoubleColon)]
        [NativeMethod("ClosestPoint")]
        extern private static Vector2 ClosestPoint_Collider(Vector2 position, [NotNull] Collider2D collider);

        [StaticAccessor("PhysicsQuery2D", StaticAccessorType.DoubleColon)]
        [NativeMethod("ClosestPoint")]
        extern private static Vector2 ClosestPoint_Rigidbody(Vector2 position, [NotNull] Rigidbody2D rigidbody);

