        public static ColliderArray2D GetContactColliders(Collider2D collider, ContactFilter2D contactFilter, Allocator allocator = Allocator.Temp)
        {
            return new(GetColliderContactsCollidersOnlyPhysicsBuffer(collider, contactFilter, allocator));
        }

        // Get filtered contacts for this rigidbody.
        ///<summary>Retrieves all colliders in contact with this Rigidbody, with the results filtered by the <c>contactFilter</c>.</summary>
        ///<param name="rigidbody">The Rigidbody to retrieve contacts for.  All Colliders attached to this Rigidbody will be checked.</param>
        ///<param name="contactFilter">The contact filter used to filter the results differently, such as by layer mask, Z depth, or normal angle.</param>
        ///<param name="allocator">The memory allocator to use for the results. This can only be Allocator.Temp, Allocator.TempJob or Allocator.Persistent.</param>
        ///<returns>A collection of Collider2D containing the results. The collection does not allocate any managed memory but must be disposed of.</returns>
        public static ColliderArray2D GetContactColliders(Rigidbody2D rigidbody, ContactFilter2D contactFilter, Allocator allocator = Allocator.Temp)
        {
            return new(GetRigidbodyContactsCollidersOnlyPhysicsBuffer(rigidbody, contactFilter, allocator));
        }

