        #region Editor

        // Editor drag-helper scratch list: cleared at the start of every SetEditorDragMovement call, so no stale entries meaningfully persist across a code reload.
        [NoAutoStaticsCleanup]
        private static List<Rigidbody2D> m_LastDisabledRigidbody2D = new List<Rigidbody2D>();
        internal static void SetEditorDragMovement(bool dragging, GameObject[] objs)
        {
            // Reset drag behaviour for all previously dragged bodies.
            foreach (var body in m_LastDisabledRigidbody2D)
            {
                if (body != null)
                    body.SetDragBehaviour(false);
            }
            m_LastDisabledRigidbody2D.Clear();

            // If we're not dragging then the work is already done.
            if (!dragging)
                return;

            // Set all bodies drag behaviour.
            foreach (var obj in objs)
            {
                var bodyComponents = obj.GetComponentsInChildren<Rigidbody2D>(false);
                foreach (var body in bodyComponents)
                {
                    m_LastDisabledRigidbody2D.Add(body);
                    body.SetDragBehaviour(true);
                }
            }
        }

        #endregion
    }

    #region Enums

    ///<summary>The direction that the capsule sides can extend.</summary>
    public enum CapsuleDirection2D
    {
        // Vertical (radii top/bottom)
        ///<summary>The capsule sides extend vertically.</summary>
        Vertical = 0,

        // Horizontal (radii left/right)
        ///<summary>The capsule sides extend horizontally.</summary>
        Horizontal = 1
    }

    ///<summary>Interpolation mode for Rigidbody2D objects.</summary>
    public enum RigidbodyInterpolation2D
    {
        // No Interpolation.
        ///<summary>Do not apply any smoothing to the object's movement.</summary>
        None = 0,

        // Interpolation will always lag a little bit behind but can be smoother than extrapolation.
        ///<summary>Smooth movement based on the object's positions in previous frames.</summary>
        Interpolate = 1,

        // Extrapolation will predict the position of the rigidbody based on the current velocity.
        ///<summary>Smooth an object's movement based on an estimate of its position in the next frame.</summary>
        Extrapolate = 2
    }

    ///<summary>Settings for a Rigidbody2D's initial sleep state.</summary>
    public enum RigidbodySleepMode2D
    {
        // Never sleep.
        ///<summary>Rigidbody2D never automatically sleeps.</summary>
        NeverSleep = 0,

        // Start the rigid body awake.
        ///<summary>Rigidbody2D is initially awake.</summary>
        StartAwake = 1,

        // Start the rigid body asleep.
        ///<summary>Rigidbody2D is initially asleep.</summary>
        StartAsleep = 2
    }

    ///<summary>Controls how collisions are detected when a <see cref="Rigidbody2D" /> moves.</summary>
    ///<seealso cref="Rigidbody2D.collisionDetectionMode" />
    public enum CollisionDetectionMode2D
    {
        // Obsolete.  Use Discrete instead.
        ///<summary>This mode is obsolete.  You should use <see cref="Discrete" /> mode.</summary>
        [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
        [Obsolete("Enum member CollisionDetectionMode2D.None has been deprecated. Use CollisionDetectionMode2D.Discrete instead (UnityUpgradable) -> Discrete", true)]
        None = 0,

        // Bodies move but may cause colliders to pass through other colliders at higher speeds but is much faster to calculate than continuous mode.
        ///<summary>When a <see cref="Rigidbody2D" /> moves, only collisions at the new position are detected.</summary>
        ///<remarks>When using this mode, <see cref="Rigidbody2D" /> that are moving fast can overlap or even pass through other colliders.  This mode however is much faster to calculate and should only be used when objects are moving at relatively slow or moderate speeds and you are not encountering objects overlapping or passing through each other.</remarks>
        ///<seealso cref="Rigidbody2D.collisionDetectionMode" />
        Discrete = 0,

        // Provides the most accurate collision detection to prevent colliders passing through other colliders at higher speeds but is much more expensive to calculate.
        ///<summary>Ensures that all collisions are detected when a <see cref="Rigidbody2D" /> moves.</summary>
        ///<remarks>When using this mode, the collision detection system will detect all collisions in the path that a <see cref="Rigidbody2D" /> moves along therefore preventing colliders attached to the rigidbody passing through other colliders at higher speeds.  The physics system will also calculate a time-of-time calculation to ensure that the new position of the <see cref="Rigidbody2D" /> is at the correct contact position with no overlaps.  This mode however is much more expensive to calculate and should only be used when objects are moving at higher speeds or you are encountering objects overlapping or passing through each other.</remarks>
        ///<seealso cref="Rigidbody2D.collisionDetectionMode" />
        Continuous = 1
    }

    ///<summary>Option for how to apply a force using <see cref="Rigidbody2D.AddForce" />.</summary>
    ///<remarks>Use this to apply a certain type of force to a 2D RigidBody. There are two types of forces to apply: Force mode and Impulse Mode. For a 3D Rigidbody see <see cref="T:UnityEngine.ForceMode" />.</remarks>
    ///<example>
    ///  <code><![CDATA[
    /// //This script adds force to a Rigidbody. The kind of force is determined by which buttons you click.
    ///
    /// //Create a Sprite and attach a Rigidbody2D component to it
    /// //Attach this script to the Sprite
    ///
    ///using UnityEngine;
    ///using UnityEngine.EventSystems;
    ///
    ///public class AddingForce : MonoBehaviour
    ///{
    ///    //Use to switch between Force Modes
    ///    enum ModeSwitching { Start, Impulse, Force };
    ///    ModeSwitching m_ModeSwitching;
    ///
    ///    //Use this to change the different kinds of force
    ///    ForceMode2D m_ForceMode;
    ///    //Start position of the RigidBody, use to reset
    ///    Vector2 m_StartPosition;
    ///
    ///    //Use to apply force to RigidBody
    ///    Vector2 m_NewForce;
    ///
    ///    //Use to manipulate the RigidBody of a GameObject
    ///    Rigidbody2D m_Rigidbody;
    ///
    ///    void Start()
    ///    {
    ///        //Fetch the RigidBody component attached to the GameObject
    ///        m_Rigidbody = GetComponent<Rigidbody2D>();
    ///        //Start at first mode (nothing happening yet)
    ///        m_ModeSwitching = ModeSwitching.Start;
    ///
    ///        //Initialising the force to use on the RigidBody in various ways
    ///        m_NewForce = new Vector2(-5.0f, 1.0f);
    ///
    ///        //This is the RigidBody's starting position
    ///        m_StartPosition = m_Rigidbody.transform.position;
    ///    }
    ///
    ///    void Update()
    ///    {
    ///        //Switching modes depending on button presses
    ///        switch (m_ModeSwitching)
    ///        {
    ///            //This is the starting mode which resets the GameObject
    ///            case ModeSwitching.Start:
    ///
    ///                //Reset to starting position of RigidBody
    ///                m_Rigidbody.transform.position = m_StartPosition;
    ///                //Reset the velocity of the RigidBody
    ///                m_Rigidbody.linearVelocity = new Vector2(0f, 0f);
    ///                break;
    ///
    ///            //This is the Force Mode
    ///            case ModeSwitching.Force:
    ///                //Make the GameObject travel upwards
    ///                m_NewForce = new Vector2(0, 1.0f);
    ///                //Use Force mode as force on the RigidBody
    ///                m_Rigidbody.AddForce(m_NewForce, ForceMode2D.Force);
    ///                break;
    ///
    ///            //This is the Impulse Mode
    ///            case ModeSwitching.Impulse:
    ///                //Make the GameObject travel upwards
    ///                m_NewForce = new Vector2(0f, 1.0f);
    ///                //Use Impulse mode as a force on the RigidBody
    ///                m_Rigidbody.AddForce(m_NewForce, ForceMode2D.Impulse);
    ///                break;
    ///        }
    ///    }
    ///
    ///    //These are the Buttons for telling what Force to apply as well as resetting
    ///    void OnGUI()
    ///    {
    ///        //If reset button pressed
    ///        if (GUI.Button(new Rect(100, 0, 150, 30), "Reset"))
    ///        {
    ///            //Switch to start/reset case
    ///
    ///            m_ModeSwitching = ModeSwitching.Start;
    ///        }
    ///
    ///        //Impulse button pressed
    ///        if (GUI.Button(new Rect(100, 60, 150, 30), "Apply Impulse"))
    ///        {
    ///            //Switch to Impulse mode (apply impulse forces to GameObject)
    ///
    ///            m_ModeSwitching = ModeSwitching.Impulse;
    ///        }
    ///
    ///        //Force Button Pressed
    ///        if (GUI.Button(new Rect(100, 90, 150, 30), "Apply Force"))
    ///        {
    ///            //Switch to Force mode (apply force to GameObject)
    ///            m_ModeSwitching = ModeSwitching.Force;
    ///        }
    ///    }
    ///}
    ///]]></code>
    ///</example>
    public enum ForceMode2D
    {
        // Add a force to the rigidbody, using its mass.
        ///<summary>Add a force to the Rigidbody2D, using its mass.</summary>
        ///<remarks>Apply the force in each FixedUpdate over a duration of time. This mode depends on the mass of rigidbody so more force must be applied to move higher-mass objects the same amount as lower-mass objects.
        ///
        ///This mode is useful for setting up realistic physics where it takes more force to move heavier objects.</remarks>
        Force = 0,

        // Add an instant velocity change (impulse) to the rigidbody, using its mass.
        ///<summary>Add an instant force impulse to the rigidbody2D, using its mass.</summary>
        ///<remarks>Apply the impulse force instantly. This mode depends on the mass of rigidbody so more force must be applied to move higher-mass objects the same amount as lower-mass objects.
        ///
        ///This mode is useful for applying forces that happen instantly, such as forces from explosions or collisions.</remarks>
        Impulse = 1,
    }

    ///<summary>Indicates what (if any) error was encountered when creating a 2D Collider.</summary>
    ///<remarks>This error state can be read directly from the 2D Collider via the property: <see cref="Collider2D.errorState" />.</remarks>
    public enum ColliderErrorState2D
    {
        // No errors were encountered when creating the collider.
        ///<summary>Indicates that no error was encountered, therefore the 2D Collider was created successfully.</summary>
        None = 0,

        // No shapes were generated when creating the collider.
        ///<summary>Indicates that no physics shapes were created by the 2D Collider because the state of 2D Collider resulted in vertices too close or an area that is too small for the physics engine to handle.</summary>
        NoShapes = 1,

        // Some shapes were removed when creating the collider.
        ///<summary>Indicates that some physics shapes were not created by the 2D Collider because the state of 2D Collider resulted in vertices too close or an area that is too small for the physics engine to handle.</summary>
        RemovedShapes = 2
    }

    ///<summary>Represents the state of a joint limit.</summary>
    ///<seealso cref="DistanceJoint2D" />
    ///<seealso cref="HingeJoint2D" />
    ///<seealso cref="SliderJoint2D" />
    public enum JointLimitState2D
    {
        // No limit set.
        ///<summary>Represents a state where the joint limit is inactive.</summary>
        Inactive = 0,

        // At the lower limit.
        ///<summary>Represents a state where the joint limit is at the specified lower limit.</summary>
        LowerLimit = 1,

        // At the upper limit.
        ///<summary>Represents a state where the joint limit is at the specified upper limit.</summary>
        UpperLimit = 2,

        // At both lower and upper limits (they are identical).
        ///<summary>Represents a state where the joint limit is at the specified lower and upper limits (they are identical).</summary>
        EqualLimits = 3,
    }

    ///<summary>Options for selecting which action to take when a <see cref="Joint2D" /> breaks.</summary>
    ///<seealso cref="Joint2D.breakAction" />
    ///<seealso cref="Joint2D.breakForce" />
    ///<seealso cref="Joint2D.breakTorque" />
    public enum JointBreakAction2D
    {
        // Ignore any joint break.
        ///<summary>When the <see cref="Joint2D" /> breaks, no action will be taken and <c>OnJointBreak2D</c> will not be called.</summary>
        ///<remarks>This option effectively disables any joint breaking and will ignore any <see cref="Joint2D.breakForce" /> or <see cref="Joint2D.breakTorque" />.</remarks>
        Ignore = 0,

        // Perform a callback only for a joint break.
        ///<summary>When the <see cref="Joint2D" /> breaks, call <c>OnJointBreak2D</c> but take no other action.</summary>
        ///<remarks>NOTE: With this option selected, continuing to break the joint will continue to cause the <c>OnJointBreak2D</c> callback to be called.</remarks>
        CallbackOnly = 1,

        // Disable the Joint for a joint break.
        ///<summary>When the <see cref="Joint2D" /> breaks, call <c>OnJointBreak2D</c> and then disable the component.</summary>
        ///<remarks>When the joint is disable, no further joint breaking can occur until the joint is enabled again.</remarks>
        Disable = 2,

        // Destroy the joint for a joint break.
        ///<summary>When the <see cref="Joint2D" /> breaks, call <c>OnJointBreak2D</c> and then destroy the component.</summary>
        ///<remarks>When the joint is destroyed, no further joint breaking can occur.</remarks>
        Destroy = 3,
    }

    // Selects source and targets to be used by an Effector2D.
    ///<summary>Selects the source and/or target to be used by an <see cref="Effector2D" />.</summary>
    public enum EffectorSelection2D
    {
        // Rigid-body (refers to the rigid-body center-of-mass).
        ///<summary>The source/target is defined by the <see cref="Rigidbody2D" />.</summary>
        ///<remarks>When used, this equates to the center-of-mass.</remarks>
        Rigidbody = 0,

        // Collider (refers to the centroid of the AABB defined by the collider).
        ///<summary>The source/target is defined by the <see cref="Collider2D" />.</summary>
        Collider = 1,
    }


    // The mode used to apply the [[Effector2D]] force.
    ///<summary>The mode used to apply <see cref="Effector2D" /> forces.</summary>
    public enum EffectorForceMode2D
    {
        ///<summary>The force is applied at a constant rate.</summary>
        Constant = 0,

        ///<summary>The force is applied inverse-linear relative to a point.</summary>
        ///<remarks>Inverse-linear falls off at the same rate as the distance from the point i.e. at a distance of 2 meter, the force is also reduced by 2.</remarks>
        InverseLinear = 1,

        ///<summary>The force is applied inverse-squared relative to a point.</summary>
        ///<remarks>Inverse-squared falls off at the square of the distance from the point i.e. at a distance of 2 meter, the force is reduced by 4.</remarks>
        InverseSquared = 2,
    }

    // The type of a physics shape.
    ///<summary>Options for indicate which primitive shape type is used to interpret geometry contained within a <see cref="PhysicsShape2D" /> object.</summary>
    ///<seealso cref="PhysicsShape2D.shapeType" />
    public enum PhysicsShapeType2D
    {
        // Circle 1-Vertex (b2CircleShape)
        ///<summary>Use a circle shape to interpret the <see cref="PhysicsShape2D" /> geometry.</summary>
        ///<remarks>A circle geometry type is comprised of a single vertex in the <see cref="PhysicsShape2D" /> and a <see cref="PhysicsShape2D.radius" />. The single vertex represents the center of the circle with the radius defining the radius of the circle.</remarks>
        Circle = 0,

        // Capsule 2-Vertex (b2CapsuleShape)
        ///<summary>Use a capsule shape to interpret the <see cref="PhysicsShape2D" /> geometry.</summary>
        ///<remarks>A capsule geometry type is comprised of two vertices in the <see cref="PhysicsShape2D" /> and a <see cref="PhysicsShape2D.radius" />. The two vertices represent the centers of the two ends of a capsule shape with the radius defining the circular end radius.</remarks>
        Capsule = 1,

        // Polygon (Physics2D.MaxPolygonShapeVertices - See "box2d_b2_maxPolygonVertices") Vertex (b2PolygonShape)
        ///<summary>Use a convex polygon shape to interpret the <see cref="PhysicsShape2D" /> geometry.</summary>
        ///<remarks>A polygon geometry type is comprised of a minimum of three (triangle) vertices and maximum defined by <see cref="Physics2D.MaxPolygonShapeVertices" /> in the <see cref="PhysicsShape2D" />. The vertices represent a set of consecutive edges where each vertex connects to the next vertex with the last vertex automatically representing an edge connecting to the first vertex resulting in a closed primitive shape. These edges must result in a convex polygon. If this is not the case then the physics system will constrain the polygon to be convex by producing a convex hull. All polygon collision detection uses convex polygons for performance reasons.</remarks>
        Polygon = 2,

        // Edge n-Vertex (b2Chainhape)
        ///<summary>Use multiple edges to interpret the <see cref="PhysicsShape2D" /> geometry.</summary>
        ///<remarks>An edge geometry type is comprised of an unlimited quantity of vertices in the <see cref="PhysicsShape2D" /> and a <see cref="PhysicsShape2D.radius" />. The vertices represent the consecutive edges where each vertex connects to the next vertex. These edges represent an open shape with no interior even if the first and last vertices overlap. The <see cref="PhysicsShape2D.radius" /> is the radius of all edges. (Edges with a radius of zero become infinitely thin edges while a radius greater than zero results in capsule shaped edges i.e. any edge with a radius.)
        ///
        ///Edges also have an <see cref="PhysicsShape2D.adjacentStart" /> and <see cref="PhysicsShape2D.adjacentEnd" /> feature allowing separate edge shapes to be  joined.
        ///
        ///**NOTE**: You should ensure that edges do not self-intersect as this can produce incorrect collision responses. As checking self-intersection has a runtime cost, this constraint is not validated and so you should ensure this does not occur.</remarks>
        Edges = 3,
    }

    #endregion

    #region Structures

    ///<summary>Represents an efficient low-level physics shape used by the physics engine.</summary>
    ///<remarks>A <see cref="Collider2D" /> is a high-level representation of physics geometry that produces low-level <see cref="PhysicsShape2D" /> geometry that the physics engine understands. A <see cref="PhysicsShape2D" /> can represent any shape type as defined by <see cref="PhysicsShapeType2D" />.</remarks>
    ///<seealso cref="PhysicsShapeGroup2D" />
    [StructLayout(LayoutKind.Sequential)]
    [UsedByNativeCode]
    [NativeHeader("Modules/Physics2D/Public/PhysicsScripting2D.h")]
    public struct PhysicsShape2D
    {
        private PhysicsShapeType2D m_ShapeType;
        private float m_Radius;
        private int m_VertexStartIndex;
        private int m_VertexCount;
        private int m_UseAdjacentStart;
        private int m_UseAdjacentEnd;
        private Vector2 m_AdjacentStart;
        private Vector2 m_AdjacentEnd;

        ///<summary>The shape type determines how the vertices and radius are used by this <see cref="PhysicsShape2D" />.</summary>
        ///<remarks>Refer to the <see cref="PhysicsShapeType2D" /> documentation for more information about the different shape types.</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        var circleShapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-2f, 3f),
        ///                radius: 1f
        ///            );
        ///
        ///        // Add a Capsule to the shape group.
        ///        var capsuleShapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Fetch the shapes.
        ///        var circleShape = shapeGroup.GetShape(circleShapeIndex);
        ///        var capsuleShape = shapeGroup.GetShape(capsuleShapeIndex);
        ///
        ///        // Validate the shape types.
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, circleShape.shapeType);
        ///        Assert.AreEqual(PhysicsShapeType2D.Capsule, capsuleShape.shapeType);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public PhysicsShapeType2D shapeType
        {
            get { return m_ShapeType; }
            set { m_ShapeType = value; }
        }

        ///<summary>The radius of the shape.</summary>
        ///<remarks>All <see cref="PhysicsShapeType2D" /> use this radius with the exception of the <see cref="PhysicsShapeType2D.Polygon">Polygon</see> type. Refer to the individual shape types for details on how the radius is used for the respective shape.</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        var circleShapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-2f, 3f),
        ///                radius: 1f
        ///            );
        ///
        ///        // Add a Capsule to the shape group.
        ///        var capsuleShapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Fetch the shapes.
        ///        var circleShape = shapeGroup.GetShape(circleShapeIndex);
        ///        var capsuleShape = shapeGroup.GetShape(capsuleShapeIndex);
        ///
        ///        // Validate the shape radius.
        ///        Assert.AreApproximatelyEqual(1f, circleShape.radius);
        ///        Assert.AreApproximatelyEqual(0.5f, capsuleShape.radius);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public float radius
        {
            get { return m_Radius; }
            set
            {
                if (value < 0.0f)
                    throw new ArgumentOutOfRangeException("radius cannot be negative.");

                if (Single.IsNaN(value) || Single.IsInfinity(value))
                    throw new ArgumentException("radius contains an invalid value.");

                m_Radius = value;
            }
        }

        ///<summary>The start index for the geometry of this shape within the <see cref="PhysicsShapeGroup2D" />.</summary>
        ///<remarks>Multiple <see cref="PhysicsShape2D" /> in a <see cref="PhysicsShapeGroup2D" /> are represented as a single list of vertices. This index is the start of this shape within that list.</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Capsule to the shape group.
        ///        var capsuleShapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Add a Circle to the shape group.
        ///        var circleShapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-2f, 3f),
        ///                radius: 1f
        ///            );
        ///
        ///        // Fetch the shapes.
        ///        var capsuleShape = shapeGroup.GetShape(capsuleShapeIndex);
        ///        var circleShape = shapeGroup.GetShape(circleShapeIndex);
        ///
        ///        // Validate the shape vertex count.
        ///        Assert.AreEqual(2, capsuleShape.vertexCount);
        ///        Assert.AreEqual(1, circleShape.vertexCount);
        ///
        ///        // Validate the Capsule vertex start index.
        ///        // NOTE: The Capsule is the first shape so its index is 0.
        ///        //  It has 2 vertices at indices 0 and 1.
        ///        Assert.AreEqual(0, capsuleShape.vertexStartIndex);
        ///
        ///        // Validate the Circle vertex start index.
        ///        // NOTE: The Circle is the second shape so its index is 0.
        ///        // It comes after the Capsule which has 2 vertices at indices 0 and 1 so
        ///        // the Circle start index is 2.
        ///        Assert.AreEqual(2, circleShape.vertexStartIndex);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        ///<seealso cref="PhysicsShapeGroup2D.GetShapeVertex">GetShapeVertex</seealso>
        ///<seealso cref="PhysicsShapeGroup2D.GetShapeVertices">GetShapeVertices</seealso>
        public int vertexStartIndex
        {
            get { return m_VertexStartIndex; }
            set
            {
                if (value < 0)
                    throw new ArgumentOutOfRangeException("vertexStartIndex cannot be negative.");

                m_VertexStartIndex = value;
            }
        }

        ///<summary>The total number of vertices used to represent the <see cref="PhysicsShape2D.shapeType">shape type</see>.</summary>
        ///<remarks>See <see cref="PhysicsShapeType2D" /> for details on how each type uses different quantities of vertices to represent itself.</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        var circleShapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-2f, 3f),
        ///                radius: 1f
        ///            );
        ///
        ///        // Add a Capsule to the shape group.
        ///        var capsuleShapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Fetch the shapes.
        ///        var circleShape = shapeGroup.GetShape(circleShapeIndex);
        ///        var capsuleShape = shapeGroup.GetShape(capsuleShapeIndex);
        ///
        ///        // Validate the shape vertex count.
        ///        Assert.AreEqual(1, circleShape.vertexCount);
        ///        Assert.AreEqual(2, capsuleShape.vertexCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int vertexCount
        {
            get { return m_VertexCount; }
            set
            {
                if (value < 1)
                    throw new ArgumentOutOfRangeException("vertexCount cannot be less than one.");

                m_VertexCount = value;
            }
        }

        ///<summary>When the value is true, then the shape will use the <see cref="PhysicsShape2D.adjacentStart">adjacentStart</see> feature. When the value is false, then the shape will not use the <see cref="PhysicsShape2D.adjacentEnd">adjacentStart</see> feature.</summary>
        ///<remarks>This property is identical to <see cref="EdgeCollider2D.useAdjacentStartPoint" />.
        ///
        ///**NOTE**: This property is only used when the <see cref="PhysicsShape2D.shapeType">shapeType</see> is <see cref="PhysicsShapeType2D.Edges" />.</remarks>
        public bool useAdjacentStart
        {
            get { return m_UseAdjacentStart != 0; }
            set { m_UseAdjacentStart = value ? 1 : 0; }
        }

        ///<summary>When the value is true, then the shape will use the <see cref="PhysicsShape2D.adjacentEnd">adjacentEnd</see> feature. When the value is false, then the shape will not use the <see cref="PhysicsShape2D.adjacentEnd">adjacentEnd</see> feature.</summary>
        ///<remarks>This property is identical to <see cref="EdgeCollider2D.useAdjacentEndPoint" />.
        ///
        ///**NOTE**: This property is only used when the <see cref="PhysicsShape2D.shapeType">shapeType</see> is <see cref="PhysicsShapeType2D.Edges" />.</remarks>
        public bool useAdjacentEnd
        {
            get { return m_UseAdjacentEnd != 0; }
            set { m_UseAdjacentEnd = value ? 1 : 0; }
        }

        ///<summary>Defines the position of a virtual point adjacent to the start vertex of an edge shape.</summary>
        ///<remarks>An edge shape is comprised of multiple edge (line segments) defined by all its vertices. However, when a collision occurs with the start vertex of the shape then this vertex can be used to form a collision normal, and calculate the collision response. This allows for joining of individual edge shapes to produce a continuous collision surface.
        ///
        ///This property is identical to <see cref="EdgeCollider2D.adjacentStartPoint" />. It is only used when the <see cref="PhysicsShape2D.shapeType">shapeType</see> is <see cref="PhysicsShapeType2D.Edges" /> and <see cref="PhysicsShape2D.useAdjacentStart">useAdjacentStart</see> is true.</remarks>
        public Vector2 adjacentStart
        {
            get { return m_AdjacentStart; }
            set
            {
                if (Single.IsNaN(value.x) ||
                    Single.IsNaN(value.y) ||
                    Single.IsInfinity(value.x) ||
                    Single.IsInfinity(value.y))
                    throw new ArgumentException("adjacentStart contains an invalid value.");

                m_AdjacentStart = value;
            }
        }

        ///<summary>Defines the position of a virtual point adjacent to the end vertex of an edge shape.</summary>
        ///<remarks>An edges shape is comprised of multiple edges (line segments) defined by all its vertices. However, when a collision occurs with the end vertex of the shape then this vertex can be used to form a collision normal, and calculate the collision response. This allows for joining of individual edge shapes to produce a continuous collision surface.
        ///
        ///This property is identical to <see cref="EdgeCollider2D.adjacentEndPoint" />. It is only used when the <see cref="PhysicsShape2D.shapeType">shapeType</see> is <see cref="PhysicsShapeType2D.Edges" /> and <see cref="PhysicsShape2D.useAdjacentEnd">useAdjacentEnd</see> is true.</remarks>
        public Vector2 adjacentEnd
        {
            get { return m_AdjacentEnd; }
            set
            {
                if (Single.IsNaN(value.x) ||
                    Single.IsNaN(value.y) ||
                    Single.IsInfinity(value.x) ||
                    Single.IsInfinity(value.y))
                    throw new ArgumentException("adjacentEnd contains an invalid value.");

                m_AdjacentEnd = value;
            }
        }
    }

    ///<summary>Represents a group of <see cref="PhysicsShape2D" /> and their geometry.</summary>
    ///<remarks>A shape group represents multiple <see cref="PhysicsShape2D" /> of the same or mixed <see cref="PhysicsShapeType2D" /> along with their geometry. It is comprised of a single list of vertices (<see cref="PhysicsShapeGroup2D.GetShapeVertices">GetShapeVertices</see>) along with a list of <see cref="PhysicsShape2D" /> which refer to specific ranges of those vertices i.e. they index into the list of vertices. Some shape types (<see cref="PhysicsShapeType2D" />) use a fixed number of vertices and some use a variable number of vertices therefore this single vertices list is a compact and efficient representation for multiple <see cref="PhysicsShape2D" /> in a group.
    ///
    ///The shape group can be created by using the following methods:
    ///
    ///- Calling <see cref="Collider2D.GetShapes" /> where it would then represent all the shapes produced by that <see cref="Collider2D" />
    ///- Calling <see cref="Rigidbody2D.GetShapes" /> where it would then represent all the shapes produced by all the<see cref="Collider2D" /> attached to that <see cref="Rigidbody2D" />
    ///- Manually populating with custom shapes by calling <see cref="PhysicsShapeGroup2D.AddCircle">AddCircle</see>, <see cref="PhysicsShapeGroup2D.AddCapsule">AddCapsule</see>, <see cref="PhysicsShapeGroup2D.AddPolygon">AddPolygon</see>, <see cref="PhysicsShapeGroup2D.AddBox">AddBox</see> or <see cref="PhysicsShapeGroup2D.AddEdges">AddEdges</see>.</remarks>
    public class PhysicsShapeGroup2D
    {
        internal struct GroupState
        {
            public List<PhysicsShape2D> m_Shapes;
            public List<Vector2> m_Vertices;
            public Matrix4x4 m_LocalToWorld;

            public void ClearGeometry()
            {
                m_Shapes.Clear();
                m_Vertices.Clear();
            }
        }

        internal GroupState m_GroupState;

        // Get the vertices.
        internal List<Vector2> groupVertices { get { return m_GroupState.m_Vertices; } }

        // Get the shapes.
        internal List<PhysicsShape2D> groupShapes { get { return m_GroupState.m_Shapes; } }

        // Get the total shape count.
        ///<summary>The total number of  <see cref="PhysicsShape2D" /> in the shape group. (RO)</summary>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    private const int ShapeCount = 10;
        ///
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        // NOTE: We can hint to the shape group the capacity for shapes so that it's quicker when adding them.
        ///        var shapeGroup = new PhysicsShapeGroup2D(shapeCapacity: ShapeCount);
        ///
        ///        // Add Boxes to the shape group.
        ///        for (var n = 0; n < ShapeCount; ++n)
        ///        {
        ///            shapeGroup.AddBox
        ///                (
        ///                    center: new Vector2(n, 0f),
        ///                    size: new Vector2(0.25f, 0.25f)
        ///                );
        ///        }
        ///
        ///        // Validate that we created the specified number of shapes.
        ///        Assert.AreEqual(ShapeCount, shapeGroup.shapeCount);
        ///
        ///        // Validate that we created the correct number of vertices.
        ///        // NOTE: Each Box has 4 vertices so we multiply this constant by the number of shapes.
        ///        Assert.AreEqual(ShapeCount * 4, shapeGroup.vertexCount);
        ///
        ///        // Validate each shape.
        ///        for (var n = 0; n < ShapeCount; ++n)
        ///        {
        ///            // Fetch the actual shape created.
        ///            var physicsShape = shapeGroup.GetShape(n);
        ///
        ///            // Validate the shape.
        ///            Assert.AreEqual(PhysicsShapeType2D.Polygon, physicsShape.shapeType);
        ///            Assert.AreEqual(4, physicsShape.vertexCount);
        ///        }
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int shapeCount { get { return m_GroupState.m_Shapes.Count; } }

        // Get the total vertex count.
        ///<summary>The total number of vertices in the shape group used to represent all <see cref="PhysicsShape2D" /> within it. (RO)</summary>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    private const int ShapeCount = 10;
        ///
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        // NOTE: We can hint to the shape group the capacity for shapes so that it's quicker when adding them.
        ///        var shapeGroup = new PhysicsShapeGroup2D(shapeCapacity: ShapeCount);
        ///
        ///        // Add Boxes to the shape group.
        ///        for (var n = 0; n < ShapeCount; ++n)
        ///        {
        ///            shapeGroup.AddBox
        ///                (
        ///                    center: new Vector2(n, 0f),
        ///                    size: new Vector2(0.25f, 0.25f)
        ///                );
        ///        }
        ///
        ///        // Validate that we created the specified number of shapes.
        ///        Assert.AreEqual(ShapeCount, shapeGroup.shapeCount);
        ///
        ///        // Validate that we created the correct number of vertices.
        ///        // NOTE: Each Box has 4 vertices so we multiply this constant by the number of shapes.
        ///        Assert.AreEqual(ShapeCount * 4, shapeGroup.vertexCount);
        ///
        ///        // Validate each shape.
        ///        for (var n = 0; n < ShapeCount; ++n)
        ///        {
        ///            // Fetch the actual shape created.
        ///            var physicsShape = shapeGroup.GetShape(n);
        ///
        ///            // Validate the shape.
        ///            Assert.AreEqual(PhysicsShapeType2D.Polygon, physicsShape.shapeType);
        ///            Assert.AreEqual(4, physicsShape.vertexCount);
        ///        }
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int vertexCount { get { return m_GroupState.m_Vertices.Count; } }

        // Get/Set the local to world pose matrix.
        ///<summary>Gets or sets a matrix that transforms the <see cref="PhysicsShapeGroup2D" /> vertices from local space into world space.</summary>
        ///<remarks>When retrieving a <see cref="PhysicsShapeGroup2D" /> via <see cref="Rigidbody2D.GetShapes" /> or <see cref="Collider2D.GetShapes" />, this matrix will be set to the pose of the <see cref="Rigidbody2D" /> unless a <see cref="Rigidbody2D" /> is not available in which case the matrix it set to <see cref="Matrix4x4.identity" />.</remarks>
        public Matrix4x4 localToWorldMatrix { get { return m_GroupState.m_LocalToWorld; } set { m_GroupState.m_LocalToWorld = value; } }

        // The minimum vertex separation for polygon shapes.
        // NOTE: This equates to half the linear-s;op in the physics engine.
        private const float MinVertexSeparation = 0.5f * 0.005f;

        ///<summary>Initializes and returns an instance of <see cref="PhysicsShapeGroup2D" />. The shape group will be empty and ready for use by <see cref="Collider2D.GetShapes" />, <see cref="Rigidbody2D.GetShapes" /> or manually adding shapes.</summary>
        ///<remarks>Both the <c>shapeCapacity</c> and  <c>vertexCapacity</c> should be set high enough so that new allocations are not required and therefore no garbage collection work is produced.</remarks>
        ///<param name="shapeCapacity">The initial capacity of the <see cref="PhysicsShape2D" /> list used to contain the shapes.</param>
        ///<param name="vertexCapacity">The initial capacity of the <see cref="Vector2">vertices</see> list used to contain the shape geometry.</param>
        public PhysicsShapeGroup2D([DefaultValue("1")] int shapeCapacity = 1, [DefaultValue("8")] int vertexCapacity = 8)
        {
            m_GroupState = new GroupState
            {
                m_Shapes = new List<PhysicsShape2D>(shapeCapacity),
                m_Vertices = new List<Vector2>(vertexCapacity),
                m_LocalToWorld = Matrix4x4.identity
            };
        }

        // Clears the shape group.
        ///<summary>Clears all the vertices and shapes from the <see cref="PhysicsShapeGroup2D" />.</summary>
        ///<remarks>This call clears the lists used to store both vertices and shapes but retains the current shape group capacity (effectively creating an empty shape group).</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        shapeGroup.AddCircle
        ///            (
        ///                center: Vector2.zero,
        ///                radius: 1f
        ///            );
        ///
        ///        // Add a Box to the shape group.
        ///        shapeGroup.AddBox
        ///            (
        ///                center: new Vector2(3f, 2f),
        ///                size: new Vector2(1f, 1f)
        ///            );
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(1 + 1, shapeGroup.shapeCount);
        ///        Assert.AreEqual(1 + 4, shapeGroup.vertexCount);
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shapeGroup.GetShape(0).shapeType);
        ///        Assert.AreEqual(PhysicsShapeType2D.Polygon, shapeGroup.GetShape(1).shapeType);
        ///
        ///        // Clear the shape group.
        ///        shapeGroup.Clear();
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(0, shapeGroup.shapeCount);
        ///        Assert.AreEqual(0, shapeGroup.vertexCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void Clear()
        {
            m_GroupState.ClearGeometry();
            m_GroupState.m_LocalToWorld = Matrix4x4.identity;
        }

        // Add a shape group to this one.
        ///<summary>Adds a copy of all the <see cref="PhysicsShape2D" /> and their geometry from the specified <c>physicsShapeGroup</c> into this shape group. The specified <c>physicsShapeGroup</c> is not modified.</summary>
        ///<param name="physicsShapeGroup">The <see cref="PhysicsShapeGroup2D" /> to add to this shape group. (RO)</param>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    private const int ShapeCount = 10;
        ///
        ///    void Start()
        ///    {
        ///        // Create a shape group and add a Circle to it.
        ///        var shapeGroup1 = new PhysicsShapeGroup2D();
        ///        shapeGroup1.AddCircle
        ///            (
        ///                center: Vector2.zero,
        ///                radius: 1f
        ///            );
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(1, shapeGroup1.shapeCount);
        ///        Assert.AreEqual(1, shapeGroup1.vertexCount);
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shapeGroup1.GetShape(0).shapeType);
        ///
        ///        // Create another shape group and add a Box to it.
        ///        var shapeGroup2 = new PhysicsShapeGroup2D();
        ///        shapeGroup2.AddBox
        ///            (
        ///                center: new Vector2(3f, 2f),
        ///                size: new Vector2(1f, 1f)
        ///            );
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(1, shapeGroup2.shapeCount);
        ///        Assert.AreEqual(4, shapeGroup2.vertexCount);
        ///        Assert.AreEqual(PhysicsShapeType2D.Polygon, shapeGroup2.GetShape(0).shapeType);
        ///
        ///        // Add the second shape group to the first shape group.
        ///        shapeGroup1.Add(shapeGroup2);
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(1 + 1, shapeGroup1.shapeCount);
        ///        Assert.AreEqual(1 + 4, shapeGroup1.vertexCount);
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shapeGroup1.GetShape(0).shapeType);
        ///        Assert.AreEqual(PhysicsShapeType2D.Polygon, shapeGroup1.GetShape(1).shapeType);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void Add(PhysicsShapeGroup2D physicsShapeGroup)
        {
            if (physicsShapeGroup == null)
                throw new ArgumentNullException("Cannot merge a NULL PhysicsShapeGroup2D.");

            if (physicsShapeGroup == this)
                throw new ArgumentException("Cannot merge a PhysicsShapeGroup2D with itself.");

            // Finish if no shapes.
            if (physicsShapeGroup.shapeCount == 0)
                return;

            // Fetch the index where the first new shape will be.
            var shapeIndex = groupShapes.Count;

            // Fetch index offset we need to shift the new shape vertices by.
            var startVertexOffset = m_GroupState.m_Vertices.Count;

            // Add the new shapes and vertices.
            groupShapes.AddRange(physicsShapeGroup.groupShapes);
            groupVertices.AddRange(physicsShapeGroup.groupVertices);

            // Offset the new shape indices if required.
            if (shapeIndex > 0)
            {
                // Offset all vertices for the new shapes.
                for (var i = shapeIndex; i < m_GroupState.m_Shapes.Count; ++i)
                {
                    var physicsShape = m_GroupState.m_Shapes[i];
                    physicsShape.vertexStartIndex += startVertexOffset;
                    m_GroupState.m_Shapes[i] = physicsShape;
                }
            }
        }

        // Get all the shapes and vertices.
        ///<summary>Gets a copy of both the shapes and vertices in the <see cref="PhysicsShapeGroup2D" />.</summary>
        ///<remarks>**NOTE**: Because this is a copy, changing the specified <c>shapes</c> and <c>vertices</c> lists afterwards will not change the <see cref="PhysicsShapeGroup2D" />.</remarks>
        ///<param name="shapes">A list that will be populated with a copy of all the shapes in the <see cref="PhysicsShapeGroup2D" />.</param>
        ///<param name="vertices">A list that will be populated with a copy of all the vertices in the <see cref="PhysicsShapeGroup2D" />.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using System.Collections.Generic;
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        var circleShapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-2f, 3f),
        ///                radius: 1f
        ///            );
        ///
        ///        // Add a Capsule to the shape group.
        ///        var capsuleShapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shapeGroup.GetShape(circleShapeIndex).shapeType);
        ///        Assert.AreEqual(PhysicsShapeType2D.Capsule, shapeGroup.GetShape(capsuleShapeIndex).shapeType);
        ///
        ///        // Fetch the shapes and vertices from the shape group.
        ///        var shapes = new List<PhysicsShape2D>();
        ///        var vertices = new List<Vector2>();
        ///        shapeGroup.GetShapeData(shapes, vertices);
        ///
        ///        // Fetch the Circle shape and validate shape and vertex.
        ///        var circleShape = shapes[circleShapeIndex];
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, circleShape.shapeType);
        ///        Assert.AreApproximatelyEqual(1f, circleShape.radius);
        ///        Assert.AreEqual(new Vector2(-2f, 3f), vertices[circleShape.vertexStartIndex]);
        ///
        ///        // Fetch the Capsule shape and validate shape and vertices (2).
        ///        var capsuleShape = shapes[capsuleShapeIndex];
        ///        Assert.AreEqual(PhysicsShapeType2D.Capsule, capsuleShape.shapeType);
        ///        Assert.AreApproximatelyEqual(0.5f, capsuleShape.radius);
        ///        Assert.AreEqual(Vector2.down, vertices[capsuleShape.vertexStartIndex]);
        ///        Assert.AreEqual(Vector2.up, vertices[capsuleShape.vertexStartIndex + 1]);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void GetShapeData(List<PhysicsShape2D> shapes, List<Vector2> vertices)
        {
            shapes.AddRange(groupShapes);
            vertices.AddRange(groupVertices);
        }

        // Get all the shapes and vertices into native arrays.
        ///<summary>Gets a copy of both the shapes and vertices in the <see cref="PhysicsShapeGroup2D" />.</summary>
        ///<remarks>**NOTE**: Because this is a copy, changing the specified <c>shapes</c> and <c>vertices</c> arrays afterwards will not change the <see cref="PhysicsShapeGroup2D" />.</remarks>
        ///<param name="shapes">A <see cref="Unity.Collections.NativeArray{T}" /> that will be populated with a copy of all the shapes in the <see cref="PhysicsShapeGroup2D" />.</param>
        ///<param name="vertices">A <see cref="Unity.Collections.NativeArray{T}" /> that will be populated with a copy of all the vertices in the <see cref="PhysicsShapeGroup2D" />.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using Unity.Collections;
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        var circleShapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-2f, 3f),
        ///                radius: 1f
        ///            );
        ///
        ///        // Add a Capsule to the shape group.
        ///        var capsuleShapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shapeGroup.GetShape(circleShapeIndex).shapeType);
        ///        Assert.AreEqual(PhysicsShapeType2D.Capsule, shapeGroup.GetShape(capsuleShapeIndex).shapeType);
        ///
        ///        // Fetch the shapes and vertices from the shape group.
        ///        var shapes = new NativeArray<PhysicsShape2D>(shapeGroup.shapeCount, Allocator.Temp);
        ///        var vertices = new NativeArray<Vector2>(shapeGroup.vertexCount, Allocator.Temp);
        ///        shapeGroup.GetShapeData(shapes, vertices);
        ///
        ///        // Fetch the Circle shape and validate shape and vertex.
        ///        var circleShape = shapes[circleShapeIndex];
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, circleShape.shapeType);
        ///        Assert.AreApproximatelyEqual(1f, circleShape.radius);
        ///        Assert.AreEqual(new Vector2(-2f, 3f), vertices[circleShape.vertexStartIndex]);
        ///
        ///        // Fetch the Capsule shape and validate shape and vertices (2).
        ///        var capsuleShape = shapes[capsuleShapeIndex];
        ///        Assert.AreEqual(PhysicsShapeType2D.Capsule, capsuleShape.shapeType);
        ///        Assert.AreApproximatelyEqual(0.5f, capsuleShape.radius);
        ///        Assert.AreEqual(Vector2.down, vertices[capsuleShape.vertexStartIndex]);
        ///        Assert.AreEqual(Vector2.up, vertices[capsuleShape.vertexStartIndex + 1]);
        ///
        ///        // Dispose of the native arrays.
        ///        vertices.Dispose();
        ///        shapes.Dispose();
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void GetShapeData(NativeArray<PhysicsShape2D> shapes, NativeArray<Vector2> vertices)
        {
            if (!shapes.IsCreated || shapes.Length != shapeCount)
                throw new ArgumentException($"Cannot get shape data as the native shapes array length must be identical to the current custom shape count of {shapeCount}.", "shapes");

            if (!vertices.IsCreated || vertices.Length != vertexCount)
                throw new ArgumentException($"Cannot get shape data as the native vertices array length must be identical to the current custom vertex count of {shapeCount}.", "vertices");

            // Copy the shapes.
            for (var i = 0; i < shapeCount; ++i)
                shapes[i] = m_GroupState.m_Shapes[i];

            // Copy the vertices.
            for (var i = 0; i < vertexCount; ++i)
                vertices[i] = m_GroupState.m_Vertices[i];
        }

        // Get all the shape vertices.
        ///<summary>Gets a copy of the shape vertices in the <see cref="PhysicsShapeGroup2D" />.</summary>
        ///<remarks>**NOTE**: Because this is a copy, changing the specified shape  <c>vertices</c> list afterwards will not change the <see cref="PhysicsShapeGroup2D" />.</remarks>
        ///<param name="shapeIndex">The index of the shape stored in the <see cref="PhysicsShapeGroup2D" />. The shape index is zero-based with the shape group having a quantity of shapes specified by <see cref="PhysicsShapeGroup2D.shapeCount">shapeCount</see>.</param>
        ///<param name="vertices">A list that will be populated with a copy of all the shape vertices in the <see cref="PhysicsShapeGroup2D" />.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using System.Collections.Generic;
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Capsule to the shape group.
        ///        var shapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///
        ///        // Fetch the shape vertices from the shape group.
        ///        var vertices = new List<Vector2>();
        ///        shapeGroup.GetShapeVertices(shapeIndex, vertices);
        ///
        ///        // validate the Capsule vertices (2).
        ///        Assert.AreEqual(Vector2.down, vertices[0]);
        ///        Assert.AreEqual(Vector2.up, vertices[1]);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void GetShapeVertices(int shapeIndex, List<Vector2> vertices)
        {
            var shape = GetShape(shapeIndex);
            var shapeVertexCount = shape.vertexCount;

            vertices.Clear();
            if (vertices.Capacity < shapeVertexCount)
                vertices.Capacity = shapeVertexCount;

            var shapeVertices = groupVertices;
            var shapeVertexIndex = shape.vertexStartIndex;
            for (var n = 0; n < shapeVertexCount; ++n)
            {
                vertices.Add(shapeVertices[shapeVertexIndex++]);
            }
        }

        // Get the shape vertex at the specified index.
        ///<summary>Gets a single vertex of a shape. The vertex index is zero-based with the shape having a quantity of vertex specified by <see cref="PhysicsShape2D.vertexCount" />.</summary>
        ///<remarks>**NOTE**: When accessing multiple vertices, it is more efficient to do one of the following:
        ///
        ///- Get all the shape vertices using <see cref="PhysicsShapeGroup2D.GetShapeVertices">GetShapeVertices</see>
        ///- Get all the shape group vertices using <see cref="PhysicsShapeGroup2D.GetShapeData">GetShapeData</see>
        ///- Create the <see cref="PhysicsShapeGroup2D" /> with explicit shapes and vertices lists using the shape group <see cref="PhysicsShapeGroup2D(int, int)">Constructor</see></remarks>
        ///<param name="shapeIndex">The index of the shape stored in the <see cref="PhysicsShapeGroup2D" />. The shape index is zero-based with the shape group having a quantity of shapes specified by <see cref="PhysicsShapeGroup2D.shapeCount">shapeCount</see>.</param>
        ///<param name="vertexIndex">The index of the shape vertex stored in the <see cref="PhysicsShapeGroup2D" />. The vertex index is zero-based with the shape having a quantity of vertex specified by <see cref="PhysicsShape2D.vertexCount" />.</param>
        ///<returns>Returns the specified shape vertex.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Capsule to the shape group.
        ///        var shapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Fetch the shape vertices from the shape group.
        ///        var vertex0 = shapeGroup.GetShapeVertex(shapeIndex, vertexIndex: 0);
        ///        var vertex1 = shapeGroup.GetShapeVertex(shapeIndex, vertexIndex: 1);
        ///
        ///        // validate the Capsule vertices.
        ///        Assert.AreEqual(Vector2.down, vertex0);
        ///        Assert.AreEqual(Vector2.up, vertex1);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        ///<seealso cref="PhysicsShapeGroup2D.SetShapeVertex">SetShapeVertex</seealso>
        public Vector2 GetShapeVertex(int shapeIndex, int vertexIndex)
        {
            var index = GetShape(shapeIndex).vertexStartIndex + vertexIndex;
            if (index < 0 || index >= groupVertices.Count)
                throw new ArgumentOutOfRangeException(String.Format("Cannot get shape-vertex at index {0}. There are {1} shape-vertices.", index, shapeCount));

            return groupVertices[index];
        }

        // Set the shape vertex at the specified index.
        ///<summary>Sets a single vertex of a shape.</summary>
        ///<remarks>**NOTE**: When accessing multiple vertices, it is more efficient to do one of the following:
        ///
        ///- Get all the shape vertices using <see cref="PhysicsShapeGroup2D.GetShapeVertices">GetShapeVertices</see>
        ///- Get all the shape group vertices using <see cref="PhysicsShapeGroup2D.GetShapeData">GetShapeData</see>
        ///- Create the <see cref="PhysicsShapeGroup2D" /> with explicit shapes and vertices lists using the shape group <see cref="PhysicsShapeGroup2D(int, int)">Constructor</see></remarks>
        ///<param name="shapeIndex">The index of the shape stored in the <see cref="PhysicsShapeGroup2D" />. The shape index is zero-based with the shape group having a quantity of shapes specified by <see cref="PhysicsShapeGroup2D.shapeCount">shapeCount</see>.</param>
        ///<param name="vertexIndex">The index of the shape vertex stored in the <see cref="PhysicsShapeGroup2D" />. The vertex index is zero-based with the shape having a quantity of vertex specified by <see cref="PhysicsShape2D.vertexCount" />.</param>
        ///<param name="vertex">The value to set the shape vertex to.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Capsule to the shape group.
        ///        var shapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Fetch the shape vertices from the shape group.
        ///        var vertex0 = shapeGroup.GetShapeVertex(shapeIndex, vertexIndex: 0);
        ///        var vertex1 = shapeGroup.GetShapeVertex(shapeIndex, vertexIndex: 1);
        ///
        ///        // Validate the Capsule vertices.
        ///        Assert.AreEqual(Vector2.down, vertex0);
        ///        Assert.AreEqual(Vector2.up, vertex1);
        ///
        ///        // Set the shape vertices in the shape group.
        ///        shapeGroup.SetShapeVertex(shapeIndex, vertexIndex: 0, vertex: Vector2.left);
        ///        shapeGroup.SetShapeVertex(shapeIndex, vertexIndex: 1, vertex: Vector2.right);
        ///
        ///        // Fetch the shape vertices from the shape group.
        ///        vertex0 = shapeGroup.GetShapeVertex(shapeIndex, vertexIndex: 0);
        ///        vertex1 = shapeGroup.GetShapeVertex(shapeIndex, vertexIndex: 1);
        ///
        ///        // Validate the Capsule vertices.
        ///        Assert.AreEqual(Vector2.left, vertex0);
        ///        Assert.AreEqual(Vector2.right, vertex1);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        ///<seealso cref="PhysicsShapeGroup2D.GetShapeVertex">GetShapeVertex</seealso>
        public void SetShapeVertex(int shapeIndex, int vertexIndex, Vector2 vertex)
        {
            var index = GetShape(shapeIndex).vertexStartIndex + vertexIndex;
            if (index < 0 || index >= groupVertices.Count)
                throw new ArgumentOutOfRangeException(String.Format("Cannot set shape-vertex at index {0}. There are {1} shape-vertices.", index, shapeCount));

            groupVertices[index] = vertex;
        }

        // Set the shape radius at the specified index.
        ///<summary>Sets the radius of a shape.</summary>
        ///<param name="shapeIndex">The index of the shape stored in the <see cref="PhysicsShapeGroup2D" />. The shape index is zero-based with the shape group having a quantity of shapes specified by <see cref="PhysicsShapeGroup2D.shapeCount">shapeCount</see>.</param>
        ///<param name="radius">The value to set the shape radius to.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        var shapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: Vector2.zero,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Fetch the Circle shape and validate the radius.
        ///        var physicsShape = shapeGroup.GetShape(shapeIndex);
        ///        Assert.AreApproximatelyEqual(0.5f, physicsShape.radius);
        ///
        ///        // Update the Circle radius.
        ///        shapeGroup.SetShapeRadius(shapeIndex, 2f);
        ///
        ///        // Fetch the Circle shape and validate the radius.
        ///        physicsShape = shapeGroup.GetShape(shapeIndex);
        ///        Assert.AreApproximatelyEqual(2f, physicsShape.radius);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void SetShapeRadius(int shapeIndex, float radius)
        {
            // Fetch the shape.
            var shape = GetShape(shapeIndex);

            // Validate the specified radius.
            switch (shape.shapeType)
            {
                case PhysicsShapeType2D.Circle:
                    if (radius <= 0.0f)
                        throw new ArgumentException(string.Format("Circle radius {0} must be greater than zero.", radius));
                    break;

                case PhysicsShapeType2D.Capsule:
                    if (radius <= 0.00001f)
                        throw new ArgumentException(string.Format("Capsule radius: {0} is too small.", radius));
                    break;

                case PhysicsShapeType2D.Edges:
                case PhysicsShapeType2D.Polygon:
                    radius = Mathf.Max(0f, radius);
                    break;
            }

            // Set the radius and update the shape.
            shape.radius = radius;
            groupShapes[shapeIndex] = shape;
        }

        // Set the shape adjacent vertices.
        ///<summary>Sets the adjacent vertices of a shape.</summary>
        ///<remarks>**NOTE**: Calling this on a <see cref="PhysicsShape2D" /> that does not have a <see cref="PhysicsShape2D.shapeType">shapeType</see> of <see cref="PhysicsShapeType2D.Edges" /> will result in an exception being thrown.</remarks>
        ///<param name="shapeIndex">The index of the shape to be modified that is stored the <see cref="PhysicsShapeGroup2D" />.</param>
        ///<param name="useAdjacentStart">Sets the <see cref="PhysicsShape2D.useAdjacentStart" /> property of the selected shape.</param>
        ///<param name="useAdjacentEnd">Sets the <see cref="PhysicsShape2D.useAdjacentEnd" /> property of the selected shape.</param>
        ///<param name="adjacentStart">Sets the <see cref="PhysicsShape2D.adjacentStart" /> property of the selected shape.</param>
        ///<param name="adjacentEnd">Sets the <see cref="PhysicsShape2D.adjacentEnd" /> property of the selected shape.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using System;
        ///using System.Collections.Generic;
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a list of Edges.
        ///        var shapeIndex = shapeGroup.AddEdges
        ///            (
        ///                vertices: new List<Vector2>
        ///                {
        ///                    new Vector2(-4f, 0f),
        ///                    new Vector2(-2f, -0.5f),
        ///                    new Vector2(0f, 0f),
        ///                    new Vector2(2f, -0.5f),
        ///                    new Vector2(4f, 0f),
        ///                },
        ///
        ///                edgeRadius: 0.5f,
        ///
        ///                useAdjacentStart: true,
        ///                useAdjacentEnd: true,
        ///                adjacentStart: new Vector2(-5f, -1f),
        ///                adjacentEnd: new Vector2(6f, 2f)
        ///            );
        ///
        ///        // Fetch the actual shape created.
        ///        var physicsShape = shapeGroup.GetShape(shapeIndex);
        ///
        ///        // Validate what we created.
        ///        Assert.AreEqual(PhysicsShapeType2D.Edges, physicsShape.shapeType);
        ///        Assert.AreApproximatelyEqual(0.5f, physicsShape.radius);
        ///        Assert.AreEqual(5, physicsShape.vertexCount);
        ///        Assert.IsTrue(physicsShape.useAdjacentStart);
        ///        Assert.IsTrue(physicsShape.useAdjacentEnd);
        ///        Assert.AreEqual(new Vector2(-5f, -1f), physicsShape.adjacentStart);
        ///        Assert.AreEqual(new Vector2(6f, 2f), physicsShape.adjacentEnd);
        ///
        ///        // Set the adjacent vertices.
        ///        shapeGroup.SetShapeAdjacentVertices(
        ///            shapeIndex,
        ///            useAdjacentStart: true,
        ///            useAdjacentEnd: true,
        ///            adjacentStart: new Vector2(-10f, -5f),
        ///            adjacentEnd: new Vector2(12f, 3f));
        ///
        ///        // Fetch the updated shape.
        ///        physicsShape = shapeGroup.GetShape(shapeIndex);
        ///
        ///        // Validate what we updated.
        ///        Assert.IsTrue(physicsShape.useAdjacentStart);
        ///        Assert.IsTrue(physicsShape.useAdjacentEnd);
        ///        Assert.AreEqual(new Vector2(-10f, -5f), physicsShape.adjacentStart);
        ///        Assert.AreEqual(new Vector2(12f, 3f), physicsShape.adjacentEnd);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void SetShapeAdjacentVertices(
            int shapeIndex,
            bool useAdjacentStart,
            bool useAdjacentEnd,
            Vector2 adjacentStart,
            Vector2 adjacentEnd)
        {
            if (shapeIndex < 0 || shapeIndex >= shapeCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot set shape adjacent vertices at index {0}. There are {1} shapes(s).", shapeIndex, shapeCount));

            var shape = groupShapes[shapeIndex];

            if (shape.shapeType != PhysicsShapeType2D.Edges)
                throw new InvalidOperationException(String.Format("Cannot set shape adjacent vertices at index {0}. The shape must be of type {1} but it is of typee {2}.", shapeIndex, PhysicsShapeType2D.Edges, shape.shapeType));

            shape.useAdjacentStart = useAdjacentStart;
            shape.useAdjacentEnd = useAdjacentEnd;
            shape.adjacentStart = adjacentStart;
            shape.adjacentEnd = adjacentEnd;

            groupShapes[shapeIndex] = shape;
        }

        // Deletes the shape at the specified index.
        ///<summary>When destroying a shape at the specified <c>shapeIndex</c>, all other shapes that exist above the specified <c>shapeIndex</c> will have their shape indices updated appropriately.</summary>
        ///<param name="shapeIndex">The index of the shape stored the <see cref="PhysicsShapeGroup2D" />.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add two Circles to the shape group.
        ///        shapeGroup.AddCircle
        ///            (
        ///                center: Vector2.left,
        ///                radius: 1f
        ///            );
        ///        var shapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: Vector2.right,
        ///                radius: 1f
        ///            );
        ///
        ///        // Add a Box to the shape group.
        ///        shapeGroup.AddBox
        ///            (
        ///                center: new Vector2(3f, 2f),
        ///                size: new Vector2(1f, 1f)
        ///            );
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(1 + 1 + 1, shapeGroup.shapeCount);
        ///        Assert.AreEqual(1 + 1 + 4, shapeGroup.vertexCount);
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shapeGroup.GetShape(0).shapeType);
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shapeGroup.GetShape(1).shapeType);
        ///        Assert.AreEqual(PhysicsShapeType2D.Polygon, shapeGroup.GetShape(2).shapeType);
        ///
        ///        // Delete the second Circle shape.
        ///        shapeGroup.DeleteShape(shapeIndex);
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(1 + 1, shapeGroup.shapeCount);
        ///        Assert.AreEqual(1 + 4, shapeGroup.vertexCount);
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shapeGroup.GetShape(0).shapeType);
        ///        Assert.AreEqual(PhysicsShapeType2D.Polygon, shapeGroup.GetShape(1).shapeType);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void DeleteShape(int shapeIndex)
        {
            if (shapeIndex < 0 || shapeIndex >= shapeCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot delete shape at index {0}. There are {1} shapes(s).", shapeIndex, shapeCount));

            var shape = groupShapes[shapeIndex];
            var shapeVertexCount = shape.vertexCount;

            groupShapes.RemoveAt(shapeIndex);
            groupVertices.RemoveRange(shape.vertexStartIndex, shapeVertexCount);

            // NOTE: This makes the assumption that shape vertex usage is ordered.
            while (shapeIndex < groupShapes.Count)
            {
                var offsetShape = m_GroupState.m_Shapes[shapeIndex];
                offsetShape.vertexStartIndex -= shapeVertexCount;
                m_GroupState.m_Shapes[shapeIndex++] = offsetShape;
            }
        }

        // Get the shape at the specified index.
        ///<summary>Gets the <see cref="PhysicsShape2D" /> stored at the specified <c>shapeIndex</c>.</summary>
        ///<remarks>**NOTE**: Because the <see cref="PhysicsShape2D" /> is a struct, this is a copy of the shape therefore changing the shape afterwards will not change the <see cref="PhysicsShapeGroup2D" />.</remarks>
        ///<param name="shapeIndex">The index of the shape stored the <see cref="PhysicsShapeGroup2D" />. The shape index is zero-based with the shape group having a quantity of shapes specified by <see cref="PhysicsShapeGroup2D.shapeCount">shapeCount</see>.</param>
        ///<returns>Returns the shape stored at the specified <c>shapeIndex</c>.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        var circleShapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-2f, 3f),
        ///                radius: 1f
        ///            );
        ///
        ///        // Add a Capsule to the shape group.
        ///        var capsuleShapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Validate the contents.
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shapeGroup.GetShape(circleShapeIndex).shapeType);
        ///        Assert.AreEqual(PhysicsShapeType2D.Capsule, shapeGroup.GetShape(capsuleShapeIndex).shapeType);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public PhysicsShape2D GetShape(int shapeIndex)
        {
            if (shapeIndex < 0 || shapeIndex >= shapeCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot get shape at index {0}. There are {1} shapes(s).", shapeIndex, shapeCount));

            return groupShapes[shapeIndex];
        }

        // Add a circle shape.
        ///<summary>Adds a circle shape (<see cref="PhysicsShapeType2D.Circle" />) to the shape group.</summary>
        ///<remarks>A circle shape is comprised of a single vertex (center ) and a <c>radius</c> that extends around that vertex. This is the most memory efficient and fastest primitive to use in all use-cases.
        ///
        ///**NOTE**: A circle forms a closed shape and does have an interior therefore its interior is detectable by physics queries etc.</remarks>
        ///<param name="center">The center point of the circle shape. This is analogous to <see cref="Collider2D.offset" />.</param>
        ///<param name="radius">The radius of the circle defining a radius around the <c>center</c>. This is identical to <see cref="CircleCollider2D.radius" />.</param>
        ///<returns>Returns the shape index the shape was added to in the <see cref="PhysicsShapeGroup2D" />. This index is used as the main reference when retrieving a shape.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        CreateShape();
        ///        GetShapeFromCollider();
        ///    }
        ///
        ///    // Create a custom shape.
        ///    void CreateShape()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle.
        ///        var shapeIndex = shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-2f, 3f),
        ///                radius: 1f
        ///            );
        ///
        ///        // Fetch the actual shape created.
        ///        var physicsShape = shapeGroup.GetShape(shapeIndex);
        ///
        ///        // Validate what we created.
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, physicsShape.shapeType);
        ///        Assert.AreApproximatelyEqual(1f, physicsShape.radius);
        ///        Assert.AreEqual(1, physicsShape.vertexCount);
        ///    }
        ///
        ///    // Get a physics shape from a Collider.
        ///    void GetShapeFromCollider()
        ///    {
        ///        // Fetch the collider.
        ///        var collider = GetComponent<CircleCollider2D>();
        ///
        ///        // If the collider is not active and enabled then we'll get no shapes.
        ///        // Let's just quit if not.
        ///        if (!collider.isActiveAndEnabled)
        ///            return;
        ///
        ///        // Configure the collider.
        ///        collider.radius = 1f;
        ///
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Get the collider shapes.
        ///        collider.GetShapes(shapeGroup);
        ///
        ///        // Fetch the actual shape.
        ///        var physicsShape = shapeGroup.GetShape(0);
        ///
        ///        // Validate what we retrieved.
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, physicsShape.shapeType);
        ///        Assert.AreApproximatelyEqual(1f, physicsShape.radius);
        ///        Assert.AreEqual(1, physicsShape.vertexCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int AddCircle(Vector2 center, float radius)
        {
            if (radius <= 0.0f)
                throw new ArgumentException(string.Format("radius {0} must be greater than zero.", radius));

            // Add geometry.
            var vertexStartIndex = groupVertices.Count;
            groupVertices.Add(center);

            // Add shape.
            groupShapes.Add(
                new PhysicsShape2D
                {
                    shapeType = PhysicsShapeType2D.Circle,
                    radius = radius,
                    vertexStartIndex = vertexStartIndex,
                    vertexCount = 1
                });

            // Return the new shape index.
            return groupShapes.Count - 1;
        }

        // Add a capsule shape.
        ///<summary>Adds a capsule shape (<see cref="PhysicsShapeType2D.Capsule" />) to the shape group.</summary>
        ///<remarks>A capsule shape is comprised of a single edge shape defined by two vertices (vertex0 and <c>vertex1</c> ) and a <c>radius</c> that extends around the length of the edge and around the vertices.
        ///
        ///**NOTE**: A capsule forms a closed shape and does have an interior therefore its interior is detectable by physics queries etc.</remarks>
        ///<param name="vertex0">The position of one end of a capsule shape. This point represents the center point of a logical circle at the end of a capsule.</param>
        ///<param name="vertex1">The position of the opposite end of a capsule shape. This point represents the  center point of a logical circle at the opposite end of a capsule.</param>
        ///<param name="radius">The radius of the capsule defining a radius around the <c>vertex0</c> and <c>vertex1</c> and the area between them.</param>
        ///<returns>Returns the shape index the shape was added to in the <see cref="PhysicsShapeGroup2D" />. This index is used as the main reference when retrieving a shape.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        CreateShape();
        ///        GetShapeFromCollider();
        ///    }
        ///
        ///    // Create a custom shape.
        ///    void CreateShape()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Capsule.
        ///        var shapeIndex = shapeGroup.AddCapsule
        ///            (
        ///                vertex0: Vector2.down,
        ///                vertex1: Vector2.up,
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Fetch the actual shape created.
        ///        var physicsShape = shapeGroup.GetShape(shapeIndex);
        ///
        ///        // Validate what we created.
        ///        Assert.AreEqual(PhysicsShapeType2D.Capsule, physicsShape.shapeType);
        ///        Assert.AreApproximatelyEqual(0.5f, physicsShape.radius);
        ///        Assert.AreEqual(2, physicsShape.vertexCount);
        ///    }
        ///
        ///    // Get a physics shape from a Collider.
        ///    void GetShapeFromCollider()
        ///    {
        ///        // Fetch the collider.
        ///        var collider = GetComponent<CapsuleCollider2D>();
        ///
        ///        // If the collider is not active and enabled then we'll get no shapes.
        ///        // Let's just quit if not.
        ///        if (!collider.isActiveAndEnabled)
        ///            return;
        ///
        ///        // Configure the collider.
        ///        collider.size = new Vector2(1f, 2f);
        ///
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Get the collider shapes.
        ///        collider.GetShapes(shapeGroup);
        ///
        ///        // Fetch the actual shape.
        ///        var physicsShape = shapeGroup.GetShape(0);
        ///
        ///        // Validate what we retrieved.
        ///        Assert.AreEqual(PhysicsShapeType2D.Capsule, physicsShape.shapeType);
        ///        Assert.AreApproximatelyEqual(0.5f, physicsShape.radius);
        ///        Assert.AreEqual(2, physicsShape.vertexCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int AddCapsule(Vector2 vertex0, Vector2 vertex1, float radius)
        {
            if (radius <= 0.00001f)
                throw new ArgumentException(string.Format("radius: {0} is too small.", radius));

            // Add geometry.
            var vertexStartIndex = groupVertices.Count;
            groupVertices.Add(vertex0);
            groupVertices.Add(vertex1);

            groupShapes.Add(
                new PhysicsShape2D
                {
                    shapeType = PhysicsShapeType2D.Capsule,
                    radius = radius,
                    vertexStartIndex = vertexStartIndex,
                    vertexCount = 2
                });

            // Return the new shape index.
            return groupShapes.Count - 1;
        }

        ///<summary>Adds a box shape (<see cref="PhysicsShapeType2D.Polygon" />) to the shape group.</summary>
        ///<remarks>A box shape is a form of convex polygon with four vertices and an <c>edgeRadius</c> that extends around the four edges. The ability to add a box shape is a convenience only and does not represent an actual primitive shape.
        ///
        ///**NOTE**: A box forms a closed shape and does have an interior therefore its interior is detectable by physics queries etc.</remarks>
        ///<param name="center">The center point of the box shape. This is analogous to <see cref="Collider2D.offset" />.</param>
        ///<param name="size">The size of the box. This is identical to <see cref="BoxCollider2D.size" />.</param>
        ///<param name="angle">The angle in degrees the box should be rotated around the <c>center</c>.</param>
        ///<param name="edgeRadius">The radius extending around the edges of the box. This is identical to <see cref="BoxCollider2D.edgeRadius" />.</param>
        ///<returns>Returns the shape index the shape was added to in the <see cref="PhysicsShapeGroup2D" />. This index is used as the main reference when retrieving a shape.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        CreateShape();
        ///        GetShapeFromCollider();
        ///    }
        ///
        ///    // Create a custom shape.
        ///    void CreateShape()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Box (polygon with four vertices).
        ///        // NOTE: Both the angle and edgeRadius arguments are optional.
        ///        var shapeIndex = shapeGroup.AddBox
        ///            (
        ///                center: new Vector2(3f, 2f),
        ///                size: new Vector2(1f, 1f),
        ///                angle: 0f,
        ///                edgeRadius: 0f
        ///            );
        ///
        ///        // Fetch the actual shape created.
        ///        var physicsShape = shapeGroup.GetShape(shapeIndex);
        ///
        ///        // Validate what we created.
        ///        Assert.AreEqual(PhysicsShapeType2D.Polygon, physicsShape.shapeType);
        ///        Assert.AreEqual(4, physicsShape.vertexCount);
        ///        Assert.AreApproximatelyEqual(0f, physicsShape.radius);
        ///    }
        ///
        ///    // Get a physics shape from a Collider.
        ///    void GetShapeFromCollider()
        ///    {
        ///        // Fetch the collider.
        ///        var collider = GetComponent<BoxCollider2D>();
        ///
        ///        // If the collider is not active and enabled then we'll get no shapes.
        ///        // Let's just quit if not.
        ///        if (!collider.isActiveAndEnabled)
        ///            return;
        ///
        ///        // Configure the collider.
        ///        collider.offset = new Vector2(3f, 2f);
        ///        collider.size = new Vector2(1f, 1f);
        ///
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Get the collider shapes.
        ///        collider.GetShapes(shapeGroup);
        ///
        ///        // Fetch the actual shape.
        ///        var physicsShape = shapeGroup.GetShape(0);
        ///
        ///        // Validate what we retrieved.
        ///        Assert.AreEqual(PhysicsShapeType2D.Polygon, physicsShape.shapeType);
        ///        Assert.AreEqual(4, physicsShape.vertexCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int AddBox(Vector2 center, Vector2 size, [DefaultValue("0f")] float angle = 0f, [DefaultValue("0f")] float edgeRadius = 0f)
        {
            if (size.x <= MinVertexSeparation || size.y <= MinVertexSeparation)
                throw new ArgumentException(string.Format("size: {0} is too small. Vertex need to be separated by at least {1}", size, MinVertexSeparation));

            // Clamp the edge-radius.
            edgeRadius = Mathf.Max(0f, edgeRadius);

            // Convert to radians.
            angle *= Mathf.Deg2Rad;
            var cos = Mathf.Cos(angle);
            var sin = Mathf.Sin(angle);

            // Add geometry.
            static Vector2 Rotate(float cos, float sin, Vector2 value) { return new Vector2(cos * value.x - sin * value.y, sin * value.x + cos * value.y); }
            var halfSize = size * 0.5f;
            var vertex0 = center + Rotate(cos, sin, -halfSize);
            var vertex1 = center + Rotate(cos, sin, new Vector2(halfSize.x, -halfSize.y));
            var vertex2 = center + Rotate(cos, sin, halfSize);
            var vertex3 = center + Rotate(cos, sin, new Vector2(-halfSize.x, halfSize.y));

            var vertexStartIndex = groupVertices.Count;
            groupVertices.Add(vertex0);
            groupVertices.Add(vertex1);
            groupVertices.Add(vertex2);
            groupVertices.Add(vertex3);

            groupShapes.Add(
                new PhysicsShape2D
                {
                    shapeType = PhysicsShapeType2D.Polygon,
                    radius = edgeRadius,
                    vertexStartIndex = vertexStartIndex,
                    vertexCount = 4
                });

            // Return the new shape index.
            return groupShapes.Count - 1;
        }

        // Add a polygon shape.
        ///<summary>Adds a polygon shape (<see cref="PhysicsShapeType2D.Polygon" />) to the shape group.</summary>
        ///<remarks>A polygon shape is comprised of multiple edges (line segments) defined by all the specified <c>vertices</c>.
        ///
        ///**NOTE**: A polygon forms a closed shape and does have an interior therefore its interior is detectable by physics queries etc.</remarks>
        ///<param name="vertices">A list of vertices that represent a continuous set of edges of a convex polygon with each vertex connecting to the following vertex to form each edge. The final vertex implicitly connects to the first vertex. The maximum allowed list length is defined by <see cref="Physics2D.MaxPolygonShapeVertices" />.</param>
        ///<returns>Returns the shape index the shape was added to in the <see cref="PhysicsShapeGroup2D" />. This index is used as the main reference when retrieving a shape.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using System;
        ///using System.Collections.Generic;
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        CreateShape();
        ///        GetShapeFromCollider();
        ///    }
        ///
        ///    // Create a custom shape.
        ///    void CreateShape()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Polygon.
        ///        var shapeIndex = shapeGroup.AddPolygon
        ///            (
        ///                vertices: new List<Vector2>
        ///                {
        ///                    new Vector2(-1f, -1f),
        ///                    new Vector2(1f, -1f),
        ///                    new Vector2(1f, 1f),
        ///                    new Vector2(-1f, 1f)
        ///                }
        ///            );
        ///
        ///        // Fetch the actual shape created.
        ///        var physicsShape = shapeGroup.GetShape(shapeIndex);
        ///
        ///        // Validate what we created.
        ///        Assert.AreEqual(PhysicsShapeType2D.Polygon, physicsShape.shapeType);
        ///        Assert.AreEqual(4, physicsShape.vertexCount);
        ///    }
        ///
        ///    // Get a physics shape from a Collider.
        ///    void GetShapeFromCollider()
        ///    {
        ///        // Fetch the collider.
        ///        var collider = GetComponent<PolygonCollider2D>();
        ///
        ///        // If the collider is not active and enabled then we'll get no shapes.
        ///        // Let's just quit if not.
        ///        if (!collider.isActiveAndEnabled)
        ///            return;
        ///
        ///        // Configure the collider.
        ///        collider.SetPath(0,
        ///            new List<Vector2>()
        ///            {
        ///                new Vector2(-1f, -1f),
        ///                new Vector2(1f, -1f),
        ///                new Vector2(1f, 1f),
        ///                new Vector2(-1f, 1f)
        ///            });
        ///
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Get the collider shapes.
        ///        collider.GetShapes(shapeGroup);
        ///
        ///        // Fetch the actual shape.
        ///        var physicsShape = shapeGroup.GetShape(0);
        ///
        ///        // Validate what we retrieved.
        ///        Assert.AreEqual(PhysicsShapeType2D.Polygon, physicsShape.shapeType);
        ///        Assert.AreEqual(4, physicsShape.vertexCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int AddPolygon(List<Vector2> vertices)
        {
            var vertexCount = vertices.Count;

            if (vertexCount < 3 || vertexCount > Physics2D.MaxPolygonShapeVertices)
                throw new ArgumentException(string.Format("Vertex Count {0} must be >= 3 and <= {1}.", vertexCount, Physics2D.MaxPolygonShapeVertices));

            // Validate vertex separation (squared)
            float minSeparationSqr = MinVertexSeparation * MinVertexSeparation;
            for (var i = 1; i < vertexCount; ++i)
            {
                var vertex1 = vertices[i - 1];
                var vertex2 = vertices[i];

                if ((vertex2 - vertex1).sqrMagnitude <= minSeparationSqr)
                    throw new ArgumentException(string.Format("vertices: {0} and {1} are too close. Vertices need to be separated by at least {2}", vertex1, vertex2, minSeparationSqr));
            }

            // Add geometry.
            var vertexStartIndex = groupVertices.Count;
            groupVertices.AddRange(vertices);

            groupShapes.Add(
                new PhysicsShape2D
                {
                    shapeType = PhysicsShapeType2D.Polygon,
                    radius = 0f,
                    vertexStartIndex = vertexStartIndex,
                    vertexCount = vertexCount
                });

            // Return the new shape index.
            return groupShapes.Count - 1;
        }

        // Add an edge shape.
        ///<summary>Adds an edges shape (<see cref="PhysicsShapeType2D.Edges" />) to the shape group.</summary>
        ///<remarks>An edge shape is comprised of multiple edges (line segments) defined by all the specified <c>vertices</c> and an <c>edgeRadius</c> that extends around the all the edge(s).
        ///
        ///**NOTE**: Edges do not form closed a shape as they do not have any interior even if the first and last vertex were to overlap therefore the logical interior is not detectable by physics queries etc.</remarks>
        ///<param name="vertices">A list of vertices that represent a continuous set of edges with each vertex connecting to the following vertex to form each edge.</param>
        ///<param name="edgeRadius">The radius extending around each edge. This is identical to <see cref="EdgeCollider2D.edgeRadius" />.</param>
        ///<returns>Returns the shape index the shape was added to in the <see cref="PhysicsShapeGroup2D" />. This index is used as the main reference when retrieving a shape.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using System;
        ///using System.Collections.Generic;
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        CreateShape();
        ///        GetShapeFromCollider();
        ///    }
        ///
        ///    // Create a custom shape.
        ///    void CreateShape()
        ///    {
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a list of Edges.
        ///        var shapeIndex = shapeGroup.AddEdges
        ///            (
        ///                vertices: new List<Vector2>
        ///                {
        ///                    new Vector2(-4f, 0f),
        ///                    new Vector2(-2f, -0.5f),
        ///                    new Vector2(0f, 0f),
        ///                    new Vector2(2f, -0.5f),
        ///                    new Vector2(4f, 0f),
        ///                },
        ///                edgeRadius: 0.5f
        ///            );
        ///
        ///        // Fetch the actual shape created.
        ///        var physicsShape = shapeGroup.GetShape(shapeIndex);
        ///
        ///        // Validate what we created.
        ///        Assert.AreEqual(PhysicsShapeType2D.Edges, physicsShape.shapeType);
        ///        Assert.AreApproximatelyEqual(0.5f, physicsShape.radius);
        ///        Assert.AreEqual(5, physicsShape.vertexCount);
        ///    }
        ///
        ///    // Get a physics shape from a Collider.
        ///    void GetShapeFromCollider()
        ///    {
        ///        // Fetch the collider.
        ///        var collider = GetComponent<EdgeCollider2D>();
        ///
        ///        // If the collider is not active and enabled then we'll get no shapes.
        ///        // Let's just quit if not.
        ///        if (!collider.isActiveAndEnabled)
        ///            return;
        ///
        ///        // Configure the collider.
        ///        collider.SetPoints(
        ///            new List<Vector2>()
        ///            {
        ///                new Vector2(-4f, 0f),
        ///                new Vector2(-2f, -0.5f),
        ///                new Vector2(0f, 0f),
        ///                new Vector2(2f, -0.5f),
        ///                new Vector2(4f, 0f),
        ///            });
        ///        collider.edgeRadius = 0.5f;
        ///
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Get the collider shapes.
        ///        collider.GetShapes(shapeGroup);
        ///
        ///        // Fetch the actual shape.
        ///        var physicsShape = shapeGroup.GetShape(0);
        ///
        ///        // Validate what we retrieved.
        ///        Assert.AreEqual(PhysicsShapeType2D.Edges, physicsShape.shapeType);
        ///        Assert.AreApproximatelyEqual(0.5f, physicsShape.radius);
        ///        Assert.AreEqual(5, physicsShape.vertexCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int AddEdges(List<Vector2> vertices, [DefaultValue("0f")] float edgeRadius = 0f)
        {
            return AddEdges(
                vertices,
                useAdjacentStart: false,
                useAdjacentEnd: false,
                adjacentStart: Vector2.zero,
                adjacentEnd: Vector2.zero,
                edgeRadius);
        }

        // Add an edge shape with adjacent vertices.
        ///<summary>Adds an edge shape (<see cref="PhysicsShapeType2D.Edges" />) to the shape group supporting adjacent start and end vertices.</summary>
        ///<remarks>An edges shape is comprised of multiple edges (line segments) defined by all the specified <c>vertices</c> and an <c>edgeRadius</c> that extends around the all the edge(s).
        ///
        ///**NOTE**: Edges do not form closed a shape as they do not have any interior even if the first and last vertex were to overlap therefore the logical interior is not detectable by physics queries etc.</remarks>
        ///<param name="vertices">A list of vertices that represent a continuous set of edges with each vertex connecting to the following vertex to form each edge.</param>
        ///<param name="edgeRadius">The radius extending around each edge. This is identical to <see cref="EdgeCollider2D.edgeRadius" />.</param>
        ///<param name="useAdjacentStart">When the value is true, the <c>adjacentStart</c> argument is used. When the value is false, the <c>adjacentStart</c> argument is not used.</param>
        ///<param name="useAdjacentEnd">When the value is true, the <c>adjacentEnd</c> argument is used. When the value is false, the <c>adjacentEnd</c> argument is not used.</param>
        ///<param name="adjacentStart">Defines the position of a virtual point adjacent to the start vertex of an edge shape.</param>
        ///<param name="adjacentEnd">Defines the position of a virtual point adjacent to the end vertex of an edge shape.</param>
        ///<returns>Returns the shape index the shape was added to in the <see cref="PhysicsShapeGroup2D" />. This index is used as the main reference when retrieving a shape.</returns>
        public int AddEdges(
            List<Vector2> vertices,
            bool useAdjacentStart,
            bool useAdjacentEnd,
            Vector2 adjacentStart,
            Vector2 adjacentEnd,
            [DefaultValue("0f")] float edgeRadius = 0f)
        {
            var vertexCount = vertices.Count;
            if (vertexCount < 2)
                throw new ArgumentOutOfRangeException(string.Format("Vertex Count {0} must be >= 2.", vertexCount));

            // Clamp the edge-radius.
            edgeRadius = Mathf.Max(0f, edgeRadius);

            // Add geometry.
            var vertexStartIndex = groupVertices.Count;
            groupVertices.AddRange(vertices);

            groupShapes.Add(
                new PhysicsShape2D
                {
                    shapeType = PhysicsShapeType2D.Edges,
                    radius = edgeRadius,
                    vertexStartIndex = vertexStartIndex,
                    vertexCount = vertexCount,

                    useAdjacentStart = useAdjacentStart,
                    useAdjacentEnd = useAdjacentEnd,
                    adjacentStart = adjacentStart,
                    adjacentEnd = adjacentEnd
                });

            // Return the new shape index.
            return groupShapes.Count - 1;
        }
    }

    // Represents the closest points and distance between two colliders.
    ///<summary>Represents the separation or overlap of two <see cref="Collider2D" />.</summary>
    ///<remarks>The <see cref="ColliderDistance2D" /> primarily defines a point on the exterior of each <see cref="Collider2D" /> along with the <see cref="distance" /> between those two points.  The <see cref="distance" /> between them can be positive indicating that the <see cref="Collider2D" /> are separated (not overlapped), zero indicating that they are touching (but not overlapped) or negative indicating that they are overlapped.
    ///
    ///A <see cref="normal" /> is provided that is a normalized vector that points from <see cref="pointB" /> to <see cref="pointA" />.  This vector, when scaled with the <see cref="distance" />, provide a vector that can be used to move the <see cref="Collider2D" /> so that they are no longer overlapped (if the <see cref="distance" /> is negative) or so they are touching (if the <see cref="distance" /> is positive).
    ///
    ///A common use-case for this is solving overlaps between two <see cref="Collider2D" />, particularly when attached to a <see cref="Rigidbody2D" /> set to be <see cref="RigidbodyType2D.Kinematic" />.</remarks>
    ///<seealso cref="Physics2D.Distance" />
    ///<seealso cref="Collider2D.Distance" />
    ///<seealso cref="Rigidbody2D.Distance" />
    [StructLayout(LayoutKind.Sequential)]
    public struct ColliderDistance2D
    {
        private Vector2 m_PointA;
        private Vector2 m_PointB;
        private Vector2 m_Normal;
        private float m_Distance;
        private int m_IsValid;

        // The closest points between the colliders.
        ///<summary>A point on a <see cref="Collider2D" /> that is a specific <see cref="distance" /> away from <see cref="pointB" />.</summary>
        ///<remarks>This point lies on the exterior surface of a <see cref="Collider2D" />.</remarks>
        public Vector2 pointA { get { return m_PointA; } set { m_PointA = value; } }
        ///<summary>A point on a <see cref="Collider2D" /> that is a specific <see cref="distance" /> away from <see cref="pointA" />.</summary>
        ///<remarks>This point lies on the exterior surface of a <see cref="Collider2D" />.</remarks>
        public Vector2 pointB { get { return m_PointB; } set { m_PointB = value; } }

        // The normal with respect to point A.
        ///<summary>A normalized vector that points from <c>pointB</c> to <c>pointA</c>.</summary>
        ///<remarks>The normalized vector points from <see cref="pointB" /> to <see cref="pointA" />.  When it is scaled with the <see cref="distance" /> is produces a vector that can be used to move the <see cref="Collider2D" /> so that they are no longer overlapped (if the <see cref="distance" /> is negative) or so they are touching (if the <see cref="distance" /> is positive).</remarks>
        public Vector2 normal { get { return m_Normal; } }

        // Distance between the colliders.
        ///<summary>Gets the distance between two colliders.</summary>
        ///<remarks>The distance between two colliders is defined as the length of a <see cref="Vector2" /> between <see cref="pointA" /> and <see cref="pointB" />.  The <see cref="distance" /> between these points can be positive indicating that the <see cref="Collider2D" /> are separated (not overlapped), zero indicating that they are touching (but not overlapped) or negative indicating that they are overlapped.</remarks>
        public float distance { get { return m_Distance; } set { m_Distance = value; } }

        // Gets whether the distance is overlapped or not.
        ///<summary>Gets whether the <c>distance</c> represents an overlap or not.</summary>
        ///<remarks>The <see cref="distance" /> can be positive indicating that the <see cref="Collider2D" /> are separated (not overlapped), zero indicating that they are touching (but not overlapped) or negative indicating that they are overlapped.
        ///
        ///This property is therefore a check to see if <see cref="distance" /> is negative which indicates the <see cref="Collider2D" /> are overlapped.</remarks>
        public bool isOverlapped { get { return m_Distance < 0.0f; } }

        // Gets/Sets whether the distance is valid or not.
        ///<summary>Gets whether the distance is valid or not.</summary>
        ///<remarks>When a function returns a <see cref="ColliderDistance2D" /> struct, it may not be valid because the <see cref="Collider2D" /> used as distance references were not valid in some way due to them being disabled or not having any valid shapes.  This property indicates whether the other distance properties can be used and are valid or not.</remarks>
        ///<seealso cref="Physics2D.Distance" />
        ///<seealso cref="Collider2D.Distance" />
        ///<seealso cref="Rigidbody2D.Distance" />
        public bool isValid { get { return m_IsValid != 0; } set { m_IsValid = value ? 1 : 0; } }
    }

    ///<summary>A set of parameters for filtering contact results. Define the angle by referring to their position in world space, where 0 degrees is parallel to the positive x-axis, 90 degrees is parallel to the positive y-axis, 180 degrees is parallel to the negative x-axis, and 270 degrees is parallel to the negative y-axis.</summary>
    ///<remarks>Use a contact filter to precisely control which contact results get returned. This removes the need to filter the results later, is faster, and more convenient.
    ///
    ///If you are using a function that requires a <see cref="ContactFilter2D" />, but you don't want to perform any filtering, then use <see cref="ContactFilter2D.noFilter" />.
    ///
    ///For more information on using <see cref="ContactFilter2D" /> with casting, see: <see cref="Physics2D.CircleCast" />, <see cref="Physics2D.BoxCast" />, <see cref="Physics2D.CapsuleCast" />, <see cref="Physics2D.Linecast" />, <see cref="Physics2D.Raycast" />, <see cref="Collider2D.Raycast" />, <see cref="Collider2D.Cast" /> and <see cref="Rigidbody2D.Cast" />.
    ///
    ///For more information on using <see cref="ContactFilter2D" /> with overlapping areas, see: <see cref="Physics2D.OverlapPoint" />, <see cref="Physics2D.OverlapCircle" />, <see cref="Physics2D.OverlapBox" />, <see cref="Physics2D.OverlapArea" />, <see cref="Physics2D.OverlapCapsule" />, <see cref="Physics2D.OverlapCollider" />, <see cref="Rigidbody2D.OverlapCollider" /> and <see cref="Collider2D.OverlapCollider" />.
    ///
    ///For more information on using <see cref="ContactFilter2D" /> with contacts, see: <see cref="Physics2D.GetContacts" />,  <see cref="Collider2D.GetContacts" />, <see cref="Rigidbody2D.GetContacts" />,  <see cref="Physics2D.IsTouching" />, <see cref="Rigidbody2D.IsTouching" /> and <see cref="Collider2D.IsTouching" />.</remarks>
    [Serializable]
    [StructLayout(LayoutKind.Sequential)]
    [NativeClass("ContactFilter", "struct ContactFilter;")]
    [NativeHeader("Modules/Physics2D/Public/Collider2D.h")]
    public partial struct ContactFilter2D
    {
        ///<summary>Returns a new contact filter with a state where it will not filter any contacts.</summary>
        ///<remarks>The returned filter has the following state:
        ///
        ///- <see cref="ContactFilter2D.useTriggers" /> = <c>true</c>
        ///- <see cref="useLayerMask" /> = <c>false</c>
        ///- <see cref="layerMask" /> = <see cref="Physics2D.AllLayers" />
        ///
        ///- <see cref="useDepth" /> = <c>false</c>
        ///- <see cref="useOutsideDepth" /> = <c>false</c>
        ///- <see cref="minDepth" /> = -<see cref="Mathf.Infinity" />
        ///- <see cref="maxDepth" /> = <see cref="Mathf.Infinity" />
        ///
        ///- <see cref="useNormalAngle" /> = <c>false</c>
        ///- <see cref="useOutsideNormalAngle" /> = <c>false</c>
        ///- <see cref="minNormalAngle" /> = <c>0.0f</c>
        ///- <see cref="maxNormalAngle" /> = <see cref="ContactFilter2D.NormalAngleUpperLimit" />.</remarks>
        public static ContactFilter2D noFilter => _noFilter;
        // Immutable default-filter template; a value-type struct with no managed references, safe to persist across a code reload.
        [NoAutoStaticsCleanup]
        private static ContactFilter2D _noFilter = new()
        {
            useTriggers = true,
            useLayerMask = false,
            layerMask = Physics2D.AllLayers,

            useDepth = false,
            useOutsideDepth = false,
            minDepth = -Mathf.Infinity,
            maxDepth = Mathf.Infinity,

            useNormalAngle = false,
            useOutsideNormalAngle = false,
            minNormalAngle = 0.0f,
            maxNormalAngle = NormalAngleUpperLimit
        };

        extern private void CheckConsistency();

        ///<summary>Turns off layer mask filtering by setting <see cref="useLayerMask" /> to false.  The associated value of <see cref="layerMask" /> is not changed.</summary>
        public void ClearLayerMask() { useLayerMask = false; }
        ///<summary>Sets the <see cref="layerMask" /> filter property using the layerMask parameter provided and also enables layer mask filtering by setting <see cref="useLayerMask" /> to true.</summary>
        ///<param name="layerMask">The value used to set the <see cref="layerMask" />.</param>
        public void SetLayerMask(LayerMask layerMask) { this.layerMask = layerMask; useLayerMask = true; }

        ///<summary>Turns off depth filtering by setting <see cref="useDepth" /> to false.  The associated values of <see cref="minDepth" /> and <see cref="maxDepth" /> are not changed.</summary>
        public void ClearDepth() { useDepth = false; }
        ///<summary>Sets the <see cref="minDepth" /> and <see cref="maxDepth" /> filter properties and turns on depth filtering by setting <see cref="useDepth" /> to true.</summary>
        ///<param name="minDepth">The value used to set <see cref="minDepth" />.</param>
        ///<param name="maxDepth">The value used to set <see cref="maxDepth" />.</param>
        public void SetDepth(float minDepth, float maxDepth)
        {
            this.minDepth = minDepth;
            this.maxDepth = maxDepth;
            useDepth = true;
            CheckConsistency();
        }

        ///<summary>Turns off normal angle filtering by setting <see cref="useNormalAngle" /> to false. The associated values of <see cref="minNormalAngle" /> and <see cref="maxNormalAngle" /> are not changed.</summary>
        public void ClearNormalAngle() { useNormalAngle = false; }
        ///<summary>Sets the <see cref="minNormalAngle" /> and <see cref="maxNormalAngle" /> filter properties and turns on normal angle filtering by setting <see cref="useNormalAngle" /> to true.</summary>
        ///<param name="minNormalAngle">The value used to set the <see cref="minNormalAngle" />.</param>
        ///<param name="maxNormalAngle">The value used to set the <see cref="maxNormalAngle" />.</param>
        public void SetNormalAngle(float minNormalAngle, float maxNormalAngle)
        {
            this.minNormalAngle = minNormalAngle;
            this.maxNormalAngle = maxNormalAngle;
            useNormalAngle = true;
            CheckConsistency();
        }

        ///<summary>Given the current state of the contact filter, determine whether it would filter anything.</summary>
        ///<remarks>This property checks the following properties and returns true, indicating filtering is enabled; <see cref="ContactFilter2D.useTriggers" />, <see cref="useLayerMask" />, <see cref="useDepth" /> and <see cref="useNormalAngle" />.</remarks>
        public bool isFiltering { get { return !useTriggers || useLayerMask || useDepth || useNormalAngle; } }
        ///<summary>Checks if the <c>collider</c> is a trigger and should be filtered by the <see cref="ContactFilter2D.useTriggers" /> to be filtered.</summary>
        ///<remarks>Filtering is defined as including or excluding objects based upon a specific condition.  Trigger filtering checks the <see cref="Collider2D.isTrigger" /> and includes it if triggers are being used and excludes it otherwise.
        ///IsFilteringTriggers returns true when <see cref="ContactFilter2D.useTriggers" /> is set to false and <see cref="Collider2D.isTrigger" /> is true. This indicates the <c>collider</c> is filtered which means it should be excluded. IsFilteringTriggers returns false if otherwise.</remarks>
        ///<param name="collider">The <see cref="Collider2D" /> used to check for a trigger.</param>
        ///<returns>Returns true when <c>collider</c> is excluded by the filter and false if otherwise.</returns>
        ///<seealso cref="ContactFilter2D.useTriggers" />
        public bool IsFilteringTrigger(Collider2D collider) { return !useTriggers && collider.isTrigger; }
        ///<summary>Checks if the <see cref="GameObject.layer" /> for <c>obj</c> is included in the <see cref="layerMask" /> to be filtered.</summary>
        ///<remarks>Filtering is defined as including or excluding objects based upon a specific condition.  Layer mask filtering checks the <see cref="GameObject.layer" /> and includes it when it is within the layer mask and excludes it if otherwise.
        ///IsFilteringLayerMask returns true when <see cref="useLayerMask" /> is set to true and the <c>obj</c> layer mask is not included by <see cref="layerMask" />. This indicates the <c>obj</c> is filtered which means it should be excluded. IsFilteringLayerMask returns false if otherwise.</remarks>
        ///<param name="obj">The <see cref="GameObject" /> used to check the <see cref="GameObject.layer" />.</param>
        ///<returns>Returns true when <c>obj</c> is excluded by the filter and false if otherwise.</returns>
        ///<seealso cref="useDepth" />
        ///<seealso cref="maxDepth" />
        public bool IsFilteringLayerMask(GameObject obj) { return useLayerMask && ((layerMask & (1 << obj.layer)) == 0); }

        ///<summary>Checks if the <see cref="Transform" /> for <c>obj</c> is within the depth range to be filtered.</summary>
        ///<remarks>Filtering is defined as including or excluding objects based upon a specific condition.  Depth filtering checks the z-position of a <see cref="GameObject" /><see cref="Transform.position" /> and includes it when it is within the depth range and excludes it if otherwise.
        ///IsFilteringDepth returns true when <see cref="useDepth" /> is set to true and the <c>obj</c> transform's z-position is outside the depth defined by <see cref="minDepth" /> and <see cref="maxDepth" />. This indicates the <c>obj</c> is filtered which means it should be excluded. IsFilteringDepth returns false if otherwise.
        ///**Note:**: Setting <see cref="useOutsideDepth" /> to true inverts the function behavior and it returns opposite results.</remarks>
        ///<param name="obj">The <see cref="GameObject" /> used to check the z-position (depth) of <see cref="Transform.position" />.</param>
        ///<returns>Returns true when <c>obj</c> is excluded by the filter and false if otherwise.</returns>
        ///<seealso cref="useDepth" />
        ///<seealso cref="maxDepth" />
        public bool IsFilteringDepth(GameObject obj)
        {
            if (!useDepth)
                return false;

            if (minDepth > maxDepth)
            {
                var temp = minDepth; minDepth = maxDepth; maxDepth = temp;
            }

            var depth = obj.transform.position.z;

            var result = depth<minDepth || depth> maxDepth;
            if (useOutsideDepth)
                return !result;

            return result;
        }

        ///<summary>Checks if the angle of <c>normal</c> is within the normal angle range to be filtered.</summary>
        ///<remarks>Filtering is defined as including or excluding objects based upon a specific condition.  Normal angle filtering checks an angle and includes it when it is within the normal angle range and excludes it if otherwise.
        ///IsFilteringNormalAngle returns true when <see cref="useNormalAngle" /> is set to true and the angle is outside the normal angle range defined by <see cref="minNormalAngle" /> and <see cref="maxNormalAngle" />. This indicates the angle is filtered which means it should be excluded. IsFilteringNormalAngle returns false if otherwise.
        ///**Note:**: Setting <see cref="useOutsideNormalAngle" /> to true inverts the function behavior and it returns opposite results.</remarks>
        ///<param name="normal">The normal used to calculate an angle.</param>
        ///<returns>Returns true when <c>normal</c> is excluded by the filter and false if otherwise.</returns>
        ///<seealso cref="useNormalAngle" />
        ///<seealso cref="maxNormalAngle" />
        extern public bool IsFilteringNormalAngle(Vector2 normal);

        ///<summary>Checks if the <c>angle</c> is within the normal angle range to be filtered.</summary>
        ///<remarks>Filtering is defined as including or excluding objects based upon a specific condition.  Normal angle filtering checks an angle and includes it when it is within the normal angle range and excludes it if otherwise.
        ///IsFilteringNormalAngle returns true when <see cref="useNormalAngle" /> is set to true and the angle is outside the normal angle range defined by <see cref="minNormalAngle" /> and <see cref="maxNormalAngle" />. This indicates the angle is filtered which means it should be excluded. IsFilteringNormalAngle returns false if otherwise.
        ///**Note:**: Setting <see cref="useOutsideNormalAngle" /> to true inverts the function behavior and it returns opposite results.</remarks>
        ///<param name="angle">The angle used for comparison in the filter.</param>
        ///<returns>Returns true when <c>angle</c> is excluded by the filter and false if otherwise.</returns>
        ///<seealso cref="useNormalAngle" />
        ///<seealso cref="maxNormalAngle" />
        public bool IsFilteringNormalAngle(float angle)
        {
            return IsFilteringNormalAngleUsingAngle(angle);
        }

        extern private bool IsFilteringNormalAngleUsingAngle(float angle);

        ///<summary>Sets to filter contact results based on trigger collider involvement.</summary>
        ///<remarks>Set to false to ignore any contacts involving trigger colliders. Set to true, to filter any contacts involving triggers and return such contacts.
        ///
        ///**Note:** Contacts filtered by involved trigger colliders, are not filtered by the normal angles of the collisions, so <see cref="useNormalAngle" />, <see cref="minNormalAngle" /> and <see cref="maxNormalAngle" /> are ignored. Other active contacts will continue to be filtered by the normal angles of the collisions.</remarks>
        [NativeName("m_UseTriggers")]
        public bool useTriggers;
        ///<summary>Sets the contact filter to filter results by layer mask.</summary>
        [NativeName("m_UseLayerMask")]
        public bool useLayerMask;
        ///<summary>Sets the contact filter to filter the results by depth using <see cref="minDepth" /> and <see cref="maxDepth" />.</summary>
        [NativeName("m_UseDepth")]
        public bool useDepth;
        ///<summary>Sets the contact filter to filter within the <see cref="minDepth" /> and <see cref="maxDepth" /> range, or outside that range.</summary>
        ///<remarks>::ref::useOutsideDepth uses the range between <see cref="minDepth" /> and <see cref="maxDepth" /> to filter depth.
        ///Set <c>useOutsideDepth</c> to true to only return object depth outside that range.
        ///Set <c>useOutsideDepth</c> to false to only return object depth within that range. It is false by default.</remarks>
        ///<seealso cref="minDepth" />
        ///<seealso cref="maxDepth" />
        ///<seealso cref="useDepth" />
        [NativeName("m_UseOutsideDepth")]
        public bool useOutsideDepth;
        ///<summary>Sets the contact filter to filter the results by the collision's normal angle using <see cref="minNormalAngle" /> and <see cref="maxNormalAngle" />.</summary>
        [NativeName("m_UseNormalAngle")]
        public bool useNormalAngle;
        ///<summary>Sets the contact filter to filter within the <see cref="minNormalAngle" /> and <see cref="maxNormalAngle" /> range, or outside that range.</summary>
        ///<remarks>::ref::useOutsideNormalAngle uses the range between <see cref="minNormalAngle" /> and <see cref="maxNormalAngle" /> to filter the normal angle.
        ///Set <c>useOutsideNormalAngle</c> to true to only return normal angle outside that range.
        ///Set <c>useOutsideNormalAngle</c> to false to only return normal angle within that range. It is false by default.</remarks>
        ///<seealso cref="minNormalAngle" />
        ///<seealso cref="maxNormalAngle" />
        ///<seealso cref="useNormalAngle" />
        [NativeName("m_UseOutsideNormalAngle")]
        public bool useOutsideNormalAngle;
        ///<summary>Sets the contact filter to filter the results that only include <see cref="Collider2D" /> on the layers defined by the layer mask.</summary>
        ///<remarks>This field takes effect if <see cref="useLayerMask" /> is true.</remarks>
        ///<seealso cref="LayerMask" />
        [NativeName("m_LayerMask")]
        public LayerMask layerMask;
        ///<summary>Sets the contact filter to filter the results to only include <see cref="Collider2D" /> with a Z coordinate (depth) greater than this value.</summary>
        ///<remarks>This is only used if <see cref="useDepth" /> is true.  If the <c>minDepth</c> is set to -<see cref="Mathf.Infinity" /> or <see cref="Mathf.Infinity" /> then the lowest possible depth is used.</remarks>
        ///<seealso cref="Transform" />
        [NativeName("m_MinDepth")]
        public float minDepth;
        ///<summary>Sets the contact filter to filter the results to only include <see cref="Collider2D" /> with a Z coordinate (depth) less than this value.</summary>
        ///<remarks>This is only used if <see cref="useDepth" /> is true.  If the <c>maxDepth</c> is set to -<see cref="Mathf.Infinity" /> or <see cref="Mathf.Infinity" /> then the highest possible depth is used.</remarks>
        ///<seealso cref="Transform" />
        [NativeName("m_MaxDepth")]
        public float maxDepth;
        ///<summary>Sets the contact filter to filter the results to only include contacts with collision normal angles that are greater than this angle.</summary>
        ///<remarks>This is only used if <see cref="useNormalAngle" /> is true.  If the <c>minNormalAngle</c> is set to -<see cref="Mathf.Infinity" /> or <see cref="Mathf.Infinity" /> then the lowest possible angle is used.</remarks>
        ///<seealso cref="ContactPoint2D.normal" />
        [NativeName("m_MinNormalAngle")]
        public float minNormalAngle;
        ///<summary>Sets the contact filter to filter the results to only include contacts with collision normal angles that are less than this angle.</summary>
        ///<remarks>This is only used if <see cref="useNormalAngle" /> is true.  If the <c>maxNormalAngle</c> is set to -<see cref="Mathf.Infinity" /> or <see cref="Mathf.Infinity" /> then the highest possible angle is used.</remarks>
        ///<seealso cref="ContactPoint2D.normal" />
        [NativeName("m_MaxNormalAngle")]
        public float maxNormalAngle;

        ///<summary>A constant of the maximum normal angle used of <c>359.9999f</c>.</summary>
        public const float NormalAngleUpperLimit = 359.9999f;

        // This can be removed once all the legacy calls that use this filter are eventually deprecated and removed.
        static internal ContactFilter2D CreateLegacyFilter(int layerMask, float minDepth, float maxDepth)
        {
            var contactFilter = new ContactFilter2D();
            contactFilter.useTriggers = Physics2D.queriesHitTriggers;
            contactFilter.SetLayerMask(layerMask);
            contactFilter.SetDepth(minDepth, maxDepth);
            return contactFilter;
        }
    }

    // Describes a collision.
    ///<summary>Collision details returned by 2D physics callback functions.</summary>
    ///<remarks>The collisions details are returned by <c>OnCollisionEnter2D</c>, <c>OnCollisionStay2D</c> and <c>OnCollisionExit2D</c> callbacks. It details which <see cref="Collider2D" /> and <see cref="Rigidbody2D" /> pairs are involved in the collision as well as contact points where the <see cref="Collider2D" /> meet. **Note:** During the <c>OnCollisionExit2D</c> event, there are no contacts to be retrieved.</remarks>
    [RequiredByNativeCode]
    [StructLayout(LayoutKind.Sequential)]
    public partial class Collision2D
    {
        internal EntityId m_Collider;
        internal EntityId m_OtherCollider;
        internal EntityId m_Rigidbody;
        internal EntityId m_OtherRigidbody;
        internal Vector2 m_RelativeVelocity;
        internal int m_Enabled;
        internal int m_ContactCount;
        internal ContactPoint2D[] m_ReusedContacts;
        internal ContactPoint2D[] m_LegacyContacts;

        // Return the appropriate contacts array.
        private ContactPoint2D[] GetContacts_Internal() { return m_LegacyContacts == null ? m_ReusedContacts : m_LegacyContacts; }

        // The first collider involved in the collision.
        ///<summary>The incoming <see cref="Collider2D" /> involved in the collision with the <see cref="otherCollider" />.</summary>
        ///<remarks>This collider is attached to the <see cref="Collision2D.rigidbody" />.</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using System.Collections;
        ///
        ///public class ExampleClass : MonoBehaviour
        ///{
        ///    void OnCollisionEnter2D(Collision2D coll)
        ///    {
        ///        // If the Collider2D component is enabled on the collided object
        ///        if (coll.collider == true)
        ///        {
        ///            // Disables the Collider2D component
        ///            coll.collider.enabled = false;
        ///        }
        ///    }
        ///}
        ///]]></code>
        ///</example>
        ///<seealso cref="Collider2D" />
        ///<seealso cref="Rigidbody2D" />
        public Collider2D collider { get { return Object.FindObjectFromInstanceID(m_Collider) as Collider2D; } }

        // The other collider in contact.
        ///<summary>The other <see cref="Collider2D" /> involved in the collision with the <see cref="collider" />.</summary>
        ///<remarks>This collider is attached to the <see cref="Collision2D.otherRigidbody" />.</remarks>
        ///<seealso cref="Collider2D" />
        ///<seealso cref="Rigidbody2D" />
        public Collider2D otherCollider { get { return Object.FindObjectFromInstanceID(m_OtherCollider) as Collider2D; } }

        // The rigid-body involved in the collision.
        ///<summary>The incoming <see cref="Rigidbody2D" /> involved in the collision with the <see cref="otherRigidbody" />.</summary>
        ///<remarks>This may be null if the <see cref="Collision2D.collider" /> is not attached to a <see cref="Rigidbody2D" />.</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using System.Collections;
        ///
        ///public class ExampleClass : MonoBehaviour
        ///{
        ///    void OnCollisionEnter2D(Collision2D collision2D)
        ///    {
        ///        //If the object we collided with was a Runner and not a Catcher.
        ///        if (collision2D.transform.name == "Runner")
        ///        {
        ///            StartCoroutine(StuckInTheMud(collision2D));
        ///        }
        ///    }
        ///
        ///    //Freeze the object in position for 5 seconds
        ///    public IEnumerator StuckInTheMud(Collision2D victim)
        ///    {
        ///        victim.rigidbody.bodyType = RigidbodyType2D.Kinematic;
        ///        yield return new WaitForSeconds(5f);
        ///        victim.rigidbody.bodyType = RigidbodyType2D.Dynamic;
        ///    }
        ///}
        ///]]></code>
        ///</example>
        ///<seealso cref="Collider2D" />
        ///<seealso cref="Rigidbody2D" />
        public Rigidbody2D rigidbody { get { return Object.FindObjectFromInstanceID(m_Rigidbody) as Rigidbody2D; } }

        // The other rigid-body involved in the collision.
        ///<summary>The other <see cref="Rigidbody2D" /> involved in the collision with the <see cref="rigidbody" />.</summary>
        ///<remarks>This may be null if the <see cref="Collision2D.otherCollider" /> is not attached to a <see cref="Rigidbody2D" />.</remarks>
        ///<seealso cref="Collider2D" />
        ///<seealso cref="Rigidbody2D" />
        public Rigidbody2D otherRigidbody { get { return Object.FindObjectFromInstanceID(m_OtherRigidbody) as Rigidbody2D; } }

        // The transform of the rigid-body or if no rigid-body is available (static collider), the collider transform.
        ///<summary>The Transform of the incoming object involved in the collision.</summary>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using System.Collections;
        ///
        ///public class ExampleClass : MonoBehaviour
        ///{
        ///    void OnCollisionEnter2D(Collision2D collision2D)
        ///    {
        ///        //If the object we collided with was an Asteroid.
        ///        if (collision2D.transform.name == "Asteroid")
        ///        {
        ///            //Sets this object as the new parent of the Transform of the object involved in the collision.
        ///            collision2D.transform.SetParent(gameObject.transform);
        ///        }
        ///    }
        ///}
        ///]]></code>
        ///</example>
        ///<seealso cref="Transform" />
        public Transform transform { get { return rigidbody != null ? rigidbody.transform : collider.transform; } }

        // The game object of the rigid-body or if no rigid-body is available, the collider transform.
        ///<summary>The incoming GameObject involved in the collision.</summary>
        ///<seealso cref="GameObject" />
        public GameObject gameObject { get { return rigidbody != null ? rigidbody.gameObject : collider.gameObject; } }

        // The relative velocity between the two bodies.
        ///<summary>The relative linear velocity of the two colliding objects (RO).</summary>
        ///<example>
        ///  <code><![CDATA[
        /// // Play a sound when we hit an object with a big velocity
        ///using UnityEngine;
        ///using System.Collections;
        ///
        ///public class ExampleClass : MonoBehaviour
        ///{
        ///    AudioSource audioSource;
        ///
        ///    void Start()
        ///    {
        ///        audioSource = GetComponent<AudioSource>();
        ///    }
        ///
        ///    void OnCollisionEnter2D(Collision2D collision)
        ///    {
        ///        if (collision.relativeVelocity.magnitude > 2)
        ///            audioSource.Play();
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public Vector2 relativeVelocity { get { return m_RelativeVelocity; } }

        // Whether the collision is enabled or not.  Effectors can temporarily disable a collision but all collisions are reported.
        ///<summary>Indicates whether the collision response or reaction is enabled or disabled.</summary>
        ///<remarks>Certain features can disable collision responses which means you still get the collision callback but no response or reaction happens. For example, two boxes going through each other without any visible reaction. The platform effector is one such feature that can disable a collision response.</remarks>
        ///<seealso cref="ContactPoint2D.enabled" />
        public bool enabled { get { return m_Enabled == 1; } }

        // The contact points.
        ///<summary>The specific points of contact with the incoming Collider2D. You should avoid using this as it produces memory garbage. Use <see cref="GetContact" /> or <see cref="GetContacts" /> instead.</summary>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using System.Collections;
        ///
        ///public class ExampleClass : MonoBehaviour
        ///{
        ///    public GameObject explosion;
        ///
        ///    void OnCollisionEnter2D(Collision2D coll)
        ///    {
        ///        // If a missile hits this object
        ///        if (coll.transform.tag == "Missile")
        ///        {
        ///            Debug.Log("HIT!");
        ///
        ///            // Spawn an explosion at each point of contact
        ///            foreach (ContactPoint2D missileHit in coll.contacts)
        ///            {
        ///                Vector2 hitPoint = missileHit.point;
        ///                Instantiate(explosion, new Vector3(hitPoint.x, hitPoint.y, 0), Quaternion.identity);
        ///            }
        ///        }
        ///    }
        ///}
        ///]]></code>
        ///</example>
        ///<seealso cref="Collider2D" />
        public ContactPoint2D[] contacts
        {
            get
            {
                if (m_LegacyContacts == null)
                {
                    m_LegacyContacts = new ContactPoint2D[m_ContactCount];
                    Array.Copy(m_ReusedContacts, m_LegacyContacts, m_ContactCount);
                }

                return m_LegacyContacts;
            }
        }

        // Returns the number of contacts.
        ///<summary>Gets the number of contacts for this collision.</summary>
        ///<remarks>A collision can involve multiple contact points. This property allows you to determine how many are involved. You can use this value when retrieving contacts using <see cref="GetContact" /> or <see cref="GetContacts" />.</remarks>
        public int contactCount { get { return m_ContactCount; } }

        // Get contact at specific index.
        ///<summary>Gets the contact point at the specified <c>index</c>.</summary>
        ///<remarks>You can retrieve individual contacts for this collision by <c>index</c>. You can use <see cref="contactCount" /> to determine how many contacts are available.</remarks>
        ///<param name="index">The index of the contact to retrieve.</param>
        ///<returns>The contact at the specified <c>index</c>.</returns>
        ///<seealso cref="contactCount" />
        ///<seealso cref="GetContacts" />
        public ContactPoint2D GetContact(int index)
        {
            if (index < 0 || index >= m_ContactCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot get contact at index {0}. There are {1} contact(s).", index, m_ContactCount));

            return GetContacts_Internal()[index];
        }

        // Get contacts for this collision.
        ///<summary>Retrieves all contact points for contacts between <see cref="collider" /> and <see cref="otherCollider" />.</summary>
        ///<remarks>When retrieving contacts, you should ensure that the provided array is large enough to contain all the contacts you are interested in. The array is usually reused, so it should be large enough to return a reasonable quantity of contacts. This function also means that no allocations occur, which means no work is produced for the garbage collector.
        ///
        ///You can check how many contacts are available using <see cref="contactCount" />.</remarks>
        ///<param name="contacts">An array of <see cref="ContactPoint2D" /> used to receive the results.</param>
        ///<returns>Returns the number of contacts placed in the <c>contacts</c> array.</returns>
        ///<seealso cref="Physics2D.GetContacts" />
        ///<seealso cref="Collider2D.GetContacts" />
        ///<seealso cref="Rigidbody2D.GetContacts" />
        public int GetContacts(ContactPoint2D[] contacts)
        {
            if (contacts == null)
                throw new NullReferenceException("Cannot get contacts as the provided array is NULL.");

            var contactCount = Mathf.Min(m_ContactCount, contacts.Length);
            Array.Copy(GetContacts_Internal(), contacts, contactCount);
            return contactCount;
        }

        // Get contacts for this collision.
        ///<summary>Retrieves all contact points for contacts between <see cref="collider" /> and <see cref="otherCollider" />.</summary>
        ///<remarks>When retrieving contacts, try to make the provided list large enough to contain all the contacts you need. If the list is not large enough, Unity will automatically increase its size so that it can contain all the contacts. The list is usually reused, so it should be large enough to return a reasonable quantity of contacts. If the list does not have to be increased in size then this function will not allocate any memory, which means no work is produced for the garbage collector.
        ///
        ///You can check how many contacts are available using <see cref="contactCount" />.</remarks>
        ///<param name="contacts">A list of <see cref="ContactPoint2D" /> used to receive the results.</param>
        ///<returns>Returns the number of contacts placed in the <c>contacts</c> list.</returns>
        ///<seealso cref="Physics2D.GetContacts" />
        ///<seealso cref="Collider2D.GetContacts" />
        ///<seealso cref="Rigidbody2D.GetContacts" />
        public int GetContacts(List<ContactPoint2D> contacts)
        {
            if (contacts == null)
                throw new NullReferenceException("Cannot get contacts as the provided list is NULL.");

            contacts.Clear();

            // Copy only the number of contacts available as this array can become larger than the number of current contacts.
            var contactArray = GetContacts_Internal();
            for (var i = 0; i < m_ContactCount; ++i)
            {
                contacts.Add(contactArray[i]);
            }

            return m_ContactCount;
        }

        [RequiredByNativeCode]
        internal static Collision2D CreateNew(EntityId collider, EntityId otherCollider, EntityId rigidbody, EntityId otherRigidbody, Vector2 relativeVelocity, int enabled, int contactCount, ContactPoint2D[] reusedContacts, ContactPoint2D[] legacyContacts)
        {
            var ret = new Collision2D();
            ret.AssignFields(collider, otherCollider, rigidbody, otherRigidbody, relativeVelocity, enabled, contactCount, reusedContacts, legacyContacts);
            return ret;
        }

        [RequiredByNativeCode]
        internal static void AssignFieldsFromNative(Collision2D self, EntityId collider, EntityId otherCollider, EntityId rigidbody, EntityId otherRigidbody, Vector2 relativeVelocity, int enabled, int contactCount, ContactPoint2D[] reusedContacts, ContactPoint2D[] legacyContacts)
        {
            self.AssignFields(collider, otherCollider, rigidbody, otherRigidbody, relativeVelocity, enabled, contactCount, reusedContacts, legacyContacts);
        }

        internal void AssignFields(EntityId collider, EntityId otherCollider, EntityId rigidbody, EntityId otherRigidbody, Vector2 relativeVelocity, int enabled, int contactCount, ContactPoint2D[] reusedContacts, ContactPoint2D[] legacyContacts)
        {
            m_Collider = collider;
            m_OtherCollider = otherCollider;
            m_Rigidbody = rigidbody;
            m_OtherRigidbody = otherRigidbody;
            m_RelativeVelocity = relativeVelocity;
            m_Enabled = enabled;
            m_ContactCount = contactCount;
            m_ReusedContacts = reusedContacts;
            m_LegacyContacts = legacyContacts;
        }
    };

