        extern private ColliderDistance2D Distance_Internal([NotNull] Collider2D collider);

        [NativeMethod("DistanceFrom")]
        extern private ColliderDistance2D DistanceFrom_Internal(
            Vector2 thisPosition, float thisAngle,
            [NotNull] Collider2D collider, Vector2 position, float angle);

        // Get the closest point to position on this rigidbody.
        ///<summary>Returns a point on the perimeter of all enabled Colliders attached to this Rigidbody that is closest to the specified <c>position</c>.</summary>
        ///<remarks>This function provides the ability to calculate the closest point of a specified <c>position</c> to the perimeter of any enabled <see cref="Collider2D" /> type attached to this Rigidbody.
        ///
        ///  In the case where the <c>position</c> is inside any of the enabled <see cref="Collider2D" /> attached to this Rigidbody, the input <c>position</c> is returned instead.</remarks>
        ///<param name="position">The position from which to find the closest point on this Rigidbody.</param>
        ///<returns>A point on the perimeter of a Collider attached to this rigidbody that is closest to the specified <c>position</c>.</returns>
        public Vector2 ClosestPoint(Vector2 position)
        {
            return Physics2D.ClosestPoint(position, this);
        }

        // Adds /force/ (defined in global space) to the rigidbody center-of-mass.  No torque is therefore generated.
        [ExcludeFromDocs]
        public void AddForce(Vector2 force) { AddForce_Internal(force, ForceMode2D.Force); }
        ///<summary>Apply a force to the rigidbody.</summary>
        ///<remarks>The force is specified as two separate components in the X and Y directions (there is no Z direction in 2D physics). The object will be accelerated by the force according to the law force = mass x acceleration - the larger the mass, the greater the force required to accelerate to a given speed.
        ///
        ///If you don’t specify a ForceMode2D the default will be used.
        ///The default in this case is ForceMode2D.Force which adds force over time, using mass.
        ///
        ///To use the example scripts below, drag and drop your chosen script onto a Sprite in the Hierarchy. Make sure that the Sprite has a Rigidbody2D component.</remarks>
        ///<param name="force">Components of the force in the X and Y axes.</param>
        ///<param name="mode">The method used to apply the specified force.</param>
        ///<example>
        ///  <code><![CDATA[
        /// // The sprite will fall under its weight.  After a short time the
        /// // sprite will start its upwards travel due to the thrust force that
        /// // is added in the opposite direction.
        ///
        ///using UnityEngine;
        ///using System.Collections;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    public Texture2D tex;
        ///
        ///    private Rigidbody2D rb2D;
        ///    private Sprite mySprite;
        ///    private SpriteRenderer sr;
        ///    private float thrust = 1f;
        ///
        ///    void Awake()
        ///    {
        ///        sr = gameObject.AddComponent<SpriteRenderer>();
        ///        rb2D = gameObject.AddComponent<Rigidbody2D>();
        ///    }
        ///
        ///    void Start()
        ///    {
        ///        mySprite = Sprite.Create(tex, new Rect(0.0f, 0.0f, 128.0f, 128.0f), new Vector2(0.5f, 0.5f), 100.0f);
        ///
        ///        sr.color = new Color(0.9f, 0.9f, 0.5f, 1.0f);
        ///        sr.sprite = mySprite;
        ///        transform.position = new Vector3(0.0f, -2.0f, 0.0f);
        ///    }
        ///
        ///    void FixedUpdate()
        ///    {
        ///        rb2D.AddForce(transform.up * thrust);
        ///        // Alternatively, specify the force mode, which is ForceMode2D.Force by default
        ///        rb2D.AddForce(transform.up * thrust, ForceMode2D.Impulse);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        ///<seealso cref="AddForceAtPosition" />
        ///<seealso cref="AddTorque" />
        ///<seealso cref="mass" />
        ///<seealso cref="linearVelocity" />
        ///<seealso cref="AddForce" />
        ///<seealso cref="ForceMode2D" />
        public void AddForce(Vector2 force, [DefaultValue("ForceMode2D.Force")] ForceMode2D mode = ForceMode2D.Force) { AddForce_Internal(force, mode); }
        ///<summary>Adds a force to the X component of the <see cref="Rigidbody2D.linearVelocity" /> only leaving the Y component of the world space <see cref="Rigidbody2D.linearVelocity" /> untouched.</summary>
        ///<param name="force">The force to add to the X component of the Linear Velocity in the world space of the <see cref="Rigidbody2D" />.</param>
        ///<param name="mode">The method used to apply the specified force.</param>
        ///<seealso cref="Rigidbody2D.AddForceY" />
        ///<seealso cref="Rigidbody2D.AddForce" />
        public void AddForceX(float force, [DefaultValue("ForceMode2D.Force")] ForceMode2D mode = ForceMode2D.Force) { AddForce_Internal(new Vector2(force, 0f), mode); }
        ///<summary>Adds a force to the Y component of the <see cref="Rigidbody2D.linearVelocity" /> only leaving the X component of the world space <see cref="Rigidbody2D.linearVelocity" /> untouched.</summary>
        ///<param name="force">The force to add to the Y component of the Linear Velocity in the world space of the <see cref="Rigidbody2D" />.</param>
        ///<param name="mode">The method used to apply the specified force.</param>
        ///<seealso cref="Rigidbody2D.AddForceX" />
        ///<seealso cref="Rigidbody2D.AddForce" />
        public void AddForceY(float force, [DefaultValue("ForceMode2D.Force")] ForceMode2D mode = ForceMode2D.Force) { AddForce_Internal(new Vector2(0f, force), mode); }

