        ///<param name="direction">Vector representing the direction to cast each <see cref="Collider2D" /> shape.</param>
        ///<param name="contactFilter">Filter results defined by the contact filter.</param>
        ///<param name="results">List to receive results.</param>
        ///<param name="distance">Maximum distance over which to cast the Collider(s).</param>
        ///<returns>Returns the number of results placed in the <c>results</c> list.</returns>
        ///<seealso cref="Rigidbody2D.Cast" />
        ///<seealso cref="ContactFilter2D" />
        public int Cast(Vector2 position, float angle, Vector2 direction, ContactFilter2D contactFilter, List<RaycastHit2D> results, [DefaultValue("Mathf.Infinity")] float distance = Mathf.Infinity)
        {
            const bool checkIgnoreColliders = false;

            return CastFromFiltered_Internal(position, angle, direction, distance, checkIgnoreColliders, contactFilter, results);
        }

        ///<summary>All the <see cref="Collider2D" /> shapes attached to the <see cref="Rigidbody2D" /> are cast into the Scene starting at each Collider position ignoring the Colliders attached to the same <see cref="Rigidbody2D" />.</summary>
        ///<remarks>This function will take all the <see cref="Collider2D" /> shapes attached to the <see cref="Rigidbody2D" /> and cast them into the Scene starting at the Collider position in the specified <c>direction</c> for an optional <c>distance</c> and return the results in the provided <c>results</c> list.
        ///
        ///The <c>contactFilter</c> parameter can filter the returned results by the options in <see cref="ContactFilter2D" />.
        ///
        ///Additionally, this will also detect other Collider(s) overlapping the collider start position.  In this case the cast shape will be starting inside the Collider and may not intersect the Collider surface.  This means that the collision normal cannot be calculated in which case the collision normal returned is set to the inverse of the <c>direction</c> vector being tested.
        ///
        ///**NOTE:** All results are sorted into ascending distance order i.e. the first result is the closest.</remarks>
        ///<param name="direction">Vector representing the direction to cast each <see cref="Collider2D" /> shape.</param>
        ///<param name="contactFilter">Filter results defined by the contact filter.</param>
        ///<param name="distance">Maximum distance over which to cast the Collider(s).</param>
        ///<param name="allocator">The memory allocator to use for the results. This can only be Allocator.Temp, Allocator.TempJob or Allocator.Persistent.</param>
        ///<returns>The NativeArray that contains the results. This must be disposed of unless it contains no results.</returns>
        public NativeArray<RaycastHit2D> Cast(Vector2 direction, ContactFilter2D contactFilter, [DefaultValue("Mathf.Infinity")] float distance = Mathf.Infinity, Allocator allocator = Allocator.Temp)
        {
            const bool checkIgnoreColliders = false;

            return CastFilteredNativeArray_Internal(direction, distance, checkIgnoreColliders, contactFilter, allocator).ToNativeArray<RaycastHit2D>();
        }

        ///<summary>The <see cref="Rigidbody2D" /> is cast into the Scene starting at the specified position and rotation. All the <see cref="Collider2D" /> shapes attached to the <see cref="Rigidbody2D" /> are cast along with it ignoring the Colliders attached to the same <see cref="Rigidbody2D" />.</summary>
        ///<remarks>This function, unlike <see cref="Rigidbody2D.Cast" /> allows you to cast the <see cref="Rigidbody2D" /> and all its attached <see cref="Collider2D" /> through the scene but also allows the starting <c>position</c> and <c>angle</c> of the <see cref="Rigidbody2D" /> to be specified.
        ///
        ///This function also uses the specified <c>contactFilter</c> therefore the specific <see cref="LayerMask" /> of each <see cref="Collider2D" /> attached to this <see cref="Rigidbody2D" /> is not used to detect contacts. If this isn't desired then the <see cref="Rigidbody2D.Cast" /> overload without the <see cref="ContactFilter2D" /> argument should be used.
        ///
        ///**NOTE:** All results are sorted into ascending distance order i.e. the first result is the closest.
        ///
        ///**NOTE**: Additionally, this will also detect other Collider(s) overlapping the start position. In this case the cast shape will be starting inside another Collider and may not intersect the Collider surface. This means that the collision normal cannot be calculated in which case the collision normal returned is set to the inverse of the <c>direction</c> vector being tested.</remarks>
        ///<param name="position">The position to start casting the rigidbody from.</param>
        ///<param name="angle">The rotation of the rigidbody (in degrees).</param>
        ///<param name="direction">Vector representing the direction to cast each <see cref="Collider2D" /> shape.</param>
        ///<param name="contactFilter">Filter results defined by the contact filter.</param>
        ///<param name="distance">Maximum distance over which to cast the Collider(s).</param>
        ///<param name="allocator">The memory allocator to use for the results. This can only be Allocator.Temp, Allocator.TempJob or Allocator.Persistent.</param>
        ///<returns>The NativeArray that contains the results. This must be disposed of unless it contains no results.</returns>
        ///<seealso cref="Rigidbody2D.Cast" />
        ///<seealso cref="ContactFilter2D" />
        public NativeArray<RaycastHit2D> Cast(Vector2 position, float angle, Vector2 direction, ContactFilter2D contactFilter, [DefaultValue("Mathf.Infinity")] float distance = Mathf.Infinity, Allocator allocator = Allocator.Temp)
        {
            const bool checkIgnoreColliders = false;

            return CastFromNativeArrayFiltered_Internal(position, angle, direction, distance, checkIgnoreColliders, contactFilter, allocator).ToNativeArray<RaycastHit2D>();
        }

        ///<summary>Get a list of all Colliders that overlap all Colliders attached to this <see cref="Rigidbody2D" /> filtered by the <c>contactFilter</c>.</summary>
        ///<remarks>The integer return value is the number of Colliders that overlap the <c>collider</c> and which could be stored in the supplied array given its length. The results array will not be resized if it doesn't contain enough elements to report all the results.  The significance of this is that no memory is allocated for the results and so garbage collection performance is improved when the check is performed frequently.</remarks>
        ///<param name="contactFilter">The contact filter used to filter the results differently, such as by layer mask, Z depth.  Note that normal angle is not used for overlap testing.</param>
        ///<param name="results">The array to receive results.  The size of the array determines the maximum number of results that can be returned.</param>
        ///<returns>Returns the number of results placed in the <c>results</c> array.</returns>
        ///<seealso cref="Physics2D.OverlapCollider" />
        ///<seealso cref="Collider2D.Overlap" />
        ///<seealso cref="Rigidbody2D.GetAttachedColliders" />
        public int Overlap(ContactFilter2D contactFilter, [In, Out] Collider2D[] results)
        {
            return OverlapArray_Internal(contactFilter, results);
        }

        ///<summary>Get a list of all Colliders that overlap all Colliders attached to this <see cref="Rigidbody2D" />.</summary>
        ///<remarks>The integer return value is the number of results written into the <c>results</c> list. The results list will be resized if it doesn't contain enough elements to report all the results. This prevents memory from being allocated for results when the <c>results</c> list does not need to be resized, and improves garbage collection performance when the query is performed frequently.</remarks>
        ///<param name="results">The list to receive results.</param>
        ///<returns>Returns the number of results placed in the <c>results</c> list.</returns>
        ///<seealso cref="Physics2D.OverlapCollider" />
        ///<seealso cref="Collider2D.Overlap" />
        ///<seealso cref="Rigidbody2D.GetAttachedColliders" />
        public int Overlap(List<Collider2D> results)
        {
            return OverlapList_Internal(results);
        }

        ///<summary>Get a list of all Colliders that overlap all Colliders attached to this <see cref="Rigidbody2D" /> filtered by the <c>contactFilter</c>.</summary>
        ///<remarks>The integer return value is the number of results written into the <c>results</c> list. The results list will be resized if it doesn't contain enough elements to report all the results. This prevents memory from being allocated for results when the <c>results</c> list does not need to be resized, and improves garbage collection performance when the query is performed frequently.</remarks>
        ///<param name="contactFilter">The contact filter used to filter the results differently, such as by layer mask, Z depth.  Note that normal angle is not used for overlap testing.</param>
        ///<param name="results">The list to receive results.</param>
        ///<returns>Returns the number of results placed in the <c>results</c> list.</returns>
        ///<seealso cref="Physics2D.OverlapCollider" />
        ///<seealso cref="Collider2D.Overlap" />
        ///<seealso cref="Rigidbody2D.GetAttachedColliders" />
        public int Overlap(ContactFilter2D contactFilter, List<Collider2D> results)
        {
            return OverlapFilteredList_Internal(contactFilter, results);
        }

        ///<summary>Get a list of all Colliders that overlap all Colliders attached to this <see cref="Rigidbody2D" />.</summary>
        ///<remarks>The integer return value is the number of results written into the <c>results</c> list. The results list will be resized if it doesn't contain enough elements to report all the results. This prevents memory from being allocated for results when the <c>results</c> list does not need to be resized, and improves garbage collection performance when the query is performed frequently.</remarks>
        ///<param name="position">The position to overlap the Rigidbody at.</param>
        ///<param name="angle">The angle to overlap the Rigidbody at.</param>
        ///<param name="results">The list to receive results.</param>
        ///<returns>Returns the number of results placed in the <c>results</c> list.</returns>
        ///<seealso cref="Physics2D.OverlapCollider" />
        ///<seealso cref="Collider2D.Overlap" />
        ///<seealso cref="Rigidbody2D.GetAttachedColliders" />
        public int Overlap(Vector2 position, float angle, List<Collider2D> results)
        {
            return OverlapFromList_Internal(position, angle, results);
        }

        ///<summary>Get a list of all Colliders that overlap all Colliders attached to this <see cref="Rigidbody2D" />.</summary>
        ///<remarks>The integer return value is the number of results written into the <c>results</c> list. The results list will be resized if it doesn't contain enough elements to report all the results. This prevents memory from being allocated for results when the <c>results</c> list does not need to be resized, and improves garbage collection performance when the query is performed frequently.</remarks>
        ///<param name="position">The position to overlapping the Rigidbody at.</param>
        ///<param name="angle">The angle to overlap the Rigidbody at.</param>
        ///<param name="contactFilter">The contact filter used to filter the results differently, such as by layer mask, Z depth.  Note that normal angle is not used for overlap testing.</param>
        ///<param name="results">The list to receive results.</param>
        ///<returns>Returns the number of results placed in the <c>results</c> list.</returns>
        ///<seealso cref="Physics2D.OverlapCollider" />
        ///<seealso cref="Collider2D.Overlap" />
        ///<seealso cref="Rigidbody2D.GetAttachedColliders" />
        public int Overlap(Vector2 position, float angle, ContactFilter2D contactFilter, List<Collider2D> results)
        {
            return OverlapFromFilteredList_Internal(position, angle, contactFilter, results);
        }

