        public int GetContacts(List<Collider2D> colliders)
        {
            return Physics2D.GetContacts(this, ContactFilter2D.noFilter, colliders);
        }

        // Get filtered contacts for this collider.
        ///<summary>Retrieves all colliders in contact with this Collider, with the results filtered by the <c>contactFilter</c>.</summary>
        ///<remarks>You should pass an array that is large enough to contain all the contacts you want returned. This array would typically be reused so it should be of a size that can return a reasonable quantity of contacts. No allocations occur in this function which means no work is produced for the garbage collector.</remarks>
        ///<param name="contactFilter">The contact filter used to filter the results differently, such as by layer mask, Z depth, or normal angle.</param>
        ///<param name="colliders">An array of <see cref="Collider2D" /> used to receive the results.</param>
        ///<returns>Returns the number of colliders placed in the <c>colliders</c> array.</returns>
        ///<seealso cref="Rigidbody2D.GetContacts" />
        ///<seealso cref="Physics2D.GetContacts" />
        public int GetContacts(ContactFilter2D contactFilter, Collider2D[] colliders)
        {
            return Physics2D.GetContacts(this, contactFilter, colliders);
        }

        ///<summary>Retrieves all colliders in contact with this Collider, with the results filtered by the <c>contactFilter</c>.</summary>
        ///<remarks>The results list will be resized if it doesn't contain enough elements to report all the results. This prevents memory from being allocated for results when the <c>results</c> list does not need to be resized, and improves garbage collection performance when the query is performed frequently.</remarks>
        ///<param name="contactFilter">The contact filter used to filter the results differently, such as by layer mask, Z depth, or normal angle.</param>
        ///<param name="colliders">A list of <see cref="Collider2D" /> used to receive the results.</param>
        ///<returns>Returns the number of contacts placed in the <c>colliders</c> list.</returns>
        ///<seealso cref="Rigidbody2D.GetContacts" />
        ///<seealso cref="Physics2D.GetContacts" />
        public int GetContacts(ContactFilter2D contactFilter, List<Collider2D> colliders)
        {
            return Physics2D.GetContacts(this, contactFilter, colliders);
        }

        ///<summary>Retrieves all contact points for this Collider, with the results filtered by the <c>contactFilter</c>.</summary>
        ///<param name="contactFilter">The contact filter used to filter the results differently, such as by layer mask, Z depth, or normal angle.</param>
        ///<param name="allocator">The memory allocator to use for the results. This can only be Allocator.Temp, Allocator.TempJob or Allocator.Persistent.</param>
        ///<returns>A collection of ContactPoint2D containing the results. The collection does not allocate any managed memory but must be disposed of.</returns>
        public NativeArray<ContactPoint2D> GetContacts(ContactFilter2D contactFilter, Allocator allocator = Allocator.Temp)
        {
            return Physics2D.GetContacts(this, contactFilter, allocator);
        }

        ///<summary>Retrieves all colliders in contact with this Collider, with the results filtered by the <c>contactFilter</c>.</summary>
        ///<param name="contactFilter">The contact filter used to filter the results differently, such as by layer mask, Z depth, or normal angle.</param>
        ///<param name="allocator">The memory allocator to use for the results. This can only be Allocator.Temp, Allocator.TempJob or Allocator.Persistent.</param>
        ///<returns>A collection of Collider2D containing the results. The collection does not allocate any managed memory but must be disposed of.</returns>
        public ColliderArray2D GetContactColliders(ContactFilter2D contactFilter, Allocator allocator = Allocator.Temp)
        {
            return Physics2D.GetContactColliders(this, contactFilter, allocator);
        }
    }

    ///<summary>Represents a <see cref="Collider2D" /> that is configured by assigning <see cref="PhysicsShape2D" /> geometry to it via a <see cref="PhysicsShapeGroup2D" />.</summary>
    ///<remarks>Unlike all other <see cref="Collider2D" /> which are defined indirectly by controlling geometric parameters such as the size of a Box or the radius of a Circle, here the <see cref="CustomCollider2D" /> is defined entirely by adding, removing and modifying <see cref="PhysicsShape2D" />. This results in a fully customized <see cref="Collider2D" /> containing an unlimited number of low-level <see cref="PhysicsShape2D" /> which can represent any type of shape or shapes, or emulate any other existing <see cref="Collider2D" /> such as the <see cref="CircleCollider2D" />, <see cref="BoxCollider2D" />, <see cref="CapsuleCollider2D" />, <see cref="EdgeCollider2D" />, <see cref="CompositeCollider2D" /> or <see cref="T:UnityEngine.Tilemaps.TilemapCollider2D" />.
    ///
    ///Alongside the customized geometry, there is full support for all existing <see cref="Collider2D" /> functionality such as <see cref="Collider2D.isTrigger">triggers</see>, <see cref="Collider2D.sharedMaterial">physics materials</see>, queries  etc.
    ///
    ///When assigning <see cref="PhysicsShape2D" /> to the <see cref="CustomCollider2D" />, you can do so either during Edit mode or Play mode.
    ///
    ///When modifying the <see cref="CustomCollider2D" /> during Edit mode, all assigned <see cref="PhysicsShape2D" /> and associated <see cref="Vector2">vertices</see> will be saved with the Unity <see cref="Scene" />. When the Unity <see cref="Scene" /> is loaded again, the <see cref="CustomCollider2D" /> will maintain its configuration. In this way, it acts like any other <see cref="Collider2D" /> that you make changes to during Edit mode. Using this ability, Edit mode authoring scripts can be used to create custom geometry.
    ///
    ///When modifing the <see cref="CustomCollider2D" /> during Play mode, all assigned <see cref="PhysicsShape2D" /> and associated <see cref="Vector2">vertices</see> will be lost when exiting Play mode. This acts like any other <see cref="Collider2D" />.</remarks>
    [NativeHeader("Modules/Physics2D/Public/CustomCollider2D.h")]
    [NativeClass("CustomCollider2D", PersistentTypeId = 0x3542D1C2)]
    public sealed partial class CustomCollider2D : Collider2D
    {
        // Gets the number of custom shapes this collider will generate.
        ///<summary>The total number of custom <see cref="PhysicsShape2D" /> assigned to the Collider. (RO)</summary>
        ///<remarks>All the shapes represented here contain a total vertex count of <see cref="CustomCollider2D.customVertexCount">customVertexCount</see>.
        ///
        ///**NOTE**: This property should not be confused with <see cref="Collider2D.shapeCount" /> which is a count of active shapes on the <see cref="Collider2D" />. The <see cref="CustomCollider2D" /> has this property too.  If a <see cref="Collider2D" /> is disabled, inactive or in <see cref="Collider2D.errorState">error</see> then the <see cref="Collider2D.shapeCount" /> will be zero whereas the <see cref="CustomCollider2D.customShapeCount">customShapeCount</see> will always be a count of assigned custom <see cref="PhysicsShape2D" />.</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-1f, 0f),
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Add a box to the shape group.
        ///        shapeGroup.AddBox
        ///            (
        ///                center: new Vector2(1f, 0f),
        ///                size: new Vector2(1f, 1f)
        ///            );
        ///
        ///        // Assign our shapes.
        ///        customCollider.SetCustomShapes(shapeGroup);
        ///
        ///        // Validate the custom shape count.
        ///        Assert.AreApproximatelyEqual(shapeGroup.shapeCount, customCollider.customShapeCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        [NativeMethod("CustomShapeCount_Binding")]
        extern public int customShapeCount { get; }

        // Gets the number of custom shape vertices this collider will generate.
        ///<summary>The total number of <see cref="Vector2">vertices</see> used by the Collider. (RO)</summary>
        ///<remarks>All the Collider shapes with a total shape count of <see cref="CustomCollider2D.customShapeCount">customShapeCount</see> use all the vertices represented here.</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-1f, 0f),
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Add a box to the shape group.
        ///        shapeGroup.AddBox
        ///            (
        ///                center: new Vector2(1f, 0f),
        ///                size: new Vector2(1f, 1f)
        ///            );
        ///
        ///        // Assign our shapes.
        ///        customCollider.SetCustomShapes(shapeGroup);
        ///
        ///        // Validate the custom shape vertices.
        ///        Assert.AreApproximatelyEqual(shapeGroup.vertexCount, customCollider.customVertexCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        [NativeMethod("CustomVertexCount_Binding")]
        extern public int customVertexCount { get; }

        ///<summary>Gets all the physics shapes and vertices in the Collider and places them in the specified <see cref="PhysicsShapeGroup2D" />.</summary>
        ///<param name="physicsShapeGroup">The physics shape group that will receive all the <see cref="PhysicsShape2D">physics shapes</see> and <see cref="Vector2">vertices</see> from the Collider.</param>
        ///<returns>Returns the total number of <see cref="PhysicsShape2D">physics shapes</see> placed in the specified <c>physicsShapeGroup</c>.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Create an input shape group.
        ///        var inputShapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add 5 Circles to the shape group.
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.5f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.6f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.7f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.8f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.9f);
        ///
        ///        // Assign our shapes.
        ///        customCollider.SetCustomShapes(inputShapeGroup);
        ///
        ///        // Validate the contents of the custom collider.
        ///        Assert.AreEqual(5, customCollider.customShapeCount);
        ///
        ///        // Create an output shape group.
        ///        var outputShapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Get all the custom shapes.
        ///        var shapeCount = customCollider.GetCustomShapes(outputShapeGroup);
        ///
        ///        // Validate the results.
        ///        Assert.AreEqual(5, shapeCount);
        ///        Assert.AreEqual(5, outputShapeGroup.shapeCount);
        ///        Assert.AreApproximatelyEqual(0.5f, outputShapeGroup.GetShape(shapeIndex: 0).radius);
        ///        Assert.AreApproximatelyEqual(0.6f, outputShapeGroup.GetShape(shapeIndex: 1).radius);
        ///        Assert.AreApproximatelyEqual(0.7f, outputShapeGroup.GetShape(shapeIndex: 2).radius);
        ///        Assert.AreApproximatelyEqual(0.8f, outputShapeGroup.GetShape(shapeIndex: 3).radius);
        ///        Assert.AreApproximatelyEqual(0.9f, outputShapeGroup.GetShape(shapeIndex: 4).radius);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int GetCustomShapes(PhysicsShapeGroup2D physicsShapeGroup)
        {
            var colliderShapeCount = customShapeCount;

            // Get the custom shapes if there are any.
            if (colliderShapeCount > 0)
                return GetCustomShapes_Internal(physicsShapeGroup.m_GroupState.m_Shapes, physicsShapeGroup.m_GroupState.m_Vertices, out physicsShapeGroup.m_GroupState.m_LocalToWorld, 0, colliderShapeCount);

            // No shapes so clear the group and finish.
            physicsShapeGroup.Clear();
            return 0;
        }

        ///<summary>Gets a specified number of physics shapes defined byshapeCount starting at <c>shapeIndex</c> along with all associated vertices those shapes use and places them in the specified <see cref="PhysicsShapeGroup2D" />.</summary>
        ///<param name="physicsShapeGroup">The physics shape group that will receive the <see cref="PhysicsShape2D">physics shapes</see> and <see cref="Vector2">vertices</see> from the Collider.</param>
        ///<param name="shapeIndex">The shape index within the Collider to start retrieving shapes from.</param>
        ///<param name="shapeCount">The total number of shapes starting at the <c>shapeIndex</c> to retrieve.</param>
        ///<returns>The total number of <see cref="PhysicsShape2D">physics shapes</see> placed in the specified <c>physicsShapeGroup</c>.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Create an input shape group.
        ///        var inputShapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add 5 Circles to the shape group.
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.5f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.6f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.7f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.8f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.9f);
        ///
        ///        // Assign our shapes.
        ///        customCollider.SetCustomShapes(inputShapeGroup);
        ///
        ///        // Validate the contents of the custom collider.
        ///        Assert.AreEqual(5, customCollider.customShapeCount);
        ///
        ///        // Create an output shape group.
        ///        var outputShapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Get the last 3 custom shapes.
        ///        var shapeCount = customCollider.GetCustomShapes(outputShapeGroup, shapeIndex: 2, shapeCount: 3);
        ///
        ///        // Validate the results.
        ///        Assert.AreEqual(3, shapeCount);
        ///        Assert.AreEqual(3, outputShapeGroup.shapeCount);
        ///        Assert.AreApproximatelyEqual(0.7f, outputShapeGroup.GetShape(shapeIndex: 0).radius);
        ///        Assert.AreApproximatelyEqual(0.8f, outputShapeGroup.GetShape(shapeIndex: 1).radius);
        ///        Assert.AreApproximatelyEqual(0.9f, outputShapeGroup.GetShape(shapeIndex: 2).radius);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public int GetCustomShapes(PhysicsShapeGroup2D physicsShapeGroup, int shapeIndex, [DefaultValue("1")] int shapeCount = 1)
        {
            var colliderShapeCount = customShapeCount;

            // Validate range.
            if (shapeIndex < 0 ||
                shapeIndex >= colliderShapeCount ||
                shapeCount < 1 ||
                (shapeIndex + shapeCount) > colliderShapeCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot get shape range from {0} to {1} as CustomCollider2D only has {2} shape(s).", shapeIndex, shapeIndex + shapeCount - 1, colliderShapeCount));

            return GetCustomShapes_Internal(physicsShapeGroup.m_GroupState.m_Shapes, physicsShapeGroup.m_GroupState.m_Vertices, out physicsShapeGroup.m_GroupState.m_LocalToWorld, shapeIndex, shapeCount);
        }

        [NativeMethod("GetCustomShapes_Binding")]
        extern private int GetCustomShapes_Internal([Out,NotNull] List<PhysicsShape2D> shapes, [Out,NotNull] List<Vector2> vertices, out Matrix4x4 localToWorld, int shapeIndex, int shapeCount);

        ///<summary>Gets all the physics shapes and vertices in the Collider and places them in the specified arrays.</summary>
        ///<param name="shapes">The array that will be populated with a copy of all the shapes in the <see cref="PhysicsShapeGroup2D" />.</param>
        ///<param name="vertices">The array that will be populated with a copy of all the vertices in the <see cref="PhysicsShapeGroup2D" />.</param>
        ///<returns>Returns the total number of <see cref="PhysicsShape2D">physics shapes</see> placed in the specified arrays.</returns>
        ///<example>
        ///  <code><![CDATA[
        ///using Unity.Collections;
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Create an input shape group.
        ///        var inputShapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add 5 Circles to the shape group.
        ///        inputShapeGroup.AddCircle(center: new Vector2(3f, 8f), radius: 0.5f);
        ///        inputShapeGroup.AddCircle(center: new Vector2(6f, 3f), radius: 0.6f);
        ///        inputShapeGroup.AddCircle(center: new Vector2(2f, 5f), radius: 0.7f);
        ///        inputShapeGroup.AddCircle(center: new Vector2(9f, 2f), radius: 0.8f);
        ///        inputShapeGroup.AddCircle(center: new Vector2(1f, 7f), radius: 0.9f);
        ///
        ///        // Assign our shapes.
        ///        customCollider.SetCustomShapes(inputShapeGroup);
        ///
        ///        // Validate the contents of the custom collider.
        ///        Assert.AreEqual(5, customCollider.customShapeCount);
        ///
        ///        // Get all the custom shapes.
        ///        var shapes = new NativeArray<PhysicsShape2D>(customCollider.customShapeCount, Allocator.Temp);
        ///        var vertices = new NativeArray<Vector2>(customCollider.customVertexCount, Allocator.Temp);
        ///        var shapeCount = customCollider.GetCustomShapes(shapes, vertices);
        ///
        ///        // Validate the shapes.
        ///        Assert.AreEqual(5, shapeCount);
        ///        Assert.AreApproximatelyEqual(0.5f, shapes[0].radius);
        ///        Assert.AreApproximatelyEqual(0.6f, shapes[1].radius);
        ///        Assert.AreApproximatelyEqual(0.7f, shapes[2].radius);
        ///        Assert.AreApproximatelyEqual(0.8f, shapes[3].radius);
        ///        Assert.AreApproximatelyEqual(0.9f, shapes[4].radius);
        ///
        ///        // Validate the vertices.
        ///        Assert.AreEqual(new Vector2(3f, 8f), vertices[0]);
        ///        Assert.AreEqual(new Vector2(6f, 3f), vertices[1]);
        ///        Assert.AreEqual(new Vector2(2f, 5f), vertices[2]);
        ///        Assert.AreEqual(new Vector2(9f, 2f), vertices[3]);
        ///        Assert.AreEqual(new Vector2(1f, 7f), vertices[4]);
        ///
        ///        // Dispose of the native arrays.
        ///        vertices.Dispose();
        ///        shapes.Dispose();
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public unsafe int GetCustomShapes(NativeArray<PhysicsShape2D> shapes, NativeArray<Vector2> vertices)
        {
            if (!shapes.IsCreated || shapes.Length != customShapeCount)
                throw new ArgumentException($"Cannot get custom shapes as the native shapes array length must be identical to the current custom shape count of {customShapeCount}.", "shapes");

            if (!vertices.IsCreated || vertices.Length != customVertexCount)
                throw new ArgumentException($"Cannot get custom shapes as the native vertices array length must be identical to the current custom vertex count of {customVertexCount}.", "vertices");

            return GetCustomShapesNative_Internal(
                (IntPtr)shapes.GetUnsafeReadOnlyPtr(), shapes.Length,
                (IntPtr)vertices.GetUnsafeReadOnlyPtr(), vertices.Length);
        }

        [NativeMethod("GetCustomShapesAllNative_Binding")]
        extern private int GetCustomShapesNative_Internal(IntPtr shapesPtr, int shapeCount, IntPtr verticesPtr, int vertexCount);

        // Set all custom shapes.
        ///<summary>Sets all the shapes and vertices in the Collider to those represented by the specified <see cref="PhysicsShapeGroup2D" />.</summary>
        ///<remarks>All existing shapes and vertices are replaced by the shapes and vertices contained in the specified <see cref="PhysicsShapeGroup2D" />.
        ///
        ///Where possible, the Collider will reduce the amount of work required to assign the specifed shapes and vertices. The Collider checks each <see cref="PhysicsShape2D" /> being assigned at each shape index and if the Collider already contains the same physics shape then no work is done. If the physics shape has the same <see cref="PhysicsShape2D.shapeType">shape type</see> and <see cref="PhysicsShape2D.vertexCount">vertex count</see> then the existing physics engine shape will only have its <see cref="PhysicsShape2D.radius">radius</see> and <see cref="PhysicsShape2D.vertexStartIndex">vertices</see> updated. If the physics shape has a different <see cref="PhysicsShape2D.shapeType">shape type</see> or <see cref="PhysicsShape2D.vertexCount">vertex count</see> then the physics engine shape will be recreated.
        ///
        ///Any existing contacts for this Collider will be recalculated during the next simulation step.</remarks>
        ///<param name="physicsShapeGroup">The <see cref="PhysicsShapeGroup2D" /> to use as the source of shapes and vertices.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add a Circle to the shape group.
        ///        shapeGroup.AddCircle
        ///            (
        ///                center: new Vector2(-1f, 0f),
        ///                radius: 0.5f
        ///            );
        ///
        ///        // Add a box to the shape group.
        ///        shapeGroup.AddBox
        ///            (
        ///                center: new Vector2(1f, 0f),
        ///                size: new Vector2(1f, 1f)
        ///            );
        ///
        ///        // Assign the shapes and vertices.
        ///        customCollider.SetCustomShapes(shapeGroup);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void SetCustomShapes(PhysicsShapeGroup2D physicsShapeGroup)
        {
            // Set the custom shapes if we defined any.
            if (physicsShapeGroup.shapeCount > 0)
            {
                ref var groupState = ref physicsShapeGroup.m_GroupState;
                SetCustomShapesAll_Internal(NoAllocHelpers.CreateReadOnlySpan(groupState.m_Shapes), NoAllocHelpers.CreateReadOnlySpan(groupState.m_Vertices));
                return;
            }

            // No custom shapes so clear them.
            ClearCustomShapes();
        }

        [NativeMethod("SetCustomShapesAll_Binding")]
        extern private void SetCustomShapesAll_Internal(ReadOnlySpan<PhysicsShape2D> shapes, ReadOnlySpan<Vector2> vertices);

        // Set all custom shapes using native arrays.
        ///<summary>Sets all the shapes and vertices in the Collider to those represented by the specified arrays.</summary>
        ///<remarks>All existing shapes and vertices are replaced by the shapes and vertices contained in the specified arrays.
        ///
        ///Where possible, the Collider will reduce the amount of work required to assign the specified shapes and vertices. The Collider checks each <see cref="PhysicsShape2D" /> being assigned at each shape index and if the Collider already contains the same physics shape then no work is done. If the physics shape has the same <see cref="PhysicsShape2D.shapeType">shape type</see> and <see cref="PhysicsShape2D.vertexCount">vertex count</see> then the existing physics engine shape will only have its <see cref="PhysicsShape2D.radius">radius</see> and <see cref="PhysicsShape2D.vertexStartIndex">vertices</see> updated. If the physics shape has a different <see cref="PhysicsShape2D.shapeType">shape type</see> or <see cref="PhysicsShape2D.vertexCount">vertex count</see> then the physics engine shape will be recreated.
        ///
        ///Any existing contacts for this Collider will be recalculated during the next simulation step.</remarks>
        ///<param name="shapes">The array containing all the shapes used to assign to the Collider.</param>
        ///<param name="vertices">The array containing all the vertices used to assign to the Collider.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using Unity.Collections;
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a native shapes array and populate it with a Circle and Capsule.
        ///        var shapes = new NativeArray<PhysicsShape2D>(2, Allocator.Temp)
        ///        {
        ///            [0] = new PhysicsShape2D() { shapeType = PhysicsShapeType2D.Circle, radius = 1f, vertexStartIndex = 0, vertexCount = 1 },
        ///            [1] = new PhysicsShape2D() { shapeType = PhysicsShapeType2D.Capsule, radius = 0.5f, vertexStartIndex = 1, vertexCount = 2 }
        ///        };
        ///
        ///        // Create a native vertices array and populate it with the vertices for the shapes.
        ///        var vertices = new NativeArray<Vector2>(3, Allocator.Temp)
        ///        {
        ///            [0] = new Vector2(2f, 3f),
        ///            [1] = Vector2.down,
        ///            [2] = Vector2.up
        ///        };
        ///
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Set custom collider to the shapes and vertices.
        ///        customCollider.SetCustomShapes(shapes, vertices);
        ///
        ///        // Dispose of the native arrays.
        ///        vertices.Dispose();
        ///        shapes.Dispose();
        ///
        ///        // Validate the collider.
        ///        Assert.AreEqual(2, customCollider.customShapeCount);
        ///        Assert.AreEqual(3, customCollider.customVertexCount);
        ///
        ///        // Get all the custom shapes.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///        customCollider.GetCustomShapes(shapeGroup);
        ///
        ///        // Validate the first shape and vertex.
        ///        var shape0 = shapeGroup.GetShape(0);
        ///        Assert.AreEqual(PhysicsShapeType2D.Circle, shape0.shapeType);
        ///        Assert.AreApproximatelyEqual(1f, shape0.radius);
        ///        Assert.AreEqual(0, shape0.vertexStartIndex);
        ///        Assert.AreEqual(1, shape0.vertexCount);
        ///        Assert.AreEqual(new Vector2(2f, 3f), shapeGroup.GetShapeVertex(shapeIndex: 0, vertexIndex: 0));
        ///
        ///        // Validate the second shape and vertices.
        ///        var shape1 = shapeGroup.GetShape(1);
        ///        Assert.AreEqual(PhysicsShapeType2D.Capsule, shape1.shapeType);
        ///        Assert.AreApproximatelyEqual(0.5f, shape1.radius);
        ///        Assert.AreEqual(1, shape1.vertexStartIndex);
        ///        Assert.AreEqual(2, shape1.vertexCount);
        ///        Assert.AreEqual(Vector2.down, shapeGroup.GetShapeVertex(shapeIndex: 1, vertexIndex: 0));
        ///        Assert.AreEqual(Vector2.up, shapeGroup.GetShapeVertex(shapeIndex: 1, vertexIndex: 1));
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public unsafe void SetCustomShapes(NativeArray<PhysicsShape2D> shapes, NativeArray<Vector2> vertices)
        {
            if (!shapes.IsCreated || shapes.Length == 0)
                throw new ArgumentException("Cannot set custom shapes as the native shapes array is empty.", "shapes");

            if (!vertices.IsCreated || vertices.Length == 0)
                throw new ArgumentException("Cannot set custom shapes as the native vertices array is empty.", "vertices");

            SetCustomShapesNative_Internal(
                (IntPtr)shapes.GetUnsafeReadOnlyPtr(), shapes.Length,
                (IntPtr)vertices.GetUnsafeReadOnlyPtr(), vertices.Length);
        }

        [NativeMethod("SetCustomShapesAllNative_Binding", ThrowsException = true)]
        extern private void SetCustomShapesNative_Internal(IntPtr shapesPtr, int shapeCount, IntPtr verticesPtr, int vertexCount);

        // Set a single custom shape.
        ///<summary>Sets a single shape and all associated shape vertices from the specified <c>physicsShapeGroup</c> into the Collider.</summary>
        ///<remarks>Setting a single shape allows replacing individual shapes within the Collider. Where possible, the Collider will reduce the amount of work required to assign the shape. See <see cref="CustomCollider2D.GetCustomShapes">GetCustomShapes</see> for more information on this behaviour.
        ///
        ///Any existing contacts for this Collider will be recalculated during the next simulation step.</remarks>
        ///<param name="physicsShapeGroup">The <see cref="PhysicsShapeGroup2D" /> to use as the source of shapes and vertices.</param>
        ///<param name="srcShapeIndex">The source shape index within the <c>physicsShapeGroup</c> used to assign to the Collider.</param>
        ///<param name="dstShapeIndex">The destination shape index within the Collider to copy the source shape to.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Create an input shape group.
        ///        var inputShapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add 5 Circles to the shape group.
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.5f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.6f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.7f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.8f);
        ///        inputShapeGroup.AddCircle(center: Vector2.zero,  radius: 0.9f);
        ///
        ///        // Assign our shapes.
        ///        customCollider.SetCustomShapes(inputShapeGroup);
        ///
        ///        // Validate the contents of the custom collider.
        ///        Assert.AreEqual(5, customCollider.customShapeCount);
        ///
        ///        // Transfer the last shape in the shape group to the first in the custom collider.
        ///        customCollider.SetCustomShape(inputShapeGroup, srcShapeIndex: 4, dstShapeIndex: 0);
        ///
        ///        // Create an output shape group.
        ///        var outputShapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Get all the custom shapes.
        ///        var shapeCount = customCollider.GetCustomShapes(outputShapeGroup);
        ///
        ///        // Validate the results.
        ///        Assert.AreEqual(5, shapeCount);
        ///        Assert.AreEqual(5, customCollider.customShapeCount);
        ///        Assert.AreApproximatelyEqual(0.9f, outputShapeGroup.GetShape(shapeIndex: 0).radius);
        ///        Assert.AreApproximatelyEqual(0.6f, outputShapeGroup.GetShape(shapeIndex: 1).radius);
        ///        Assert.AreApproximatelyEqual(0.7f, outputShapeGroup.GetShape(shapeIndex: 2).radius);
        ///        Assert.AreApproximatelyEqual(0.8f, outputShapeGroup.GetShape(shapeIndex: 3).radius);
        ///        Assert.AreApproximatelyEqual(0.9f, outputShapeGroup.GetShape(shapeIndex: 4).radius);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void SetCustomShape(PhysicsShapeGroup2D physicsShapeGroup, int srcShapeIndex, int dstShapeIndex)
        {
            if (srcShapeIndex < 0 || srcShapeIndex >= physicsShapeGroup.shapeCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot set custom shape at {0} as the shape group only has {1} shape(s).", srcShapeIndex, physicsShapeGroup.shapeCount));

            var physicsShape2D = physicsShapeGroup.GetShape(srcShapeIndex);
            if (physicsShape2D.vertexStartIndex < 0 ||
                physicsShape2D.vertexStartIndex >= physicsShapeGroup.vertexCount ||
                physicsShape2D.vertexCount < 1 ||
                (physicsShape2D.vertexStartIndex + physicsShape2D.vertexCount) > physicsShapeGroup.vertexCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot set custom shape at {0} as its shape indices are out of the available vertices ranges.", srcShapeIndex));

            if (dstShapeIndex < 0 || dstShapeIndex >= customShapeCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot set custom shape at destination {0} as CustomCollider2D only has {1} custom shape(s). The destination index must be within the existing shape range.", dstShapeIndex, customShapeCount));

            ref var groupState = ref physicsShapeGroup.m_GroupState;
            SetCustomShape_Internal(NoAllocHelpers.CreateReadOnlySpan(groupState.m_Shapes), NoAllocHelpers.CreateReadOnlySpan(groupState.m_Vertices), srcShapeIndex, dstShapeIndex);
        }

        [NativeMethod("SetCustomShape_Binding")]
        extern private void SetCustomShape_Internal(ReadOnlySpan<PhysicsShape2D> shapes, ReadOnlySpan<Vector2> vertices, int srcShapeIndex, int dstShapeIndex);

        // Set a single custom shape using native arrays.
        ///<summary>Sets a single shape and all associated shape vertices from the specified shape and vertices arrays into the Collider.</summary>
        ///<remarks>Setting a single shape allows replacing individual shapes within the Collider. Where possible, the Collider will reduce the amount of work required to assign the shape. See <see cref="CustomCollider2D.GetCustomShapes">GetCustomShapes</see> for more information on this behaviour.
        ///
        ///Any existing contacts for this Collider will be recalculated during the next simulation step.</remarks>
        ///<param name="shapes">The array to use as the source of shapes.</param>
        ///<param name="vertices">The array to use as the source of vertices.</param>
        ///<param name="srcShapeIndex">The source shape index within the <c>shapes</c> array used to assign to the Collider.</param>
        ///<param name="dstShapeIndex">The destination shape index within the Collider to copy the source shape to.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using Unity.Collections;
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Create a native shapes array and populate it with a Circle and Capsule.
        ///        var shapes = new NativeArray<PhysicsShape2D>(2, Allocator.Temp)
        ///        {
        ///            [0] = new PhysicsShape2D() { shapeType = PhysicsShapeType2D.Circle, radius = 0.5f, vertexStartIndex = 0, vertexCount = 1 },
        ///            [1] = new PhysicsShape2D() { shapeType = PhysicsShapeType2D.Circle, radius = 0.6f, vertexStartIndex = 1, vertexCount = 1 },
        ///            [2] = new PhysicsShape2D() { shapeType = PhysicsShapeType2D.Circle, radius = 0.7f, vertexStartIndex = 2, vertexCount = 1 },
        ///            [3] = new PhysicsShape2D() { shapeType = PhysicsShapeType2D.Circle, radius = 0.8f, vertexStartIndex = 3, vertexCount = 1 },
        ///            [4] = new PhysicsShape2D() { shapeType = PhysicsShapeType2D.Circle, radius = 0.9f, vertexStartIndex = 4, vertexCount = 1 },
        ///        };
        ///
        ///        // Create a native vertices array and populate it with the vertices for the shapes.
        ///        var vertices = new NativeArray<Vector2>(3, Allocator.Temp)
        ///        {
        ///            [0] = Vector2.zero,
        ///            [1] = Vector2.zero,
        ///            [2] = Vector2.zero,
        ///            [3] = Vector2.zero,
        ///            [4] = Vector2.zero,
        ///        };
        ///
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Assign all our test shapes.
        ///        customCollider.SetCustomShapes(shapes, vertices);
        ///
        ///        // Assign the last shape to the first shape.
        ///        customCollider.SetCustomShape(shapes, vertices, srcShapeIndex: 4, dstShapeIndex: 0);
        ///
        ///        // Get all the custom shapes.
        ///        var outputShapeGroup = new PhysicsShapeGroup2D();
        ///        var shapeCount = customCollider.GetCustomShapes(outputShapeGroup);
        ///
        ///        // Validate the results.
        ///        Assert.AreEqual(5, shapeCount);
        ///        Assert.AreEqual(5, customCollider.customShapeCount);
        ///        Assert.AreApproximatelyEqual(0.9f, outputShapeGroup.GetShape(shapeIndex: 0).radius);
        ///        Assert.AreApproximatelyEqual(0.6f, outputShapeGroup.GetShape(shapeIndex: 1).radius);
        ///        Assert.AreApproximatelyEqual(0.7f, outputShapeGroup.GetShape(shapeIndex: 2).radius);
        ///        Assert.AreApproximatelyEqual(0.8f, outputShapeGroup.GetShape(shapeIndex: 3).radius);
        ///        Assert.AreApproximatelyEqual(0.9f, outputShapeGroup.GetShape(shapeIndex: 4).radius);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public unsafe void SetCustomShape(NativeArray<PhysicsShape2D> shapes, NativeArray<Vector2> vertices, int srcShapeIndex, int dstShapeIndex)
        {
            if (!shapes.IsCreated || shapes.Length == 0)
                throw new ArgumentException("Cannot set custom shapes as the native shapes array is empty.", "shapes");

            if (!vertices.IsCreated || vertices.Length == 0)
                throw new ArgumentException("Cannot set custom shapes as the native vertices array is empty.", "vertices");

            if (srcShapeIndex < 0 || srcShapeIndex >= shapes.Length)
                throw new ArgumentOutOfRangeException(String.Format("Cannot set custom shape at {0} as the shape native array only has {1} shape(s).", srcShapeIndex, shapes.Length));

            var physicsShape2D = shapes[srcShapeIndex];
            if (physicsShape2D.vertexStartIndex < 0 ||
                physicsShape2D.vertexStartIndex >= vertices.Length ||
                physicsShape2D.vertexCount < 1 ||
                (physicsShape2D.vertexStartIndex + physicsShape2D.vertexCount) > vertices.Length)
                throw new ArgumentOutOfRangeException(String.Format("Cannot set custom shape at {0} as its shape indices are out of the available vertices ranges.", srcShapeIndex));

            if (dstShapeIndex < 0 || dstShapeIndex >= customShapeCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot set custom shape at destination {0} as CustomCollider2D only has {1} custom shape(s). The destination index must be within the existing shape range.", dstShapeIndex, customShapeCount));

            SetCustomShapeNative_Internal(
                (IntPtr)shapes.GetUnsafeReadOnlyPtr(), shapes.Length,
                (IntPtr)vertices.GetUnsafeReadOnlyPtr(), vertices.Length,
                srcShapeIndex, dstShapeIndex);
        }

        [NativeMethod("SetCustomShapeNative_Binding", ThrowsException = true)]
        extern private void SetCustomShapeNative_Internal(IntPtr shapesPtr, int shapeCount, IntPtr verticesPtr, int vertexCount, int srcShapeIndex, int dstShapeIndex);

        // Clear shapes in the specified range.
        ///<summary>Deletes a specific number of shapes defined by <c>shapeCount</c> starting at <c>shapeIndex</c> along with all associated vertices those shapes use.</summary>
        ///<remarks>Any existing contacts for this Collider will be recalculated during the next simulation step.</remarks>
        ///<param name="shapeIndex">The index of the shape stored in the Collider.</param>
        ///<param name="shapeCount">The number of shapes to delete starting at the specified index.</param>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using UnityEngine.Assertions;
        ///
        ///public class Example : MonoBehaviour
        ///{
        ///    void Start()
        ///    {
        ///        // Fetch the custom collider.
        ///        var customCollider = GetComponent<CustomCollider2D>();
        ///
        ///        // Create a shape group.
        ///        var shapeGroup = new PhysicsShapeGroup2D();
        ///
        ///        // Add 5 Circles to the shape group.
        ///        shapeGroup.AddCircle(center: new Vector2(3f, 0f),  radius: 0.5f);
        ///        shapeGroup.AddCircle(center: new Vector2(4f, 0f),  radius: 0.5f);
        ///        shapeGroup.AddCircle(center: new Vector2(5f, 0f),  radius: 0.5f);
        ///        shapeGroup.AddCircle(center: new Vector2(6f, 0f),  radius: 0.5f);
        ///        shapeGroup.AddCircle(center: new Vector2(7f, 0f),  radius: 0.5f);
        ///
        ///        // Assign our shapes.
        ///        customCollider.SetCustomShapes(shapeGroup);
        ///
        ///        // Validate the contents of the custom collider.
        ///        Assert.AreEqual(5, customCollider.customShapeCount);
        ///
        ///        // Clear the first 2 shapes.
        ///        customCollider.ClearCustomShapes(shapeIndex: 0, shapeCount: 2);
        ///
        ///        // Validate the contents of the custom collider.
        ///        Assert.AreEqual(3, customCollider.customShapeCount);
        ///
        ///        // Clear the remaining 3 shapes.
        ///        customCollider.ClearCustomShapes(shapeIndex: 0, shapeCount: 3);
        ///
        ///        // Validate the contents of the custom collider.
        ///        Assert.AreEqual(0, customCollider.customShapeCount);
        ///    }
        ///}
        ///]]></code>
        ///</example>
        public void ClearCustomShapes(int shapeIndex, int shapeCount)
        {
            var colliderShapeCount = customShapeCount;

            if (shapeIndex < 0 || shapeIndex >= colliderShapeCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot clear custom shape(s) at index {0} as the CustomCollider2D only has {1} shape(s).", shapeIndex, colliderShapeCount));

            if ((shapeIndex + shapeCount) < 0 || (shapeIndex + shapeCount) > customShapeCount)
                throw new ArgumentOutOfRangeException(String.Format("Cannot clear custom shape(s) in the range (index {0}, count {1}) as this range is outside range of the existing {2} shape(s).", shapeIndex, shapeCount, customShapeCount));

            ClearCustomShapes_Internal(shapeIndex, shapeCount);
        }

