        {
            [NativeMethod("GetPoints_Binding")]
            get;
            [NativeMethod("SetPoints_Binding")]
            set;
        }

        // Get the number of paths.
        ///<summary>The number of paths in the polygon.</summary>
        ///<remarks>A path is cyclic sequence of line segments between points that define the outline of the polygon. Because the polygon can have holes and discontinuous parts, its shape is not necessarily defined by a single path.</remarks>
        ///<seealso cref="GetPath" />
        ///<seealso cref="SetPath" />
        extern public int pathCount { get; set; }

        // Get the specified path of points.
        ///<summary>Gets a path from the Collider by its index.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of the Collider. Because the Collider can have holes and discontinuous parts, its shape is not necessarily defined by a single path.
        ///
        ///Returns an ordered array of the points in the path.</remarks>
        ///<param name="index">The index of the path to retrieve.</param>
        ///<returns>An ordered array of the vertices (points) in the selected path.</returns>
        ///<seealso cref="pathCount" />
        ///<seealso cref="SetPath" />
        public Vector2[] GetPath(int index)
        {
            if (index >= pathCount)
                throw new ArgumentOutOfRangeException(String.Format("Path {0} does not exist.", index));

            if (index < 0)
                throw new ArgumentOutOfRangeException(String.Format("Path {0} does not exist; negative path index is invalid.", index));

            return GetPath_Internal(index);
        }

        ///<summary>Gets a path from the Collider by its index.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of the Collider. Because the Collider can have holes and discontinuous parts, its shape is not necessarily defined by a single path.
        ///
        ///Returns an ordered list of the points in the path.
        ///
        ///The integer return value is the number of results written into the <c>points</c> list. The points list will be resized if it doesn't contain enough elements to report all the points.This prevents memory from being allocated for results when the <c>points</c> list does not need to be resized, and improves garbage collection performance when the query is performed frequently.</remarks>
        ///<param name="index">The index of the path to retrieve.</param>
        ///<param name="points">An ordered list of the vertices (points) in the selected path.</param>
        ///<returns>Returns the number of results placed in the <c>points</c> list.</returns>
        ///<seealso cref="pathCount" />
        ///<seealso cref="SetPath" />
        public int GetPath(int index, List<Vector2> points)
        {
            if (index < 0 || index >= pathCount)
                throw new ArgumentOutOfRangeException("index", String.Format("Path index {0} must be in the range of 0 to {1}.", index, pathCount - 1));

            if (points == null)
                throw new ArgumentNullException("points");

            return GetPathList_Internal(index, points);
        }

        // Set the specified path of points.
        ///<summary>Define a path by its constituent points.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of the polygon. Because the polygon can have holes and discontinuous parts, its shape is not necessarily defined by a single path. For example, the polygon might actually be 3 separate paths.  In this case <see cref="SetPath" /> will be called 3 times, with an <c>index</c> of 0, 1 and 2. So <c>index</c> specifies which of these three collections of points are used.</remarks>
        ///<param name="index">Index of the path to set.</param>
        ///<param name="points">An ordered array of the vertices (points) that define the path.</param>
        ///<seealso cref="pathCount" />
        ///<seealso cref="GetPath" />
        public void SetPath(int index, Vector2[] points)
        {
            if (index < 0)
                throw new ArgumentOutOfRangeException(String.Format("Negative path index {0} is invalid.", index));

            SetPath_Internal(index, points);
        }

        ///<summary>Define a path by its constituent points.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of the polygon. Because the polygon can have holes and discontinuous parts, its shape is not necessarily defined by a single path. For example, the polygon might actually be 3 separate paths.  In this case <see cref="SetPath" /> will be called 3 times, with an <c>index</c> of 0, 1 and 2. So <c>index</c> specifies which of these three collections of points are used.</remarks>
        ///<param name="index">Index of the path to set.</param>
        ///<param name="points">An ordered list of the vertices (points) that define the path.</param>
        ///<seealso cref="pathCount" />
        ///<seealso cref="GetPath" />
        public void SetPath(int index, List<Vector2> points)
        {
            if (index < 0)
                throw new ArgumentOutOfRangeException(String.Format("Negative path index {0} is invalid.", index));

            SetPathList_Internal(index, points);
        }

        ///<summary>Gets a path from the Collider by its index.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of the Collider. Because the Collider can have holes and discontinuous parts, its shape is not necessarily defined by a single path.
        ///
        ///Returns an ordered list of the points in the path.</remarks>
        ///<param name="index">The index of the path to retrieve.</param>
        ///<param name="allocator">The memory allocator to use for the results. This can only be Allocator.Temp, Allocator.TempJob or Allocator.Persistent.</param>
        ///<returns>The NativeArray that contains an ordered list of the vertices (points) in the selected path. This must be disposed of unless it contains no results.</returns>
        ///<seealso cref="pathCount" />
        ///<seealso cref="SetPath" />
        public NativeArray<Vector2> GetPath(int index = 0, Allocator allocator = Allocator.Temp)
        {
            if (index < 0 || index >= pathCount)
                throw new ArgumentOutOfRangeException("index", String.Format("Path index {0} must be in the range of 0 to {1}.", index, pathCount - 1));

            return GetPathPhysicsBuffer_Internal(index, allocator).ToNativeArray<Vector2>();
        }

        ///<summary>Define a path by its constituent points.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of the polygon. Because the polygon can have holes and discontinuous parts, its shape is not necessarily defined by a single path. For example, the polygon might actually be 3 separate paths.  In this case <see cref="SetPath" /> will be called 3 times, with an <c>index</c> of 0, 1 and 2. So <c>index</c> specifies which of these three collections of points are used.</remarks>
        ///<param name="index">Index of the path to set.</param>
        ///<param name="points">An ordered span of the vertices (points) that define the path.</param>
        ///<seealso cref="pathCount" />
        ///<seealso cref="GetPath" />
        public void SetPath(int index, ReadOnlySpan<Vector2> points)
        {
            if (index < 0)
                throw new ArgumentOutOfRangeException(String.Format("Negative path index {0} is invalid.", index));

            SetPathSpan_Internal(index, points);
        }

        [NativeMethod("GetPath_Binding")] extern private Vector2[] GetPath_Internal(int index);
        [NativeMethod("GetPathList_Binding")] extern private int GetPathList_Internal(int index, [NotNull] List<Vector2> points);
        [NativeMethod("SetPath_Binding")] extern private void SetPath_Internal(int index, [NotNull] Vector2[] points);
        [NativeMethod("SetPathList_Binding")] extern private void SetPathList_Internal(int index, [NotNull] List<Vector2> points);

        [NativeMethod("GetPathPhysicsBuffer_Binding")] extern private PhysicsBuffer2D GetPathPhysicsBuffer_Internal(int index, Allocator allocator);
        [NativeMethod("SetPathSpan_Binding")] extern private void SetPathSpan_Internal(int index, ReadOnlySpan<Vector2> points);

        // Create a primitive n-sided polygon.
        [ExcludeFromDocs]
        public void CreatePrimitive(int sides)
        {
            CreatePrimitive(sides, Vector2.one, Vector2.zero);
        }

        [ExcludeFromDocs]
        public void CreatePrimitive(int sides, Vector2 scale)
        {
            CreatePrimitive(sides, scale, Vector2.zero);
        }

        ///<summary>Creates as regular primitive polygon with the specified number of sides.</summary>
        ///<param name="sides">The number of sides in the polygon.  This must be greater than two.</param>
        ///<param name="scale">The X/Y scale of the polygon.  These must be greater than zero.</param>
        ///<param name="offset">The X/Y offset of the polygon.</param>
        public void CreatePrimitive(int sides, [DefaultValue("Vector2.one")] Vector2 scale, [DefaultValue("Vector2.zero")] Vector2 offset)
        {
            if (sides < 3)
            {
                Debug.LogWarning("Cannot create a 2D polygon primitive collider with less than two sides.", this);
                return;
            }

            if (!(scale.x > 0.0f && scale.y > 0.0f))
            {
                Debug.LogWarning("Cannot create a 2D polygon primitive collider with an axis scale less than or equal to zero.", this);
                return;
            }

            CreatePrimitive_Internal(sides, scale, offset, true);
        }

        [NativeMethod("CreatePrimitive")]
        extern private void CreatePrimitive_Internal(int sides, Vector2 scale, Vector2 offset, bool recreateCollider);

        ///<summary>Create polygon shapes using the selected sprite.</summary>
        ///<remarks>If the selected <c>sprite</c> already has its own physics outline(s) defined in the Sprite Editor then that outline will be tessellated into polygon shapes to be used here.
        ///
        ///If the selected <c>sprite</c> does not have its own physics outline(s) then a new outline will be created using the additional arguments provided. This takes additional time and in all cases, it is preferred that each <see cref="Sprite" /> has its own physics outline(s) defined.
        ///
        ///**NOTE**: If physics outline(s) are not available in the Sprite and the additional arguments are used in a player build then the <see cref="Sprite.texture" /> must have read/write enabled in the importer so it is <see cref="Texture.isReadable">readable</see>.</remarks>
        ///<param name="sprite">The sprite to extract the polygon shape data from.</param>
        ///<param name="detail">The detail used when tessellating the sprite outline, in the range [0, 1]. This is only used if the <c>sprite</c> doesn't already have its own physics outline(s) or <c>usePhysicsShapes</c> is false. This value has the same meaning as the similarly named property in the Sprite Editor.</param>
        ///<param name="alphaTolerance">The alpha tolerance used to separate the sprite from its background, in the range [0, 255]. This is only used if the <c>sprite</c> doesn't already have its own physics outline(s) or <c>usePhysicsShapes</c> is false. This value has the same meaning as the similarly named property in the Sprite Editor.</param>
        ///<param name="holeDetection">Selects whether internal holes should be detected when creating the sprite outlines. This is only used if the <c>sprite</c> doesn't already have its own physics outline(s) or <c>usePhysicsShapes</c> is false. This value has the same meaning as the similarly named property in the Sprite Editor.</param>
        ///<returns>Returns <c>true</c> if the selected sprite resulted in polygon shapes being created. Returns <c>false</c> if not, in which case the Collider will be set to a default primitive shape.</returns>
        ///<seealso cref="Sprite" />
        ///<seealso cref="Sprite.GetPhysicsOutlineCount" />
        ///<seealso cref="Sprite.GetPhysicsOutline" />
        ///<seealso cref="Sprite.GetPhysicsOutlinePointCount" />
        public bool CreateFromSprite(Sprite sprite, float detail, byte alphaTolerance, bool holeDetection)
        {
            return CreateFromSprite(sprite, detail, alphaTolerance, holeDetection, true);
        }

        ///<summary>Create polygon shapes using the selected sprite.</summary>
        ///<remarks>If the selected <c>sprite</c> already has its own physics outline(s) defined in the Sprite Editor then that outline will be tessellated into polygon shapes to be used here.
        ///
        ///If the selected <c>sprite</c> does not have its own physics outline(s) then a new outline will be created using the additional arguments provided. This takes additional time and in all cases, it is preferred that each <see cref="Sprite" /> has its own physics outline(s) defined.
        ///
        ///**NOTE**: If physics outline(s) are not available in the Sprite and the additional arguments are used in a player build then the <see cref="Sprite.texture" /> must have read/write enabled in the importer so it is <see cref="Texture.isReadable">readable</see>.</remarks>
        ///<param name="sprite">The sprite to extract the polygon shape data from.</param>
        ///<param name="detail">The detail used when tessellating the sprite outline, in the range [0, 1]. This is only used if the <c>sprite</c> doesn't already have its own physics outline(s) or <c>usePhysicsShapes</c> is false. This value has the same meaning as the similarly named property in the Sprite Editor.</param>
        ///<param name="alphaTolerance">The alpha tolerance used to separate the sprite from its background, in the range [0, 255]. This is only used if the <c>sprite</c> doesn't already have its own physics outline(s) or <c>usePhysicsShapes</c> is false. This value has the same meaning as the similarly named property in the Sprite Editor.</param>
        ///<param name="holeDetection">Selects whether internal holes should be detected when creating the sprite outlines. This is only used if the <c>sprite</c> doesn't already have its own physics outline(s) or <c>usePhysicsShapes</c> is false. This value has the same meaning as the similarly named property in the Sprite Editor.</param>
        ///<param name="usePhysicsShapes">Selects whether the outline should use the physics outline(s) defined in the <c>sprite</c>. If true, they are used (if available) however if false then they are never used even if available.</param>
        ///<returns>Returns <c>true</c> if the selected sprite resulted in polygon shapes being created. Returns <c>false</c> if not, in which case the Collider will be set to a default primitive shape.</returns>
        ///<seealso cref="Sprite" />
        ///<seealso cref="Sprite.GetPhysicsOutlineCount" />
        ///<seealso cref="Sprite.GetPhysicsOutline" />
        ///<seealso cref="Sprite.GetPhysicsOutlinePointCount" />
        public bool CreateFromSprite(Sprite sprite, [DefaultValue("0.25f")] float detail = 0.25f, [DefaultValue("200")] byte alphaTolerance = 200, [DefaultValue("true")] bool holeDetection = true, [DefaultValue("true")] bool usePhysicsShapes = true)
        {
            if (sprite == null)
            {
                Debug.LogWarning("Sprite cannot be NULL.", this);
                return false;
            }

            if (detail < 0.0f || detail > 1.0f)
            {
                Debug.LogWarning("Detail must be in the range [0, 1].", this);
                return false;
            }

            return CreateFromSprite_Internal(sprite, detail, alphaTolerance, holeDetection, true, usePhysicsShapes);
        }

        [NativeMethod("CreateFromSprite")]
        extern private bool CreateFromSprite_Internal([NotNull] Sprite sprite, float detail, byte alphaTolerance, bool holeDetection, bool recreateCollider, bool usePhysicsShapes);
    }

    ///<summary>A Collider that can merge other Colliders together.</summary>
    ///<remarks>A <see cref="CompositeCollider2D" /> merges other Colliders together when their <see cref="Collider2D.compositeOperation" /> is anything other than <see cref="Collider2D.CompositeOperation.None" />, that is, whenever a composite operation is selected.
    ///
    ///When a Composite Collider uses a Collider, the Editor will ignore and not show the <see cref="Collider2D.sharedMaterial" />, <see cref="Collider2D.isTrigger" /> &amp; <see cref="Collider2D.compositeOperation" /> properties. The same properties on the <see cref="CompositeCollider2D" /> will be used instead. You should set these properties on the Composite Collider to merge all Colliders into the Composite Collider.
    ///
    ///**NOTE**: This <see cref="Collider2D" /> cannot be disabled/enabled with the <see cref="Behaviour.enabled" /> property. Any changes to that property will be ignored.</remarks>
    [RequireComponent(typeof(Rigidbody2D))]
    [global::UnityEngine.NativeClass("CompositeCollider2D", PersistentTypeId = 66)]
    [NativeHeader("Modules/Physics2D/Public/CompositeCollider2D.h")]
    public sealed partial class CompositeCollider2D : Collider2D
    {
        ///<summary>Specifies the type of geometry the Composite Collider generates.</summary>
        ///<seealso cref="CompositeCollider2D.geometryType" />
        public enum GeometryType { ///<summary>Sets the Composite Collider 2D to generate closed outlines for the merged collider geometry consisting of only edges.</summary>
///<remarks>The outline geometry is equivalent to using an <see cref="EdgeCollider2D" /> with the chains of edges all connected. While all the edges are closed (the end edge connects to the start edge), nothing will collide in the interior of such geometry as there is no overlap of the edges. A collision or trigger will be registered only if the edges are in contact with a collider.
///
///This is usually the most efficient geometry to use as it produces far less edges. Continuous edges do not cause unwanted collisions because all edges are connected. Unwanted collisions is where two separate Colliders get in contact even though both are aligned perfectly. Use this type of geometry to produce platform surfaces where other Colliders are to move without any interference from unwanted collisions.
///
///Any interior holes caused by the the composite edges surrounding it, does not cause any interior overlap but is another closed off section of the new Composite Collider shape.</remarks>
Outlines = 0, ///<summary>Sets the Composite Collider 2D to generate closed outlines for the merged collider geometry consisting of convex polygon shapes.</summary>
///<remarks>The polygon geometry is equivalent to using an <see cref="PolygonCollider2D" /> with the polygon outlines from other colliders being merged then decomposed into multiple convex polygon shapes forming a closed outline composite. The interior of this closed outline registers collisions or triggers.
///
///This is usually the least efficient geometry to use as it produces multiple shapes or edges. These multiple shapes cause unwanted collisions when two separate colliders come in contact with each other even when they are aligned perfectly. Only use this geometry type when you need to detect the interior of the composite outline, such as when you use triggers.
///
///Any interior holes caused by forming the Composite Collider 2D does not register any collision or trigger.</remarks>
Polygons = 1 }

        ///<summary>Specifies when to generate the Composite Collider geometry.</summary>
        ///<remarks>Controls when the Composite Collider geometry is updated when a Collider used by a Composite Collider changes.</remarks>
        ///<seealso cref="CompositeCollider2D.generationType" />
        public enum GenerationType { ///<summary>Sets the Composite Collider geometry to update synchronously immediately when a Collider used by the Composite Collider changes.</summary>
Synchronous = 0, ///<summary>Sets the Composite Collider geometry to not automatically update when a Collider used by the Composite Collider changes.</summary>
///<remarks>Use this enumeration value to set the Composite Collider geometry to only be able to be updated manually when a Collider used by the Composite Collider changes.
///
///Call <see cref="CompositeCollider2D.GenerateGeometry" /> to manually update the Composite Collider.</remarks>
Manual = 1 }

        // Controls the type of geometry created by the composite.
        ///<summary>Specifies the type of geometry the Composite Collider should generate.</summary>
        ///<seealso cref="CompositeCollider2D.GeometryType" />
        extern public GeometryType geometryType { get; set; }

        // Controls when the collider generation happens.
        ///<summary>Specifies when to generate the Composite Collider geometry.</summary>
        ///<remarks>The values in this enumeration allows you to control when the Composite Collider geometry updates when a Collider of that Composite Collider changes.</remarks>
        ///<seealso cref="CompositeCollider2D.GenerationType" />
        extern public GenerationType generationType { get; set; }

        // Get/Set Delaunay mesh usage.
        ///<summary>When the value is true, the Collider uses an additional Delaunay triangulation step to produce the Collider mesh. When the value is false, this additional step does not occur.</summary>
        ///<remarks>Using Delaunay triangulation can reduce the number of shapes created in the Collider mesh and reduce the number of small triangle fans produced, both of which can improve overall physics performance.</remarks>
        extern public bool useDelaunayMesh { get; set; }

        // Controls the allowed vertex distance spacing.
        ///<summary>Controls the minimum distance allowed between generated vertices.</summary>
        ///<remarks>Controls the minimum distance allowed between generated vertices. Any vertices closer than or equal to this distance will be removed. Setting too high a distance can result in nothing being generated.</remarks>
        extern public float vertexDistance { get; set; }

        // extern public radius of the edge(s).
        ///<summary>Controls the radius of all edges created by the Collider.</summary>
        ///<remarks>The edge radius controls a radius extending around all edges of the Composite Collider. When an edge has zero radius it is effectively infinitely thin. When an edge has a radius greater than zero, each edge acts like a capsule shape with rounded ends. This results in a Composite Collider with rounded corners.
        ///
        ///It is important to know that when using <see cref="Rigidbody2D.useAutoMass" />, changing the edge radius does not change the calculated <see cref="Rigidbody2D.mass" /> even though the collision area has changed.  The mass is calculated as if the edge radius is zero i.e. not used.</remarks>
        extern public float edgeRadius { get; set; }

        // Controls the distance in which vertices are offset and clipped if within this distance
        ///<summary>Vertices are offset by this distance when compositing multiple physic shapes. Any vertices between shapes within this distance are combined.</summary>
        ///<remarks>Do not set the distance offset to higher than 1% of the Sprite's length, as this may result in a loss in detail when too many vertices are combined together.</remarks>
        extern public float offsetDistance { get; set; }

        // Generates the geometry if using manual generation type.
        ///<summary>Regenerates the Composite Collider geometry.</summary>
        ///<remarks>Call this function when you use <see cref="CompositeCollider2D.GenerationType.Manual" />.</remarks>
        extern public void GenerateGeometry();

        // Get a list of composited colliders.
        ///<summary>When any <see cref="Collider2D" /> is using any composite operation other than <see cref="Collider2D.CompositeOperation.None" /> then it is used by this <see cref="CompositeCollider2D" />.</summary>
        ///<remarks>The order of the <see cref="Collider2D" /> returned is sorted into ascending composite order as defined by <see cref="Collider2D.compositeOrder" />.</remarks>
        ///<param name="colliders">A list of Collider2D that are being composited.</param>
        ///<returns>The number of colliders returned.</returns>
        ///<seealso cref="Collider2D.compositeOperation" />
        ///<seealso cref="Collider2D.compositeOrder" />
        [NativeMethod("GetCompositedColliders_Binding")] extern public int GetCompositedColliders([NotNull][Out] List<Collider2D> colliders);

        ///<summary>TODO.</summary>
        ///<param name="allocator">The memory allocator to use for the results. This can only be Allocator.Temp, Allocator.TempJob or Allocator.Persistent.</param>
        public ColliderArray2D GetCompositedColliders(Allocator allocator = Allocator.Temp) => new(GetCompositedColliders_Internal(allocator));

        [NativeMethod("GetCompositedCollidersPhysicsBuffer_Binding")] extern private PhysicsBuffer2D GetCompositedColliders_Internal(Allocator allocator);

        // Gets the count of points in the specified path.
        ///<summary>Gets the number of points in the specified path from the Collider by its index.</summary>
        ///<param name="index">The index of the path from 0 to <see cref="pathCount" /> minus 1.</param>
        ///<returns>Returns the number of points in the path specified by <c>index</c>.</returns>
        ///<seealso cref="GetPath" />
        ///<seealso cref="pathCount" />
        public int GetPathPointCount(int index)
        {
            int maxPathIndex = pathCount - 1;
            if (index < 0 || index > maxPathIndex)
                throw new ArgumentOutOfRangeException("index", String.Format("Path index {0} must be in the range of 0 to {1}.", index, maxPathIndex));

            return GetPathPointCount_Internal(index);
        }

        [NativeMethod("GetPathPointCount_Binding")]
        extern private int GetPathPointCount_Internal(int index);

        // Get the number of paths.
        ///<summary>The number of paths in the Collider.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of a polygon. Since the polygon can have holes and discontinuous parts, its shape is not necessarily defined by a single path.</remarks>
        ///<seealso cref="GetPath" />
        extern public int pathCount { get; }

        // Get the total number of points in all paths.
        ///<summary>Gets the total number of points in all the paths within the Collider.</summary>
        ///<seealso cref="pathCount" />
        ///<seealso cref="GetPath" />
        extern public int pointCount { get; }

        // Get the specified path of points.
        ///<summary>Gets a path from the Collider by its index.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of the Collider. Since the Collider can have holes and discontinuous parts, its shape is not necessarily defined by a single path.
        ///
        ///Returns the number of points placed in the <c>points</c> array.</remarks>
        ///<param name="index">The index of the path from 0 to <see cref="pathCount" /> minus 1.</param>
        ///<param name="points">An ordered array of the vertices (points) in the selected path.</param>
        ///<returns>Returns the number of points placed in the <c>points</c> array.</returns>
        ///<seealso cref="GetPathPointCount" />
        ///<seealso cref="pathCount" />
        public int GetPath(int index, Vector2[] points)
        {
            if (index < 0 || index >= pathCount)
                throw new ArgumentOutOfRangeException("index", String.Format("Path index {0} must be in the range of 0 to {1}.", index, pathCount - 1));

            if (points == null)
                throw new ArgumentNullException("points");

            return GetPathArray_Internal(index, points);
        }

        ///<summary>Gets a path from the Collider by its index.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of the Collider. Since the Collider can have holes and discontinuous parts, its shape is not necessarily defined by a single path.
        ///
        ///The integer return value is the number of results written into the <c>results</c> list. The results list will be resized if it doesn't contain enough elements to report all the results. This prevents memory from being allocated for results when the <c>results</c> list does not need to be resized, and improves garbage collection performance when the query is performed frequently.</remarks>
        ///<param name="index">The index of the path from 0 to <see cref="pathCount" /> minus 1.</param>
        ///<param name="points">An ordered list of the vertices (points) in the selected path.</param>
        ///<returns>Returns the number of points placed in the <c>points</c> list.</returns>
        ///<seealso cref="GetPathPointCount" />
        ///<seealso cref="pathCount" />
        public int GetPath(int index, List<Vector2> points)
        {
            if (index < 0 || index >= pathCount)
                throw new ArgumentOutOfRangeException("index", String.Format("Path index {0} must be in the range of 0 to {1}.", index, pathCount - 1));

            if (points == null)
                throw new ArgumentNullException("points");

            return GetPathList_Internal(index, points);
        }

        ///<summary>Gets a path from the Collider by its index.</summary>
        ///<remarks>A path is a cyclic sequence of line segments between points that define the outline of the Collider. Since the Collider can have holes and discontinuous parts, its shape is not necessarily defined by a single path.</remarks>
        ///<param name="index">The index of the path from 0 to <see cref="pathCount" /> minus 1.</param>
        ///<param name="allocator">The memory allocator to use for the results. This can only be Allocator.Temp, Allocator.TempJob or Allocator.Persistent.</param>
        ///<returns>The NativeArray that contains an ordered list of the vertices (points) in the selected path. This must be disposed of unless it contains no results.</returns>
        ///<seealso cref="GetPathPointCount" />
        ///<seealso cref="pathCount" />
        public NativeArray<Vector2> GetPath(int index, Allocator allocator = Allocator.Temp)
        {
            if (index < 0 || index >= pathCount)
                throw new ArgumentOutOfRangeException("index", String.Format("Path index {0} must be in the range of 0 to {1}.", index, pathCount - 1));

            return GetPathPhysicsBuffer_Internal(index, allocator).ToNativeArray<Vector2>();
        }

        [NativeMethod("GetPathArray_Binding")]
        extern private int GetPathArray_Internal(int index, [NotNull] Vector2[] points);

        [NativeMethod("GetPathList_Binding")]
        extern private int GetPathList_Internal(int index, [NotNull] List<Vector2> points);

        [NativeMethod("GetPathPhysicsBuffer_Binding")]
        extern private PhysicsBuffer2D GetPathPhysicsBuffer_Internal(int index, Allocator allocator);
    }

