    public partial class Joint2D : Behaviour
    {
        // Gets the attached rigid-body.
        ///<summary>The <see cref="Rigidbody2D" /> attached to the <see cref="Joint2D" />.</summary>
        ///<remarks>
        ///  <see cref="Joint2D" /> are automatically attached to a <see cref="Rigidbody2D" /> on the same <see cref="GameObject" /> as the <see cref="Joint2D" />.</remarks>
        ///<example>
        ///  <code><![CDATA[
        ///using UnityEngine;
        ///using System.Collections;
        ///
        ///public class ExampleClass : MonoBehaviour
        ///{
        ///    public Vector2 force = Vector2.up;
        ///
        ///    void Start()
        ///    {
        ///        // Apply a force to the rigidbody attached to the joint.
        ///        GetComponent<Joint2D>().attachedRigidbody.AddForce(force);
        ///    }
        ///}
        ///]]></code>
        ///</example>
