        ///<seealso cref="anchor" />
        ///<seealso cref="connectedAnchor" />
        extern public bool autoConfigureConnectedAnchor { get; set; }
    }

    // The SpringJoint2D ensures that the two connected rigid-bodies stay at a specific distance apart using a spring system.
    ///<summary>Joint that attempts to keep two <see cref="Rigidbody2D" /> objects a set distance apart by applying a force between them.</summary>
    ///<remarks>Note that unlike DistanceJoint2D, the length of the joint can stretch and oscillate.</remarks>
    ///<seealso cref="DistanceJoint2D" />
    ///<seealso cref="HingeJoint2D" />
    ///<seealso cref="SliderJoint2D" />
    [global::UnityEngine.NativeClass("SpringJoint2D", PersistentTypeId = 231)]
    [NativeHeader("Modules/Physics2D/SpringJoint2D.h")]
    public sealed class SpringJoint2D : AnchoredJoint2D
    {
        // Should the distance be automatically calculated from the relative distance between the anchor points?
        ///<summary>Should the <c>distance</c> be calculated automatically?</summary>
        ///<remarks>When true, the <c>distance</c> property will be calculated automatically to match the distance between the <c>anchor</c> and <c>connectedAnchor</c> properties.  When false, the distance can be configured using the <c>distance</c> property.</remarks>
        ///<seealso cref="distance" />
        ///<seealso cref="AnchoredJoint2D.anchor" />
        ///<seealso cref="AnchoredJoint2D.connectedAnchor" />
        extern public bool autoConfigureDistance { get; set; }

        // The distance the joint should maintain between the two connected rigid-bodies.
        ///<summary>The distance the spring will try to keep between the two objects.</summary>
        extern public float distance { get; set; }

        // The damping ratio for the oscillation whilst trying to achieve the specified distance.  0 means no damping.  1 means critical damping.  range { 0.0, 1.0 }
        ///<summary>The amount by which the spring force is reduced in proportion to the movement speed.</summary>
        ///<remarks>The spring will oscillate with a certain frequency as it attempts to reestablish the desired distance between the objects. The higher the damping ratio, the quicker the oscillation will die down to zero.</remarks>
        ///<seealso cref="frequency" />
        extern public float dampingRatio { get; set; }

        // The frequency in Hertz for the oscillation whilst trying to achieve the specified distance.  range { 0.0, infinity }
        ///<summary>The frequency at which the spring oscillates around the distance distance between the objects.</summary>
        ///<remarks>The spring will oscillate with a certain frequency as it attempts to reestablish the desired distance between the objects. A damping ratio can be set to cause this oscillation to die down over time.</remarks>
        ///<seealso cref="dampingRatio" />
        extern public float frequency { get; set; }
    }

