        // The maximum force which the joint should use to adjust position.
        ///<summary>The maximum force that can be generated when trying to maintain the friction joint constraint.</summary>
        ///<remarks>The joint constantly tries to reduce the ::Rigidbody2D::velocity using the maximum force.  Because you can use very high force limit, you can essential reduce an objects movement to almost zero.</remarks>
        ///<seealso cref="maxTorque" />
        extern public float maxForce { get; set; }

        // The maximum torque which the joint should use to adjust rotation.
        ///<summary>The maximum torque that can be generated when trying to maintain the friction joint constraint.</summary>
        ///<remarks>The joint constantly tries to reduce the ::Rigidbody2D::angularVelocity using the maximum torque.  Because you can use very high torque limit, you can essentially reduce an objects rotation to almost zero.</remarks>
        ///<seealso cref="maxForce" />
        extern public float maxTorque { get; set; }
    }

    // The HingeJoint2D constrains the two connected rigid-bodies around the anchor points not restricting the relative rotation of them.  Can be used for wheels, rollers, chains, rag-dol joints, levers etc.
    ///<summary>Joint that allows a Rigidbody2D object to rotate around a point in space or a point on another object.</summary>
    ///<seealso cref="DistanceJoint2D" />
    ///<seealso cref="SliderJoint2D" />
    ///<seealso cref="SpringJoint2D" />
    ///<seealso cref="JointAngleLimits2D" />
    [global::UnityEngine.NativeClass("HingeJoint2D", PersistentTypeId = 233)]
    [NativeHeader("Modules/Physics2D/HingeJoint2D.h")]
    public sealed class HingeJoint2D : AnchoredJoint2D
    {
        // Setting the motor or limit automatically enabled them.

        // Enables the joint's motor.
        ///<summary>Should the joint be rotated automatically by a motor torque?</summary>
        ///<seealso cref="motor" />
